export default "n    \\\"bf16\\\": 2,\\n    \\\"fp16\\\": 2,\\n    \\\"fp32\\\": 4,\\n}\\n\\n\\nPRESETS = {\\n    \\\"gemma4_e2b\\\": {\\n        \\\"n_query_heads\\\": 8,\\n        \\\"n_kv_heads\\\": 1,\\n        \\\"head_dim\\\": 256,\\n        \\\"n_layers\\\": 35,\\n        \\\"n_kv_producing_layers\\\": 15,\\n    },\\n    \\\"gemma4_e4b\\\": {\\n        \\\"n_query_heads\\\": 8,\\n        \\\"n_kv_heads\\\": 2,\\n        \\\"head_dim\\\": 320,\\n        \\\"n_layers\\\": 42,\\n        \\\"n_kv_producing_layers\\\": 24,\\n    },\\n}\\n\\n\\ndef bytes_to_gb(n):\\n    return n / (1000 ** 3)\\n\\n\\ndef context_tick_formatter(value, _pos):\\n    labels = {\\n        256: \\\"256\\\",\\n        1024: \\\"1k\\\",\\n        4096: \\\"4k\\\",\\n        16384: \\\"16k\\\",\\n        65536: \\\"64k\\\",\\n        131072: \\\"128k\\\",\\n    }\\n    return labels.get(int(round(value)), \\\"\\\")\\n\\n\\ndef calc_kv_bytes_total(\\n    batch_size,\\n    context_length,\\n    head_dim,\\n    n_kv_heads,\\n    n_cached_layers,\\n    bytes_per_elem,\\n):\\n    return (\\n        batch_size\\n        * context_length\\n        * 2\\n        * head_dim\\n        * n_kv_heads\\n        * n_cached_layers\\n        * bytes_per_elem\\n    )\\n\\n\\ndef compute_kv_curve(\\n    context_lengths,\\n    batch_size,\\n    head_dim,\\n    n_kv_heads,\\n    n_cached_layers,\\n    bytes_per_elem,\\n):\\n    curve = []\\n    for context_length in context_lengths:\\n        total_bytes = calc_kv_bytes_total(\\n            batch_size=batch_size,\\n            context_length=context_length,\\n            head_dim=head_dim,\\n            n_kv_heads=n_kv_heads,\\n            n_cached_layers=n_cached_layers,\\n            bytes_per_elem=bytes_per_elem,\\n        )\\n        curve.append(bytes_to_gb(total_bytes))\\n    return curve\\n\\n\\ndef add_end_label(ax, x_value, y_value, text, color, y_offset=0.0):\\n    ax.text(\\n        x_value * 1.16,\\n        y_value + y_offset,\\n        text,\\n        color=color,\\n        fontsize=8,\\n        va=\\\"center\\\",\\n        ha=\\\"left\\\",\\n        clip_on=False,\\n    )\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser(\\n        formatter_class=argparse.ArgumentDefaultsHelpFormatter,\\n        description=\\\"Plot KV-cache memory for MHA, GQA, and cross-layer KV sharing\\\",\\n    )\\n    p.add_argument(\\\"--preset\\\", choices=PRESETS.keys(), default=\\\"gemma4_e4b\\\")\\n    p.add_argument(\\\"--batch_size\\\", type=int, default=1)\\n    p.add_argument(\\\"--dtype\\\", choices=DTYPE_BYTES.keys(), default=\\\"bf16\\\")\\n    p.add_argument(\\\"--output\\\", type=Path, default=None)\\n    args = p.parse_args()\\n\\n    cfg = PRESETS[args.preset]\\n    bytes_per_elem = DTYPE_BYTES[args.dtype]\\n    context_lengths = [\\n        256,\\n        512,\\n        1024,\\n        2048,\\n        4096,\\n        8192,\\n        16384,\\n        32768,\\n        65536,\\n        131072,\\n    ]\\n\\n    curves = {\\n        \\\"MHA\\\": compute_kv_curve(\\n            context_lengths,\\n            batch_size=args.batch_size,\\n            head_dim=cfg[\\\"head_dim\\\"],\\n            n_kv_heads=cfg[\\\"n_query_heads\\\"],\\n            n_cached_layers=cfg[\\\"n_layers\\\"],\\n            bytes_per_elem=bytes_per_elem,\\n        ),\\n        \\\"GQA\\\": compute_kv_curve(\\n            context_lengths,\\n            batch_size=args.batch_size,\\n            head_dim=cfg[\\\"head_dim\\\"],\\n            n_kv_heads=cfg[\\\"n_kv_heads\\\"],\\n            n_cached_layers=cfg[\\\"n_layers\\\"],\\n            bytes_per_elem=bytes_per_elem,\\n        ),\\n        \\\"GQA + KV sharing\\\": compute_kv_curve(\\n            context_lengths,\\n            batch_size=args.batch_size,\\n            head_dim=cfg[\\\"head_dim\\\"],\\n            n_kv_heads=cfg[\\\"n_kv_heads\\\"],\\n            n_cached_layers=cfg[\\\"n_kv_producing_layers\\\"],\\n            bytes_per_elem=bytes_per_elem,\\n        ),\\n    }\\n\\n    plt.rcParams.update({\\\"font.size\\\": 9})\\n    fig, ax = plt.subplots(figsize=(7.4, 4.4))\\n\\n    styles = {\\n        \\\"MHA\\\": {\\\"color\\\": \\\"#2f2f2f\\\", \\\"linewidth\\\": 2.0, \\\"zorder\\\": 3},\\n        \\\"GQA\\\": {\\\"color\\\": \\\"#6f7f8f\\\", \\\"linewidth\\\": 1.8, \\\"zorder\\\": 3},\\n        \\\"GQA + KV sharing\\\": {\\\"color\\\": \\\"#2f7ae5\\\", \\\"linewidth\\\": 2.2, \\\"zorder\\\": 4},\\n    }\\n\\n    for label, values in curves.items():\\n        ax.plot(context_lengths, values, solid_capstyle=\\\"round\\\", **styles[label])\\n\\n    max_y = max(curves[\\\"MHA\\\"]) * 1.08\\n    ax.set_xscale(\\\"log\\\", base=2)\\n    ax.set_xlim(context_lengths[0], context_lengths[-1] * 2.1)\\n    ax.set_ylim(0, max_y)\\n    ax.xaxis.set_major_locator(FixedLocator([256, 1024, 4096, 16384, 65536, 131072]))\\n    ax.xaxis.set_major_formatter(FuncFormatter(context_tick_formatter))\\n\\n    ax.set_xlabel(\\\"Context length (tokens, log scale)\\\")\\n    ax.set_ylabel(\\\"KV cache across all layers (GB)\\\")\\n    ax.set_title(\\\"GQA and KV sharing compound the KV-cache savings\\\", loc=\\\"left\\\", pad=20)\\n    ax.text(\\n        0.0,\\n        1.02,\\n        (\\n            f\\\"{args.preset}: {cfg['n_query_heads']} query heads, \\\"\\n            f\\\"{cfg['n_kv_heads']} KV heads, {cfg['n_layers']} layers, \\\"\\n            f\\\"{cfg['n_kv_producing_layers']} K/V-producing layers, \\\"\\n            f\\\"batch {args.batch_size}, {args.dtype}\\\"\\n        ),\\n        transform=ax.transAxes,\\n        fontsize=8,\\n        color=\\\"#666666\\\",\\n        ha=\\\"left\\\",\\n        va=\\\"bottom\\\",\\n    )\\n\\n    mha_128k = curves[\\\"MHA\\\"][-1]\\n    gqa_128k = curves[\\\"GQA\\\"][-1]\\n    sharing_128k = curves[\\\"GQA + KV sharing\\\"][-1]\\n\\n    ax.text(\\n        0.02,\\n        0.96,\\n        (\\n            f\\\"At 128k tokens, MHA would need {mha_128k:.1f} GB;\\\\n\\\"\\n            f\\\"GQA cuts this to {gqa_128k:.1f} GB, and KV sharing to {sharing_128k:.1f} GB.\\\"\\n        ),\\n        transform=ax.transAxes,\\n        fontsize=8,\\n        color=\\\"#333333\\\",\\n        ha=\\\"left\\\",\\n        va=\\\"top\\\",\\n        bbox={\\\"boxstyle\\\": \\\"round,pad=0.25\\\", \\\"facecolor\\\": \\\"white\\\", \\\"edgecolor\\\": \\\"none\\\"},\\n    )\\n\\n    ax.spines[\\\"top\\\"].set_visible(False)\\n    ax.spines[\\\"right\\\"].set_visible(False)\\n    ax.spines[\\\"left\\\"].set_color(\\\"#a8a8a8\\\")\\n    ax.spines[\\\"bottom\\\"].set_color(\\\"#a8a8a8\\\")\\n    ax.tick_params(axis=\\\"both\\\", which=\\\"major\\\", length=3, color=\\\"#888888\\\", labelsize=8)\\n    ax.tick_params(axis=\\\"both\\\", which=\\\"minor\\\", length=0)\\n    ax.grid(False)\\n\\n    add_end_label(ax, context_lengths[-1], mha_128k, f\\\"MHA {mha_128k:.1f} GB\\\", \\\"#2f2f2f\\\")\\n    add_end_label(ax, context_lengths[-1], gqa_128k, f\\\"GQA {gqa_128k:.1f} GB\\\", \\\"#6f7f8f\\\", 0.25)\\n    add_end_label(\\n        ax,\\n        context_lengths[-1],\\n        sharing_128k,\\n        f\\\"GQA + KV sharing {sharing_128k:.1f} GB\\\",\\n        \\\"#2f7ae5\\\",\\n        -0.25,\\n    )\\n\\n    output = args.output\\n    if output is None:\\n        output = Path(f\\\"kv_memory_mha_gqa_kvsharing_{args.preset}.pdf\\\")\\n    fig.tight_layout()\\n    fig.savefig(output)\\n    plt.close(fig)\\n    print(f\\\"Saved plot to: {output}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/10_kv-sharing/tests.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bb9dfb34b7b7f34a77155740e6cf62f4489dd9fb266ca9e3df2aa50571bffbf5\",\"content\":\"import torch\\n\\nfrom gpt_with_kv_mha import GPTModel as GPTModelMHA\\nfrom gpt_with_kv_mha import generate_text_simple_cached as generate_text_simple_cached_mha\\nfrom gpt_with_kv_sharing import GPTModel as GPTModelKVSharing\\nfrom gpt_with_kv_sharing import generate_text_simple_cached as generate_text_simple_cached_sharing\\nfrom memory_estimator_kv_sharing import calc_kv_bytes_total\\n\\n\\ndef test_kv_sharing_matches_mha_when_all_layers_produce_kv():\\n    cfg = {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 3,\\n        \\\"drop_rate\\\": 0.0,\\n        \\\"qkv_bias\\\": False,\\n    }\\n    sharing_cfg = {**cfg, \\\"n_kv_producing_layers\\\": cfg[\\\"n_layers\\\"]}\\n\\n    torch.manual_seed(123)\\n    mha_model = GPTModelMHA(cfg)\\n    sharing_model = GPTModelKVSharing(sharing_cfg)\\n    load_result = sharing_model.load_state_dict(mha_model.state_dict(), strict=True)\\n    assert not load_result.missing_keys\\n    assert not load_result.unexpected_keys\\n\\n    mha_model.eval()\\n    sharing_model.eval()\\n\\n    full_input = torch.randint(0, cfg[\\\"vocab_size\\\"], (1, cfg[\\\"context_length\\\"]))\\n    expected_logits = mha_model(full_input, use_cache=False)\\n    actual_logits = sharing_model(full_input, use_cache=False)\\n    torch.testing.assert_close(actual_logits, expected_logits, rtol=0, atol=1e-6)\\n\\n    prompt = full_input[:, :6]\\n    expected_ids = generate_text_simple_cached_mha(\\n        model=mha_model,\\n        idx=prompt.clone(),\\n        max_new_tokens=2,\\n        context_size=cfg[\\\"context_length\\\"],\\n        use_cache=True,\\n    )\\n    actual_ids = generate_text_simple_cached_sharing(\\n        model=sharing_model,\\n        idx=prompt.clone(),\\n        max_new_tokens=2,\\n        context_size=cfg[\\\"context_length\\\"],\\n        use_cache=True,\\n    )\\n    assert torch.equal(actual_ids, expected_ids)\\n\\n\\ndef test_only_producer_layers_store_kv_cache():\\n    cfg = {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 4,\\n        \\\"n_kv_producing_layers\\\": 2,\\n        \\\"drop_rate\\\": 0.0,\\n        \\\"qkv_bias\\\": False,\\n    }\\n\\n    torch.manual_seed(123)\\n    model = GPTModelKVSharing(cfg)\\n    model.eval()\\n\\n    idx = torch.randint(0, cfg[\\\"vocab_size\\\"], (1, 6))\\n    model.reset_kv_cache()\\n    logits = model(idx, use_cache=True)\\n\\n    assert not torch.isnan(logits).any()\\n    for block in model.trf_blocks[:2]:\\n        assert block.att.cache_k.size(1) == idx.size(1)\\n        assert block.att.cache_v.size(1) == idx.size(1)\\n    for block in model.trf_blocks[2:]:\\n        assert block.att.cache_k is None\\n        assert block.att.cache_v is None\\n\\n\\ndef test_memory_estimator_counts_cached_layers():\\n    batch_size = 1\\n    context_length = 128\\n    emb_dim = 32\\n    n_heads = 4\\n    n_kv_heads = 1\\n    n_cached_layers = 2\\n    bytes_per_elem = 2\\n\\n    actual = calc_kv_bytes_total(\\n        batch_size,\\n        context_length,\\n        emb_dim,\\n        n_heads,\\n        n_kv_heads,\\n        n_cached_layers,\\n        bytes_per_elem,\\n    )\\n    expected = batch_size * context_length * 8 * n_kv_heads * 2 * bytes_per_elem * n_cached_layers\\n    assert actual == expected\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b591708a6c84b76c5947a350471b0cca478487c96455bcd2eb44a3037129bb97\",\"content\":\"# Chapter 4: Implementing a GPT Model from Scratch to Generate Text\\n\\n&nbsp;\\n## Main Chapter Code\\n\\n- [01_main-chapter-code](01_main-chapter-code) contains the main chapter code.\\n\\n&nbsp;\\n## Bonus Materials\\n\\n- [02_performance-analysis](02_performance-analysis) contains optional code analyzing the performance of the GPT model(s) implemented in the main chapter\\n- [03_kv-cache](03_kv-cache) implements a KV cache to speed up the text generation during inference\\n- [07_moe](07_moe) explanation and implementation of Mixture-of-Experts (MoE)\\n- [ch05/07_gpt_to_llama](../ch05/07_gpt_to_llama) contains a step-by-step guide for converting a GPT architecture implementation to Llama 3.2 and loads pretrained weights from Meta AI (it might be interesting to look at alternative architectures after completing chapter 4, but you can also save that for after reading chapter 5)\\n\\n\\n&nbsp;\\n## Attention Alternatives\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/attention-alternatives/attention-alternatives.webp\\\">\\n\\n&nbsp;\\n\\n- [04_gqa](04_gqa) contains an introduction to Grouped-Query Attention (GQA), which is used by most modern LLMs (Llama 4, gpt-oss, Qwen3, Gemma 3, and many more) as alternative to regular Multi-Head Attention (MHA)\\n- [05_mla](05_mla) contains an introduction to Multi-Head Latent Attention (MLA), which is used by DeepSeek V3, as alternative to regular Multi-Head Attention (MHA)\\n- [06_swa](06_swa) contains an introduction to Sliding Window Attention (SWA), which is used by Gemma 3 and others\\n- [08_deltanet](08_deltanet) explanation of Gated DeltaNet as a popular linear attention variant (used in Qwen3-Next and Kimi Linear)\\n- [10_kv-sharing](10_kv-sharing) contains an introduction to cross-layer KV sharing, which is used by Gemma 4 E2B and E4B to reduce KV-cache memory\\n\\n\\n&nbsp;\\n## More\\n\\nIn the video below, I provide a code-along session that covers some of the chapter contents as supplementary material.\\n\\n<br>\\n<br>\\n\\n[![Link to the video](https://img.youtube.com/vi/YSAkgEarBGE/0.jpg)](https://www.youtube.com/watch?v=YSAkgEarBGE)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/01_main-chapter-code/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6c80d7570c325f610105db09971bf91d267d57feded14f8bc999bbab00280e5a\",\"content\":\"# Chapter 5: Pretraining on Unlabeled Data\\n\\n### Main Chapter Code\\n\\n- [ch05.ipynb](ch05.ipynb) contains all the code as it appears in the chapter\\n- [previous_chapters.py](previous_chapters.py) is a Python module that contains the `MultiHeadAttention` module and `GPTModel` class from the previous chapters, which we import in [ch05.ipynb](ch05.ipynb) to pretrain the GPT model\\n- [gpt_download.py](gpt_download.py) contains the utility functions for downloading the pretrained GPT model weights\\n- [exercise-solutions.ipynb](exercise-solutions.ipynb) contains the exercise solutions for this chapter\\n\\n### Optional Code\\n\\n- [gpt_train.py](gpt_train.py) is a standalone Python script file with the code that we implemented in [ch05.ipynb](ch05.ipynb) to train the GPT model (you can think of it as a code file summarizing this chapter)\\n- [gpt_generate.py](gpt_generate.py) is a standalone Python script file with the code that we implemented in [ch05.ipynb](ch05.ipynb) to load and use the pretrained model weights from OpenAI\\n\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/01_main-chapter-code/gpt_download.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3e2e95f7c3bf188e16e33e23fc9f0b1d285da55931f15fe12174d32cf10ec076\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n\\nimport os\\n\\nimport requests\\nimport json\\nimport numpy as np\\nimport tensorflow as tf\\nfrom tqdm import tqdm\\n\\n\\ndef download_and_load_gpt2(model_size, models_dir):\\n    # Validate model size\\n    allowed_sizes = (\\\"124M\\\", \\\"355M\\\", \\\"774M\\\", \\\"1558M\\\")\\n    if model_size not in allowed_sizes:\\n        raise ValueError(f\\\"Model size not in {allowed_sizes}\\\")\\n\\n    # Define paths\\n    model_dir = os.path.join(models_dir, model_size)\\n    base_url = \\\"https://openaipublic.blob.core.windows.net/gpt-2/models\\\"\\n    backup_base_url = \\\"https://f001.backblazeb2.com/file/LLMs-from-scratch/gpt2\\\"\\n    filenames = [\\n        \\\"checkpoint\\\", \\\"encoder.json\\\", \\\"hparams.json\\\",\\n        \\\"model.ckpt.data-00000-of-00001\\\", \\\"model.ckpt.index\\\",\\n        \\\"model.ckpt.meta\\\", \\\"vocab.bpe\\\"\\n    ]\\n\\n    # Download files\\n    os.makedirs(model_dir, exist_ok=True)\\n    for filename in filenames:\\n        file_url = os.path.join(base_url, model_size, filename)\\n        backup_url = os.path.join(backup_base_url, model_size, filename)\\n        file_path = os.path.join(model_dir, filename)\\n        download_file(file_url, file_path, backup_url)\\n\\n    # Load settings and params\\n    tf_ckpt_path = tf.train.latest_checkpoint(model_dir)\\n    settings = json.load(open(os.path.join(model_dir, \\\"hparams.json\\\"), \\\"r\\\", encoding=\\\"utf-8\\\"))\\n    params = load_gpt2_params_from_tf_ckpt(tf_ckpt_path, settings)\\n\\n    return settings, params\\n\\n\\ndef download_file(url, destination, backup_url=None):\\n    def _attempt_download(download_url):\\n        response = requests.get(download_url, stream=True, timeout=60)\\n        response.raise_for_status()\\n\\n        file_size = int(response.headers.get(\\\"Content-Length\\\", 0))\\n\\n        # Check if file exists and has same size\\n        if os.path.exists(destination):\\n            file_size_local = os.path.getsize(destination)\\n            if file_size and file_size == file_size_local:\\n                print(f\\\"File already exists and is up-to-date: {destination}\\\")\\n                return True\\n\\n        block_size = 1024  # 1 KB\\n        desc = os.path.basename(download_url)\\n        with tqdm(total=file_size, unit=\\\"iB\\\", unit_scale=True, desc=desc) as progress_bar:\\n            with open(destination, \\\"wb\\\") as file:\\n                for chunk in response.iter_content(chunk_size=block_size):\\n                    if chunk:\\n                        file.write(chunk)\\n                        progress_bar.update(len(chunk))\\n        return True\\n\\n    try:\\n        if _attempt_download(url):\\n            return\\n    except requests.exceptions.RequestException:\\n        if backup_url is not None:\\n            print(f\\\"Primary URL ({url}) failed. Attempting backup URL: {backup_url}\\\")\\n            try:\\n                if _attempt_download(backup_url):\\n                    return\\n            except requests.exceptions.RequestException:\\n                pass\\n\\n        error_message = (\\n            f\\\"Failed to download from both primary URL ({url})\\\"\\n            f\\\"{' and backup URL (' + backup_url + ')' if backup_url else ''}.\\\"\\n            \\\"\\\\nCheck your internet connection or the file availability.\\\\n\\\"\\n            \\\"For help, visit: https://github.com/rasbt/LLMs-from-scratch/discussions/273\\\"\\n        )\\n        print(error_message)\\n    except Exception as e:\\n        print(f\\\"An unexpected error occurred: {e}\\\")\\n\\n\\n# Alternative way using `requests`\\n\\\"\\\"\\\"\\ndef download_file(url, destination):\\n    # Send a GET request to download the file in streaming mode\\n    response = requests.get(url, stream=True)\\n\\n    # Get the total file size from headers, defaulting to 0 if not present\\n    file_size = int(response.headers.get(\\\"content-length\\\", 0))\\n\\n    # Check if file exists and has the same size\\n    if os.path.exists(destination):\\n        file_size_local = os.path.getsize(destination)\\n        if file_size == file_size_local:\\n            print(f\\\"File already exists and is up-to-date: {destination}\\\")\\n            return\\n\\n    # Define the block size for reading the file\\n    block_size = 1024  # 1 Kilobyte\\n\\n    # Initialize the progress bar with total file size\\n    progress_bar_description = url.split(\\\"/\\\")[-1]  # Extract filename from URL\\n    with tqdm(total=file_size, unit=\\\"iB\\\", unit_scale=True, desc=progress_bar_description) as progress_bar:\\n        # Open the destination file in binary write mode\\n        with open(destination, \\\"wb\\\") as file:\\n            # Iterate over the file data in chunks\\n            for chunk in response.iter_content(block_size):\\n                progress_bar.update(len(chunk))  # Update progress bar\\n                file.write(chunk)  # Write the chunk to the file\\n\\\"\\\"\\\"\\n\\n\\ndef load_gpt2_params_from_tf_ckpt(ckpt_path, settings):\\n    # Initialize parameters dictionary with empty blocks for each layer\\n    params = {\\\"blocks\\\": [{} for _ in range(settings[\\\"n_layer\\\"])]}\\n\\n    # Iterate over each variable in the checkpoint\\n    for name, _ in tf.train.list_variables(ckpt_path):\\n        # Load the variable and remove singleton dimensions\\n        variable_array = np.squeeze(tf.train.load_variable(ckpt_path, name))\\n\\n        # Process the variable name to extract relevant parts\\n        variable_name_parts = name.split(\\\"/\\\")[1:]  # Skip the 'model/' prefix\\n\\n        # Identify the target dictionary for the variable\\n        target_dict = params\\n        if variable_name_parts[0].startswith(\\\"h\\\"):\\n            layer_number = int(variable_name_parts[0][1:])\\n            target_dict = params[\\\"blocks\\\"][layer_number]\\n\\n        # Recursively access or create nested dictionaries\\n        for key in variable_name_parts[1:-1]:\\n            target_dict = target_dict.setdefault(key, {})\\n\\n        # Assign the variable array to the last key\\n        last_key = variable_name_parts[-1]\\n        target_dict[last_key] = variable_array\\n\\n    return params\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/01_main-chapter-code/gpt_generate.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c3bbfe9463f81cc65962c561d9b2bc9b9af11f623d13df1a9c0ef608a507ed7b\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport argparse\\nimport json\\nimport numpy as np\\nimport os\\n\\nimport requests\\nimport tensorflow as tf\\nimport tiktoken\\nimport torch\\nfrom tqdm import tqdm\\n\\n# Import from local files\\nfrom previous_chapters import GPTModel\\n\\n\\ndef text_to_token_ids(text, tokenizer):\\n    encoded = tokenizer.encode(text)\\n    encoded_tensor = torch.tensor(encoded).unsqueeze(0)  # add batch dimension\\n    return encoded_tensor\\n\\n\\ndef token_ids_to_text(token_ids, tokenizer):\\n    flat = token_ids.squeeze(0)  # remove batch dimension\\n    return tokenizer.decode(flat.tolist())\\n\\n\\ndef download_and_load_gpt2(model_size, models_dir):\\n    # Validate model size\\n    allowed_sizes = (\\\"124M\\\", \\\"355M\\\", \\\"774M\\\", \\\"1558M\\\")\\n    if model_size not in allowed_sizes:\\n        raise ValueError(f\\\"Model size not in {allowed_sizes}\\\")\\n\\n    # Define paths\\n    model_dir = os.path.join(models_dir, model_size)\\n    base_url = \\\"https://openaipublic.blob.core.windows.net/gpt-2/models\\\"\\n    filenames = [\\n        \\\"checkpoint\\\", \\\"encoder.json\\\", \\\"hparams.json\\\",\\n        \\\"model.ckpt.data-00000-of-00001\\\", \\\"model.ckpt.index\\\",\\n        \\\"model.ckpt.meta\\\", \\\"vocab.bpe\\\"\\n    ]\\n\\n    # Download files\\n    os.makedirs(model_dir, exist_ok=True)\\n    for filename in filenames:\\n        file_url = os.path.join(base_url, model_size, filename)\\n        file_path = os.path.join(model_dir, filename)\\n        download_file(file_url, file_path)\\n\\n    # Load settings and params\\n    tf_ckpt_path = tf.train.latest_checkpoint(model_dir)\\n    settings = json.load(open(os.path.join(model_dir, \\\"hparams.json\\\")))\\n    params = load_gpt2_params_from_tf_ckpt(tf_ckpt_path, settings)\\n\\n    return settings, params\\n\\n\\ndef download_file(url, destination):\\n    # Send a GET request to download the file\\n    response = requests.get(url, stream=True, timeout=60)\\n    response.raise_for_status()\\n\\n    # Get the total file size from headers, defaulting to 0 if not present\\n    file_size = int(response.headers.get(\\\"Content-Length\\\", 0))\\n\\n    # Check if file exists and has the same size\\n    if os.path.exists(destination):\\n        file_size_local = os.path.getsize(destination)\\n        if file_size and file_size == file_size_local:\\n            print(f\\\"File already exists and is up-to-date: {destination}\\\")\\n            return\\n\\n    # Define the block size for reading the file\\n    block_size = 1024  # 1 Kilobyte\\n\\n    # Initialize the progress bar with total file size\\n    progress_bar_description = os.path.basename(url)\\n    with tqdm(total=file_size, unit=\\\"iB\\\", unit_scale=True, desc=progress_bar_description) as progress_bar:\\n        # Open the destination file in binary write mode\\n        with open(destination, \\\"wb\\\") as file:\\n            for chunk in response.iter_content(chunk_size=block_size):\\n                if chunk:\\n                    file.write(chunk)\\n                    progress_bar.update(len(chunk))  # Update progress bar\\n\\n\\ndef load_gpt2_params_from_tf_ckpt(ckpt_path, settings):\\n    # Initialize parameters dictionary with empty blocks for each layer\\n    params = {\\\"blocks\\\": [{} for _ in range(settings[\\\"n_layer\\\"])]}\\n\\n    # Iterate over each variable in the checkpoint\\n    for name, _ in tf.train.list_variables(ckpt_path):\\n        # Load the variable and remove singleton dimensions\\n        variable_array = np.squeeze(tf.train.load_variable(ckpt_path, name))\\n\\n        # Process the variable name to extract relevant parts\\n        variable_name_parts = name.split(\\\"/\\\")[1:]  # Skip the 'model/' prefix\\n\\n        # Identify the target dictionary for the variable\\n        target_dict = params\\n        if variable_name_parts[0].startswith(\\\"h\\\"):\\n            layer_number = int(variable_name_parts[0][1:])\\n            target_dict = params[\\\"blocks\\\"][layer_number]\\n\\n        # Recursively access or create nested dictionaries\\n        for key in variable_name_parts[1:-1]:\\n            target_dict = target_dict.setdefault(key, {})\\n\\n        # Assign the variable array to the last key\\n        last_key = variable_name_parts[-1]\\n        target_dict[last_key] = variable_array\\n\\n    return params\\n\\n\\ndef assign(left, right):\\n    if left.shape != right.shape:\\n        raise ValueError(f\\\"Shape mismatch. Left: {left.shape}, Right: {right.shape}\\\")\\n    return torch.nn.Parameter(torch.tensor(right))\\n\\n\\ndef load_weights_into_gpt(gpt, params):\\n    gpt.pos_emb.weight = assign(gpt.pos_emb.weight, params[\\\"wpe\\\"])\\n    gpt.tok_emb.weight = assign(gpt.tok_emb.weight, params[\\\"wte\\\"])\\n\\n    for b in range(len(params[\\\"blocks\\\"])):\\n        q_w, k_w, v_w = np.split(\\n            (params[\\\"blocks\\\"][b][\\\"attn\\\"][\\\"c_attn\\\"])[\\\"w\\\"], 3, axis=-1)\\n        gpt.trf_blocks[b].att.W_query.weight = assign(\\n            gpt.trf_blocks[b].att.W_query.weight, q_w.T)\\n        gpt.trf_blocks[b].att.W_key.weight = assign(\\n            gpt.trf_blocks[b].att.W_key.weight, k_w.T)\\n        gpt.trf_blocks[b].att.W_value.weight = assign(\\n            gpt.trf_blocks[b].att.W_value.weight, v_w.T)\\n\\n        q_b, k_b, v_b = np.split(\\n            (params[\\\"blocks\\\"][b][\\\"attn\\\"][\\\"c_attn\\\"])[\\\"b\\\"], 3, axis=-1)\\n        gpt.trf_blocks[b].att.W_query.bias = assign(\\n            gpt.trf_blocks[b].att.W_query.bias, q_b)\\n        gpt.trf_blocks[b].att.W_key.bias = assign(\\n            gpt.trf_blocks[b].att.W_key.bias, k_b)\\n        gpt.trf_blocks[b].att.W_value.bias = assign(\\n            gpt.trf_blocks[b].att.W_value.bias, v_b)\\n\\n        gpt.trf_blocks[b].att.out_proj.weight = assign(\\n            gpt.trf_blocks[b].att.out_proj.weight,\\n            params[\\\"blocks\\\"][b][\\\"attn\\\"][\\\"c_proj\\\"][\\\"w\\\"].T)\\n        gpt.trf_blocks[b].att.out_proj.bias = assign(\\n            gpt.trf_blocks[b].att.out_proj.bias,\\n            params[\\\"blocks\\\"][b][\\\"attn\\\"][\\\"c_proj\\\"][\\\"b\\\"])\\n\\n        gpt.trf_blocks[b].ff.layers[0].weight = assign(\\n            gpt.trf_blocks[b].ff.layers[0].weight,\\n            params[\\\"blocks\\\"][b][\\\"mlp\\\"][\\\"c_fc\\\"][\\\"w\\\"].T)\\n        gpt.trf_blocks[b].ff.layers[0].bias = assign(\\n            gpt.trf_blocks[b].ff.layers[0].bias,\\n            params[\\\"blocks\\\"][b][\\\"mlp\\\"][\\\"c_fc\\\"][\\\"b\\\"])\\n        gpt.trf_blocks[b].ff.layers[2].weight = assign(\\n            gpt.trf_blocks[b].ff.layers[2].weight,\\n            params[\\\"blocks\\\"][b][\\\"mlp\\\"][\\\"c_proj\\\"][\\\"w\\\"].T)\\n        gpt.trf_blocks[b].ff.layers[2].bias = assign(\\n            gpt.trf_blocks[b].ff.layers[2].bias,\\n            params[\\\"blocks\\\"][b][\\\"mlp\\\"][\\\"c_proj\\\"][\\\"b\\\"])\\n\\n        gpt.trf_blocks[b].norm1.scale = assign(\\n            gpt.trf_blocks[b].norm1.scale,\\n            params[\\\"blocks\\\"][b][\\\"ln_1\\\"][\\\"g\\\"])\\n        gpt.trf_blocks[b].norm1.shift = assign(\\n            gpt.trf_blocks[b].norm1.shift,\\n            params[\\\"blocks\\\"][b][\\\"ln_1\\\"][\\\"b\\\"])\\n        gpt.trf_blocks[b].norm2.scale = assign(\\n            gpt.trf_blocks[b].norm2.scale,\\n            params[\\\"blocks\\\"][b][\\\"ln_2\\\"][\\\"g\\\"])\\n        gpt.trf_blocks[b].norm2.shift = assign(\\n            gpt.trf_blocks[b].norm2.shift,\\n            params[\\\"blocks\\\"][b][\\\"ln_2\\\"][\\\"b\\\"])\\n\\n    gpt.final_norm.scale = assign(gpt.final_norm.scale, params[\\\"g\\\"])\\n    gpt.final_norm.shift = assign(gpt.final_norm.shift, params[\\\"b\\\"])\\n    gpt.out_head.weight = assign(gpt.out_head.weight, params[\\\"wte\\\"])\\n\\n\\ndef generate(model, idx, max_new_tokens, context_size, temperature=0.0, top_k=None, eos_id=None):\\n\\n    if eos_id is not None and idx.shape[0] != 1:\\n        raise ValueError(\\\"EOS stopping currently supports batch size 1 only\\\")\\n\\n    # For-loop is the same as before: Get logits, and only focus on last time step\\n    for _ in range(max_new_tokens):\\n        idx_cond = idx[:, -context_size:]\\n        with torch.no_grad():\\n            logits = model(idx_cond)\\n        logits = logits[:, -1, :]\\n\\n        # New: Filter logits with top_k sampling\\n        if top_k is not None:\\n            # Keep only top_k values\\n            top_logits, _ = torch.topk(logits, top_k)\\n            min_val = top_logits[:, -1]\\n            logits = torch.where(logits < min_val, torch.tensor(float(\\\"-inf\\\")).to(logits.device), logits)\\n\\n        # New: Apply temperature scaling\\n        if temperature > 0.0:\\n            logits = logits / temperature\\n\\n            # New (not in book): numerical stability tip to get equivalent results on mps device\\n            # subtract rowwise max before softmax\\n            logits = logits - logits.max(dim=-1, keepdim=True).values\\n\\n            # Apply softmax to get probabilities\\n            probs = torch.softmax(logits, dim=-1)  # (batch_size, context_len)\\n\\n            # Sample from the distribution\\n            idx_next = torch.multinomial(probs, num_samples=1)  # (batch_size, 1)\\n\\n        # Otherwise same as before: get idx of the vocab entry with the highest logits value\\n        else:\\n            idx_next = torch.argmax(logits, dim=-1, keepdim=True)  # (batch_size, 1)\\n\\n        if idx_next == eos_id:  # Stop generating early if end-of-sequence token is encountered and eos_id is specified\\n            break\\n\\n        # Same as before: append sampled index to the running sequence\\n        idx = torch.cat((idx, idx_next), dim=1)  # (batch_size, num_tokens+1)\\n\\n    return idx\\n\\n\\ndef main(gpt_config, input_prompt, model_size, device):\\n\\n    settings, params = download_and_load_gpt2(model_size=model_size, models_dir=\\\"gpt2\\\")\\n\\n    gpt = GPTModel(gpt_config)\\n    load_weights_into_gpt(gpt, params)\\n    gpt.to(device)\\n    gpt.eval()\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    torch.manual_seed(123)\\n\\n    token_ids = generate(\\n        model=gpt,\\n        idx=text_to_token_ids(input_prompt, tokenizer).to(device),\\n        max_new_tokens=25,\\n        context_size=gpt_config[\\\"context_length\\\"],\\n        top_k=50,\\n        temperature=1.0\\n    )\\n\\n    print(\\\"Output text:\\\\n\\\", token_ids_to_text(token_ids, tokenizer))\\n\\n\\nif __name__ == \\\"__main__\\\":\\n\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Generate text with a pretrained GPT-2 model.\\\")\\n    parser.add_argument(\\n        \\\"--prompt\\\",\\n        default=\\\"Every effort moves you\\\",\\n        help=\\\"Prompt text used to seed the generation.\\\"\\n    )\\n    parser.add_argument(\\n        \\\"--device\\\",\\n        default=\\\"cpu\\\",\\n        help=\\\"Device for running inference, e.g., cpu, cuda, mps, or auto.\\\"\\n    )\\n\\n    args = parser.parse_args()\\n\\n\\n    torch.manual_seed(123)\\n\\n    CHOOSE_MODEL = \\\"gpt2-small (124M)\\\"\\n    INPUT_PROMPT = args.prompt\\n    DEVICE = torch.device(args.device)\\n\\n    print(\\\"PyTorch:\\\", torch.__version__)\\n    print(\\\"Device:\\\", DEVICE)\\n\\n\\n    BASE_CONFIG = {\\n        \\\"vocab_size\\\": 50257,     # Vocabulary size\\n        \\\"context_length\\\": 1024,  # Context length\\n        \\\"drop_rate\\\": 0.0,        # Dropout rate\\n        \\\"qkv_bias\\\": True         # Query-key-value bias\\n    }\\n\\n    model_configs = {\\n        \\\"gpt2-small (124M)\\\": {\\\"emb_dim\\\": 768, \\\"n_layers\\\": 12, \\\"n_heads\\\": 12},\\n        \\\"gpt2-medium (355M)\\\": {\\\"emb_dim\\\": 1024, \\\"n_layers\\\": 24, \\\"n_heads\\\": 16},\\n        \\\"gpt2-large (774M)\\\": {\\\"emb_dim\\\": 1280, \\\"n_layers\\\": 36, \\\"n_heads\\\": 20},\\n        \\\"gpt2-xl (1558M)\\\": {\\\"emb_dim\\\": 1600, \\\"n_layers\\\": 48, \\\"n_heads\\\": 25},\\n    }\\n\\n    model_size = CHOOSE_MODEL.split(\\\" \\\")[-1].lstrip(\\\"(\\\").rstrip(\\\")\\\")\\n\\n    BASE_CONFIG.update(model_configs[CHOOSE_MODEL])\\n\\n    main(BASE_CONFIG, INPUT_PROMPT, model_size, DEVICE)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/01_main-chapter-code/gpt_train.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"54623631dd9e9d50f7be63df4fd83220431815e3001f6b7b8750b2b03984ec59\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport matplotlib.pyplot as plt\\nimport os\\nimport requests\\nimport torch\\nimport tiktoken\\n\\n\\n# Import from local files\\nfrom previous_chapters import GPTModel, create_dataloader_v1, generate_text_simple\\n\\n\\ndef text_to_token_ids(text, tokenizer):\\n    encoded = tokenizer.encode(text)\\n    encoded_tensor = torch.tensor(encoded).unsqueeze(0)  # add batch dimension\\n    return encoded_tensor\\n\\n\\ndef token_ids_to_text(token_ids, tokenizer):\\n    flat = token_ids.squeeze(0)  # remove batch dimension\\n    return tokenizer.decode(flat.tolist())\\n\\n\\ndef calc_loss_batch(input_batch, target_batch, model, device):\\n    input_batch, target_batch = input_batch.to(device), target_batch.to(device)\\n    logits = model(input_batch)\\n    loss = torch.nn.functional.cross_entropy(logits.flatten(0, 1), target_batch.flatten())\\n    return loss\\n\\n\\ndef calc_loss_loader(data_loader, model, device, num_batches=None):\\n    total_loss = 0.\\n    if len(data_loader) == 0:\\n        return float(\\\"nan\\\")\\n    elif num_batches is None:\\n        num_batches = len(data_loader)\\n    else:\\n        num_batches = min(num_batches, len(data_loader))\\n    for i, (input_batch, target_batch) in enumerate(data_loader):\\n        if i < num_batches:\\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\\n            total_loss += loss.item()\\n        else:\\n            break\\n    return total_loss / num_batches\\n\\n\\ndef evaluate_model(model, train_loader, val_loader, device, eval_iter):\\n    model.eval()\\n    with torch.no_grad():\\n        train_loss = calc_loss_loader(train_loader, model, device, num_batches=eval_iter)\\n        val_loss = calc_loss_loader(val_loader, model, device, num_batches=eval_iter)\\n    model.train()\\n    return train_loss, val_loss\\n\\n\\ndef generate_and_print_sample(model, tokenizer, device, start_context):\\n    model.eval()\\n    context_size = model.pos_emb.weight.shape[0]\\n    encoded = text_to_token_ids(start_context, tokenizer).to(device)\\n    with torch.no_grad():\\n        token_ids = generate_text_simple(\\n            model=model, idx=encoded,\\n            max_new_tokens=50, context_size=context_size\\n        )\\n        decoded_text = token_ids_to_text(token_ids, tokenizer)\\n        print(decoded_text.replace(\\\"\\\\n\\\", \\\" \\\"))  # Compact print format\\n    model.train()\\n\\n\\ndef train_model_simple(model, train_loader, val_loader, optimizer, device, num_epochs,\\n                       eval_freq, eval_iter, start_context, tokenizer):\\n    # Initialize lists to track losses and tokens seen\\n    train_losses, val_losses, track_tokens_seen = [], [], []\\n    tokens_seen = 0\\n    global_step = -1\\n\\n    # Main training loop\\n    for epoch in range(num_epochs):\\n        model.train()  # Set model to training mode\\n\\n        for input_batch, target_batch in train_loader:\\n            optimizer.zero_grad()  # Reset loss gradients from previous batch iteration\\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\\n            loss.backward()  # Calculate loss gradients\\n            optimizer.step()  # Update model weights using loss gradients\\n            tokens_seen += input_batch.numel()\\n            global_step += 1\\n\\n            # Optional evaluation step\\n            if global_step % eval_freq == 0:\\n                train_loss, val_loss = evaluate_model(\\n                    model, train_loader, val_loader, device, eval_iter)\\n                train_losses.append(train_loss)\\n                val_losses.append(val_loss)\\n                track_tokens_seen.append(tokens_seen)\\n                print(f\\\"Ep {epoch+1} (Step {global_step:06d}): \\\"\\n                      f\\\"Train loss {train_loss:.3f}, Val loss {val_loss:.3f}\\\")\\n\\n        # Print a sample text after each epoch\\n        generate_and_print_sample(\\n            model, tokenizer, device, start_context\\n        )\\n\\n    return train_losses, val_losses, track_tokens_seen\\n\\n\\ndef plot_losses(epochs_seen, tokens_seen, train_losses, val_losses):\\n    fig, ax1 = plt.subplots()\\n\\n    # Plot training and validation loss against epochs\\n    ax1.plot(epochs_seen, train_losses, label=\\\"Training loss\\\")\\n    ax1.plot(epochs_seen, val_losses, linestyle=\\\"-.\\\", label=\\\"Validation loss\\\")\\n    ax1.set_xlabel(\\\"Epochs\\\")\\n    ax1.set_ylabel(\\\"Loss\\\")\\n    ax1.legend(loc=\\\"upper right\\\")\\n\\n    # Create a second x-axis for tokens seen\\n    ax2 = ax1.twiny()  # Create a second x-axis that shares the same y-axis\\n    ax2.plot(tokens_seen, train_losses, alpha=0)  # Invisible plot for aligning ticks\\n    ax2.set_xlabel(\\\"Tokens seen\\\")\\n\\n    fig.tight_layout()  # Adjust layout to make room\\n    # plt.show()\\n\\n\\ndef main(gpt_config, settings):\\n\\n    torch.manual_seed(123)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n\\n    ##############################\\n    # Download data if necessary\\n    ##############################\\n\\n    file_path = \\\"the-verdict.txt\\\"\\n    url = \\\"https://raw.githubusercontent.com/rasbt/LLMs-from-scratch/main/ch02/01_main-chapter-code/the-verdict.txt\\\"\\n\\n    if not os.path.exists(file_path):\\n        response = requests.get(url, timeout=30)\\n        response.raise_for_status()\\n        text_data = response.text\\n        with open(file_path, \\\"w\\\", encoding=\\\"utf-8\\\") as file:\\n            file.write(text_data)\\n    else:\\n        with open(file_path, \\\"r\\\", encoding=\\\"utf-8\\\") as file:\\n            text_data = file.read()\\n    ##############################\\n    # Initialize model\\n    ##############################\\n\\n    model = GPTModel(gpt_config)\\n    model.to(device)  # no assignment model = model.to(device) necessary for nn.Module classes\\n    optimizer = torch.optim.AdamW(\\n        model.parameters(), lr=settings[\\\"learning_rate\\\"], weight_decay=settings[\\\"weight_decay\\\"]\\n    )\\n\\n    ##############################\\n    # Set up dataloaders\\n    ##############################\\n\\n    # Train/validation ratio\\n    train_ratio = 0.90\\n    split_idx = int(train_ratio * len(text_data))\\n\\n    train_loader = create_dataloader_v1(\\n        text_data[:split_idx],\\n        batch_size=settings[\\\"batch_size\\\"],\\n        max_length=gpt_config[\\\"context_length\\\"],\\n        stride=gpt_config[\\\"context_length\\\"],\\n        drop_last=True,\\n        shuffle=True,\\n        num_workers=0\\n    )\\n\\n    val_loader = create_dataloader_v1(\\n        text_data[split_idx:],\\n        batch_size=settings[\\\"batch_size\\\"],\\n        max_length=gpt_config[\\\"context_length\\\"],\\n        stride=gpt_config[\\\"context_length\\\"],\\n        drop_last=False,\\n        shuffle=False,\\n        num_workers=0\\n    )\\n\\n    ##############################\\n    # Train model\\n    ##############################\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n\\n    train_losses, val_losses, tokens_seen = train_model_simple(\\n        model, train_loader, val_loader, optimizer, device,\\n        num_epochs=settings[\\\"num_epochs\\\"], eval_freq=5, eval_iter=1,\\n        start_context=\\\"Every effort moves you\\\", tokenizer=tokenizer\\n    )\\n\\n    return train_losses, val_losses, tokens_seen, model\\n\\n\\nif __name__ == \\\"__main__\\\":\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,    # Vocabulary size\\n        \\\"context_length\\\": 256,  # Shortened context length (orig: 1024)\\n        \\\"emb_dim\\\": 768,         # Embedding dimension\\n        \\\"n_heads\\\": 12,          # Number of attention heads\\n        \\\"n_layers\\\": 12,         # Number of layers\\n        \\\"drop_rate\\\": 0.1,       # Dropout rate\\n        \\\"qkv_bias\\\": False       # Query-key-value bias\\n    }\\n\\n    OTHER_SETTINGS = {\\n        \\\"learning_rate\\\": 5e-4,\\n        \\\"num_epochs\\\": 10,\\n        \\\"batch_size\\\": 2,\\n        \\\"weight_decay\\\": 0.1\\n    }\\n\\n    ###########################\\n    # Initiate training\\n    ###########################\\n\\n    train_losses, val_losses, tokens_seen, model = main(GPT_CONFIG_124M, OTHER_SETTINGS)\\n\\n    ###########################\\n    # After training\\n    ###########################\\n\\n    # Plot results\\n    epochs_tensor = torch.linspace(0, OTHER_SETTINGS[\\\"num_epochs\\\"], len(train_losses))\\n    plot_losses(epochs_tensor, tokens_seen, train_losses, val_losses)\\n    plt.savefig(\\\"loss.pdf\\\")\\n\\n    # Save and load model\\n    torch.save(model.state_dict(), \\\"model.pth\\\")\\n    model = GPTModel(GPT_CONFIG_124M)\\n    model.load_state_dict(torch.load(\\\"model.pth\\\", weights_only=True))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/01_main-chapter-code/previous_chapters.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d611a73cb4e6eaeb8f46e18e9bcdb56d3b9d24f5db037300c73ac23973ec7e6f\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n#\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 2-4.\\n# This file can be run as a standalone script.\\n\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\nfrom torch.utils.data import Dataset, DataLoader\\n\\n#####################################\\n# Chapter 2\\n#####################################\\n\\n\\nclass GPTDatasetV1(Dataset):\\n    def __init__(self, txt, tokenizer, max_length, stride):\\n        self.input_ids = []\\n        self.target_ids = []\\n\\n        # Tokenize the entire text\\n        token_ids = tokenizer.encode(txt, allowed_special={\\\"<|endoftext|>\\\"})\\n\\n        # Use a sliding window to chunk the book into overlapping sequences of max_length\\n        for i in range(0, len(token_ids) - max_length, stride):\\n            input_chunk = token_ids[i:i + max_length]\\n            target_chunk = token_ids[i + 1: i + max_length + 1]\\n            self.input_ids.append(torch.tensor(input_chunk))\\n            self.target_ids.append(torch.tensor(target_chunk))\\n\\n    def __len__(self):\\n        return len(self.input_ids)\\n\\n    def __getitem__(self, idx):\\n        return self.input_ids[idx], self.target_ids[idx]\\n\\n\\ndef create_dataloader_v1(txt, batch_size=4, max_length=256,\\n                         stride=128, shuffle=True, drop_last=True, num_workers=0):\\n    # Initialize the tokenizer\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n\\n    # Create dataset\\n    dataset = GPTDatasetV1(txt, tokenizer, max_length, stride)\\n\\n    # Create dataloader\\n    dataloader = DataLoader(\\n        dataset, batch_size=batch_size, shuffle=shuffle, drop_last=drop_last, num_workers=num_workers)\\n\\n    return dataloader\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass MultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, context_length, dropout, num_heads, qkv_bias=False):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by n_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n        self.register_buffer(\\\"mask\\\", torch.triu(torch.ones(context_length, context_length), diagonal=1))\\n\\n    def forward(self, x):\\n        b, num_tokens, d_in = x.shape\\n\\n        keys = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n        queries = self.W_query(x)\\n        values = self.W_value(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        keys = keys.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values = values.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        # Original mask truncated to the number of tokens and converted to boolean\\n        mask_bool = self.mask.bool()[:num_tokens, :num_tokens]\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.reshape(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            context_length=cfg[\\\"context_length\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n        x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        self.trf_blocks = nn.Sequential(\\n            *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n        pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n        x = self.trf_blocks(x)\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n\\ndef generate_text_simple(model, idx, max_new_tokens, context_size):\\n    # idx is (B, T) array of indices in the current context\\n    for _ in range(max_new_tokens):\\n\\n        # Crop current context if it exceeds the supported context size\\n        # E.g., if LLM supports only 5 tokens, and the context size is 10\\n        # then only the last 5 tokens are used as context\\n        idx_cond = idx[:, -context_size:]\\n\\n        # Get the predictions\\n        with torch.no_grad():\\n            logits = model(idx_cond)\\n\\n        # Focus only on the last time step\\n        # (batch, n_token, vocab_size) becomes (batch, vocab_size)\\n        logits = logits[:, -1, :]\\n\\n        # Get the idx of the vocab entry with the highest logits value\\n        idx_next = torch.argmax(logits, dim=-1, keepdim=True)  # (batch, 1)\\n\\n        # Append sampled index to the running sequence\\n        idx = torch.cat((idx, idx_next), dim=1)  # (batch, n_tokens+1)\\n\\n    return idx\\n\\n\\nif __name__ == \\\"__main__\\\":\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,     # Vocabulary size\\n        \\\"context_length\\\": 1024,  # Context length\\n        \\\"emb_dim\\\": 768,          # Embedding dimension\\n        \\\"n_heads\\\": 12,           # Number of attention heads\\n        \\\"n_layers\\\": 12,          # Number of layers\\n        \\\"drop_rate\\\": 0.1,        # Dropout rate\\n        \\\"qkv_bias\\\": False        # Query-Key-Value bias\\n    }\\n\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    model.eval()  # disable dropout\\n\\n    start_context = \\\"Hello, I am\\\"\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n    encoded_tensor = torch.tensor(encoded).unsqueeze(0)\\n\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    out = generate_text_simple(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=10,\\n        context_size=GPT_CONFIG_124M[\\\"context_length\\\"]\\n    )\\n    decoded_text = tokenizer.decode(out.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", out)\\n    print(\\\"Output length:\\\", len(out[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/01_main-chapter-code/tests.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cb44604fc4e61cddbb1aaf4f20454d30c1b168b18358318cb66a4de5942c7e79\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# File for internal use (unit tests)\\n\\nimport pytest\\nfrom gpt_train import main\\nimport requests\\n\\n@pytest.fixture\\ndef gpt_config():\\n    return {\\n        \\\"vocab_size\\\": 50257,\\n        \\\"context_length\\\": 12,  # small for testing efficiency\\n        \\\"emb_dim\\\": 32,         # small for testing efficiency\\n        \\\"n_heads\\\": 4,          # small for testing efficiency\\n        \\\"n_layers\\\": 2,         # small for testing efficiency\\n        \\\"drop_rate\\\": 0.1,\\n        \\\"qkv_bias\\\": False\\n    }\\n\\n\\n@pytest.fixture\\ndef other_settings():\\n    return {\\n        \\\"learning_rate\\\": 5e-4,\\n        \\\"num_epochs\\\": 1,    # small for testing efficiency\\n        \\\"batch_size\\\": 2,\\n        \\\"weight_decay\\\": 0.1\\n    }\\n\\n\\ndef test_main(gpt_config, other_settings):\\n    train_losses, val_losses, tokens_seen, model = main(gpt_config, other_settings)\\n\\n    assert len(train_losses) == 39, \\\"Unexpected number of training losses\\\"\\n    assert len(val_losses) == 39, \\\"Unexpected number of validation losses\\\"\\n    assert len(tokens_seen) == 39, \\\"Unexpected number of tokens seen\\\"\\n\\n\\ndef check_file_size(url, expected_size):\\n    try:\\n        response = requests.head(url, allow_redirects=True, timeout=30)\\n        if response.status_code != 200:\\n            return False, f\\\"{url} not accessible\\\"\\n\\n        size = response.headers.get(\\\"Content-Length\\\")\\n        if size is None:\\n            return False, \\\"Content-Length header is missing\\\"\\n\\n        size = int(size)\\n        if size != expected_size:\\n            return False, f\\\"{url} file has expected size {expected_size}, but got {size}\\\"\\n\\n        return True, f\\\"{url} file size is correct\\\"\\n\\n    except requests.exceptions.RequestException as e:\\n        return False, f\\\"Failed to access {url}: {e}\\\"\\n\\n\\ndef test_model_files():\\n    def check_model_files(base_url):\\n\\n        model_size = \\\"124M\\\"\\n        files = {\\n            \\\"checkpoint\\\": 77,\\n            \\\"encoder.json\\\": 1042301,\\n            \\\"hparams.json\\\": 90,\\n            \\\"model.ckpt.data-00000-of-00001\\\": 497759232,\\n            \\\"model.ckpt.index\\\": 5215,\\n            \\\"model.ckpt.meta\\\": 471155,\\n            \\\"vocab.bpe\\\": 456318\\n        }\\n\\n        for file_name, expected_size in files.items():\\n            url = f\\\"{base_url}/{model_size}/{file_name}\\\"\\n            valid, message = check_file_size(url, expected_size)\\n            assert valid, message\\n\\n        model_size = \\\"355M\\\"\\n        files = {\\n            \\\"checkpoint\\\": 77,\\n            \\\"encoder.json\\\": 1042301,\\n            \\\"hparams.json\\\": 91,\\n            \\\"model.ckpt.data-00000-of-00001\\\": 1419292672,\\n            \\\"model.ckpt.index\\\": 10399,\\n            \\\"model.ckpt.meta\\\": 926519,\\n            \\\"vocab.bpe\\\": 456318\\n        }\\n\\n        for file_name, expected_size in files.items():\\n            url = f\\\"{base_url}/{model_size}/{file_name}\\\"\\n            valid, message = check_file_size(url, expected_size)\\n            assert valid, message\\n\\n    check_model_files(base_url=\\\"https://openaipublic.blob.core.windows.net/gpt-2/models\\\")\\n    check_model_files(base_url=\\\"https://f001.backblazeb2.com/file/LLMs-from-scratch/gpt2\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/02_alternative_weight_loading/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f4c226ff169e33c71e80d87baebbaa79002e6ea43a58607408a45c3480ad041c\",\"content\":\"# Alternative Approaches to Loading Pretrained Weights\\n\\nThis folder contains alternative weight loading strategies in case the weights become unavailable from OpenAI.\\n\\n- [weight-loading-pytorch.ipynb](weight-loading-pytorch.ipynb): (Recommended) contains code to load the weights from PyTorch state dicts that I created by converting the original TensorFlow weights\\n\\n- [weight-loading-hf-transformers.ipynb](weight-loading-hf-transformers.ipynb): contains code to load the weights from the Hugging Face Model Hub via the `transformers` library\\n\\n- [weight-loading-hf-safetensors.ipynb](weight-loading-hf-safetensors.ipynb): contains code to load the weights from the Hugging Face Model Hub via the `safetensors` library directly (skipping the instantiation of a Hugging Face transformer model)\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/03_bonus_pretraining_on_gutenberg/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"df0629abf5580bdc1b29563b9232bbaf93d94ec6a968e66db7319f6b696132df\",\"content\":\"# Pretraining GPT on the Project Gutenberg Dataset\\n\\nThe code in this directory contains code for training a small GPT model on the free books provided by Project Gutenberg.\\n\\nAs the Project Gutenberg website states, \\\"the vast majority of Project Gutenberg eBooks are in the public domain in the US.\\\"\\n\\nPlease read the [Project Gutenberg Permissions, Licensing and other Common Requests](https://www.gutenberg.org/policy/permission.html) page for more information about using the resources provided by Project Gutenberg.\\n\\n&nbsp;\\n## How to Use This Code\\n\\n&nbsp;\\n\\n### 1) Download the dataset\\n\\nIn this section, we download books from Project Gutenberg using code from the [`pgcorpus/gutenberg`](https://github.com/pgcorpus/gutenberg) GitHub repository.\\n\\nAs of this writing, this will require approximately 50 GB of disk space and take about 10-15 hours, but it may be more depending on how much Project Gutenberg grew since then.\\n\\n&nbsp;\\n#### Download instructions for Linux and macOS users\\n\\n\\nLinux and macOS users can follow these steps to download the dataset (if you are a Windows user, please see the note below):\\n\\n1. Set the `03_bonus_pretraining_on_gutenberg` folder as working directory to clone the `gutenberg` repository locally in this folder (this is necessary to run the provided scripts `prepare_dataset.py` and `pretraining_simple.py`). For instance, when being in the `LLMs-from-scratch` repository's folder, navigate into the *03_bonus_pretraining_on_gutenberg* folder via:\\n```bash\\ncd ch05/03_bonus_pretraining_on_gutenberg\\n```\\n\\n2. Clone the `gutenberg` repository in there:\\n```bash\\ngit clone https://github.com/pgcorpus/gutenberg.git\\n```\\n\\n3. Navigate into the locally cloned `gutenberg` repository's folder:\\n```bash\\ncd gutenberg\\n```\\n\\n4. Install the required packages defined in *requirements.txt* from the `gutenberg` repository's folder:\\n```bash\\npip install -r requirements.txt\\n```\\n\\n5. Download the data:\\n```bash\\npython get_data.py\\n```\\n\\n6. Go back into the `03_bonus_pretraining_on_gutenberg` folder\\n```bash\\ncd ..\\n```\\n\\n&nbsp;\\n#### Special instructions for Windows users\\n\\nThe [`pgcorpus/gutenberg`](https://github.com/pgcorpus/gutenberg) code is compatible with both Linux and macOS. However, Windows users would have to make small adjustments, such as adding `shell=True` to the `subprocess` calls and replacing `rsync`.\\n\\nAlternatively, an easier way to run this code on Windows is by using the \\\"Windows Subsystem for Linux\\\" (WSL) feature, which allows users to run a Linux environment using Ubuntu in Windows. For more information, please read [Microsoft's official installation instruction](https://learn.microsoft.com/en-us/windows/wsl/install) and [tutorial](https://learn.microsoft.com/en-us/training/modules/wsl-introduction/).\\n\\nWhen using WSL, please make sure you have Python 3 installed (check via `python3 --version`, or install it for instance with `sudo apt-get install -y python3.10` for Python 3.10) and install following packages there:\\n\\n```bash\\nsudo apt-get update && \\\\\\nsudo apt-get upgrade -y && \\\\\\nsudo apt-get install -y python3-pip && \\\\\\nsudo apt-get install -y python-is-python3 && \\\\\\nsudo apt-get install -y rsync\\n```\\n\\n> **Note:**\\n> Instructions about how to set up Python and installing packages can be found in [Optional Python Setup Preferences](../../setup/01_optional-python-setup-preferences/README.md) and [Installing Python Libraries](../../setup/02_installing-python-libraries/README.md).\\n>\\n> Optionally, a Docker image running Ubuntu is provided with this repository. Instructions about how to run a container with the provided Docker image can be found in [Optional Docker Environment](../../setup/03_optional-docker-environment/README.md).\\n\\n&nbsp;\\n### 2) Prepare the dataset\\n\\nNext, run the `prepare_dataset.py` script, which concatenates the (as of this writing, 60,173) text files into fewer larger files so that they can be more efficiently transferred and accessed:\\n\\n```bash\\npython prepare_dataset.py \\\\\\n  --data_dir gutenberg/data/raw \\\\\\n  --max_size_mb 500 \\\\\\n  --output_dir gutenberg_preprocessed\\n```\\n\\n```\\n...\\nSkipping gutenberg/data/raw/PG29836_raw.txt as it does not contain primarily English text.                                     Skipping gutenberg/data/raw/PG16527_raw.txt as it does not contain primarily English text.                                     100%|\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588| 57250/57250 [25:04<00:00, 38.05it/s]\\n42 file(s) saved in /Users/sebastian/Developer/LLMs-from-scratch/ch05/03_bonus_pretraining_on_gutenberg/gutenberg_preprocessed\\n```\\n\\n\\n> **Tip:**\\n> Note that the produced files are stored in plaintext format and are not pre-tokenized for simplicity. However, you may want to update the codes to store the dataset in a pre-tokenized form to save computation time if you are planning to use the dataset more often or train for multiple epochs. See the *Design Decisions and Improvements* at the bottom of this page for more information.\\n\\n> **Tip:**\\n> You can choose smaller file sizes, for example, 50 MB. This will result in more files but might be useful for quicker pretraining runs on a small number of files for testing purposes.\\n\\n\\n&nbsp;\\n### 3) Run the pretraining script\\n\\nYou can run the pretraining script as follows. Note that the additional command line arguments are shown with the default values for illustration purposes:\\n\\n```bash\\npython pretraining_simple.py \\\\\\n  --data_dir \\\"gutenberg_preprocessed\\\" \\\\\\n  --n_epochs 1 \\\\\\n  --batch_size 4 \\\\\\n  --output_dir model_checkpoints\\n```\\n\\nThe output will be formatted in the following way:\\n\\n> Total files: 3\\n> Tokenizing file 1 of 3: data_small/combined_1.txt\\n> Training ...\\n> Ep 1 (Step 0): Train loss 9.694, Val loss 9.724\\n> Ep 1 (Step 100): Train loss 6.672, Val loss 6.683\\n> Ep 1 (Step 200): Train loss 6.543, Val loss 6.434\\n> Ep 1 (Step 300): Train loss 5.772, Val loss 6.313\\n> Ep 1 (Step 400): Train loss 5.547, Val loss 6.249\\n> Ep 1 (Step 500): Train loss 6.182, Val loss 6.155\\n> Ep 1 (Step 600): Train loss 5.742, Val loss 6.122\\n> Ep 1 (Step 700): Train loss 6.309, Val loss 5.984\\n> Ep 1 (Step 800): Train loss 5.435, Val loss 5.975\\n> Ep 1 (Step 900): Train loss 5.582, Val loss 5.935\\n> ...\\n> Ep 1 (Step 31900): Train loss 3.664, Val loss 3.946\\n> Ep 1 (Step 32000): Train loss 3.493, Val loss 3.939\\n> Ep 1 (Step 32100): Train loss 3.940, Val loss 3.961\\n> Saved model_checkpoints/model_pg_32188.pth\\n> Book processed 3h 46m 55s\\n> Total time elapsed 3h 46m 55s\\n> ETA for remaining books: 7h 33m 50s\\n> Tokenizing file 2 of 3: data_small/combined_2.txt\\n> Training ...\\n> Ep 1 (Step 32200): Train loss 2.982, Val loss 4.094\\n> Ep 1 (Step 32300): Train loss 3.920, Val loss 4.097\\n> ...\\n\\n\\n&nbsp;\\n> **Tip:**\\n> In practice, if you are using macOS or Linux, I recommend using the `tee` command to save the log outputs to a `log.txt` file in addition to printing them on the terminal:\\n\\n```bash\\npython -u pretraining_simple.py | tee log.txt\\n```\\n\\n&nbsp;\\n> **Warning:**\\n> Note that training on 1 of the ~500 Mb text files in the `gutenberg_preprocessed` folder will take approximately 4 hours on a V100 GPU.\\n> The folder contains 47 files and will take approximately 200 hours (more than 1 week) to complete. You may want to run it on a smaller number of files.\\n\\n\\n&nbsp;\\n## Design Decisions and Improvements\\n\\nNote that this code focuses on keeping things simple and minimal for educational purposes. The code could be improved in the following ways to improve modeling performance and training efficiency:\\n\\n1. Modify the `prepare_dataset.py` script to strip the Gutenberg boilerplate text from each book file.\\n2. Update the data preparation and loading utilities to pre-tokenize the dataset and save it in a tokenized form so that it doesn't have to be re-tokenized each time when calling the pretraining script.\\n3. Update the `train_model_simple` script by adding the features introduced in [Appendix D: Adding Bells and Whistles to the Training Loop](../../appendix-D/01_main-chapter-code/appendix-D.ipynb), namely, cosine decay, linear warmup, and gradient clipping.\\n4. Update the pretraining script to save the optimizer state (see section *5.4 Loading and saving weights in PyTorch* in chapter 5; [ch05.ipynb](../../ch05/01_main-chapter-code/ch05.ipynb)) and add the option to load an existing model and optimizer checkpoint and continue training if the training run was interrupted.\\n5. Add a more advanced logger (for example, Weights and Biases) to view the loss and validation curves live\\n6. Add distributed data parallelism (DDP) and train the model on multiple GPUs (see section *A.9.3 Training with multiple GPUs* in appendix A; [DDP-script.py](../../appendix-A/01_main-chapter-code/DDP-script.py)).\\n7. Swap the from scratch `MultiheadAttention` class in the `previous_chapter.py` script with the efficient `MHAPyTorchScaledDotProduct` class implemented in the [Efficient Multi-Head Attention Implementations](../../ch03/02_bonus_efficient-multihead-attention/mha-implementations.ipynb) bonus section, which uses Flash Attention via PyTorch's `nn.functional.scaled_dot_product_attention` function.\\n8. Speeding up the training by optimizing the model via [torch.compile](https://pytorch.org/tutorials/intermediate/torch_compile_tutorial.html) (`model = torch.compile`) or [thunder](https://github.com/Lightning-AI/lightning-thunder) (`model = thunder.jit(model)`).\\n9. Implement Gradient Low-Rank Projection (GaLore) to further speed up the pretraining process. This can be achieved by just replacing the `AdamW` optimizer with the provided `GaLoreAdamW` provided in the [GaLore Python library](https://github.com/jiaweizzhao/GaLore).\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/03_bonus_pretraining_on_gutenberg/prepare_dataset.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"15153dc30fca2a0bbf534ffa70353cea9eb1ed4c9304cfbc2496c7f86b3a7675\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n\\\"\\\"\\\"\\nScript that processes the Project Gutenberg files into fewer larger files.\\n\\\"\\\"\\\"\\n\\nimport argparse\\nimport os\\nimport re\\nfrom tqdm import tqdm\\nfrom gutenberg.src.cleanup import strip_headers\\n\\n\\ndef is_english(text, threshold=0.9):\\n    ascii_chars = sum(1 for c in text if ord(c) < 128)\\n    return ascii_chars / len(text) > threshold\\n\\n\\ndef combine_files(file_paths, target_dir, max_size_mb=500, separator=\\\"<|endoftext|>\\\", fallback_encoding=\\\"latin1\\\"):\\n    if not os.path.exists(target_dir):\\n        os.makedirs(target_dir)\\n\\n    current_content = []\\n    current_size = 0\\n    file_counter = 1\\n\\n    for file_path in tqdm(file_paths):\\n        try:\\n            with open(file_path, \\\"r\\\", encoding=\\\"utf-8\\\") as file:\\n                content = file.read()\\n        except UnicodeDecodeError:\\n            # Attempt to read the file with a fallback encoding\\n            tqdm.write(f\\\"Warning: UnicodeDecodeError encountered. Trying fallback encoding for {file_path}\\\")\\n            with open(file_path, \\\"r\\\", encoding=fallback_encoding) as file:\\n                content = file.read()\\n\\n        if not is_english(content):\\n            tqdm.write(f\\\"Skipping {file_path} as it does not contain primarily English text.\\\")\\n            continue\\n        content = strip_headers(content)\\n\\n        # Regular expression to replace multiple blank lines with a single blank line\\n        content = re.sub(r\\\"\\\\n\\\\s*\\\\n\\\", \\\"\\\\n\\\\n\\\", content)\\n        estimated_size = len(content.encode(\\\"utf-8\\\"))\\n\\n        if current_size + estimated_size > max_size_mb * 1024 * 1024:\\n            target_file_path = os.path.join(target_dir, f\\\"combined_{file_counter}.txt\\\")\\n            with open(target_file_path, \\\"w\\\", encoding=\\\"utf-8\\\") as target_file:\\n                target_file.write(separator.join(current_content))\\n            file_counter += 1\\n            current_content = [content]\\n            current_size = estimated_size\\n        else:\\n            current_content.append(content)\\n            current_size += estimated_size\\n\\n    if current_content:\\n        target_file_path = os.path.join(target_dir, f\\\"combined_{file_counter}.txt\\\")\\n        with open(target_file_path, \\\"w\\\", encoding=\\\"utf-8\\\") as target_file:\\n            target_file.write(separator.join(current_content))\\n    return file_counter\\n\\n\\nif __name__ == \\\"__main__\\\":\\n\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Preprocess and combine text files for pretraining\\\")\\n\\n    parser.add_argument(\\\"--data_dir\\\", type=str, default=\\\"gutenberg/data/raw\\\",\\n                        help=\\\"Directory containing the downloaded raw training data\\\")\\n    parser.add_argument(\\\"--max_size_mb\\\", type=int, default=500,\\n                        help=\\\"The maximum file size for each concatenated file in megabytes\\\")\\n    parser.add_argument(\\\"--output_dir\\\", type=str, default=\\\"gutenberg_preprocessed\\\",\\n                        help=\\\"Directory where the preprocessed data will be saved\\\")\\n\\n    args = parser.parse_args()\\n\\n    all_files = [os.path.join(path, name) for path, subdirs, files in os.walk(args.data_dir)\\n                 for name in files if name.endswith((\\\".txt\\\", \\\".txt.utf8\\\"))]\\n\\n    print(f\\\"{len(all_files)} file(s) to process.\\\")\\n    file_counter = combine_files(all_files, args.output_dir, max_size_mb=args.max_size_mb)\\n    print(f\\\"{file_counter} file(s) saved in {os.path.abspath(args.output_dir)}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/03_bonus_pretraining_on_gutenberg/pretraining_simple.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0b9d1bbb5c9eb31c65fc3e533b49410af31deb4767312f37fe1185b181c511bb\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n\\\"\\\"\\\"\\nScript for pretraining a small GPT-2 124M parameter model\\non books from Project Gutenberg.\\n\\nBefore running this script, make sure you downloaded and\\nprocessed the dataset as described in the README.md.\\n\\\"\\\"\\\"\\n\\nimport argparse\\nimport os\\nfrom pathlib import Path\\nimport time\\nimport tiktoken\\nimport torch\\n\\n# For llms_from_scratch installation instructions, see:\\n# https://github.com/rasbt/LLMs-from-scratch/tree/main/pkg\\nfrom llms_from_scratch.ch02 import create_dataloader_v1\\nfrom llms_from_scratch.ch04 import GPTModel\\nfrom llms_from_scratch.ch05 import calc_loss_batch, evaluate_model, plot_losses, generate_and_print_sample\\n\\n\\ndef read_text_file(file_path):\\n    with open(file_path, \\\"r\\\", encoding=\\\"utf-8\\\") as file:\\n        text_data = file.read()\\n    return text_data\\n\\n\\ndef create_dataloaders(text_data, train_ratio, batch_size, max_length, stride, num_workers=0):\\n    split_idx = int(train_ratio * len(text_data))\\n    train_loader = create_dataloader_v1(\\n        text_data[:split_idx],\\n        batch_size=batch_size,\\n        max_length=max_length,\\n        stride=stride,\\n        drop_last=True,\\n        shuffle=True,\\n        num_workers=num_workers\\n    )\\n    val_loader = create_dataloader_v1(\\n        text_data[split_idx:],\\n        batch_size=batch_size,\\n        max_length=max_length,\\n        stride=stride,\\n        drop_last=False,\\n        shuffle=False,\\n        num_workers=num_workers\\n    )\\n    return train_loader, val_loader\\n\\n\\ndef convert_time(seconds):\\n    hours, rem = divmod(seconds, 3600)\\n    minutes, seconds = divmod(rem, 60)\\n    return int(hours), int(minutes), int(seconds)\\n\\n\\ndef print_eta(start_time, book_start_time, index, total_files):\\n    book_end_time = time.time()  # End time of processing this book\\n    elapsed_time = book_end_time - book_start_time\\n    total_elapsed_time = book_end_time - start_time\\n    books_remaining = total_files - index\\n    average_time_per_book = total_elapsed_time / index\\n    eta = average_time_per_book * books_remaining\\n\\n    book_h, book_m, book_s = convert_time(elapsed_time)\\n    total_h, total_m, total_s = convert_time(total_elapsed_time)\\n    eta_h, eta_m, eta_s = convert_time(eta)\\n\\n    print(f\\\"Book processed {book_h}h {book_m}m {book_s}s\\\"\\n          f\\\"\\\\nTotal time elapsed {total_h}h {total_m}m {total_s}s\\\"\\n          f\\\"\\\\nETA for remaining books: {eta_h}h {eta_m}m {eta_s}s\\\")\\n\\n\\ndef train_model_simple(model, optimizer, device, n_epochs,\\n                       eval_freq, eval_iter, print_sample_iter, start_context,\\n                       output_dir, save_ckpt_freq, tokenizer,\\n                       batch_size=1024, train_ratio=0.90):\\n\\n    train_losses, val_losses, track_tokens_seen = [], [], []\\n    tokens_seen = 0\\n    global_step = -1\\n    start_time = time.time()\\n\\n    try:\\n        for epoch in range(n_epochs):\\n\\n            # Iterate over the books in the training corpus\\n            for index, file_path in enumerate(all_files, 1):\\n                book_start_time = time.time()\\n                text_data = read_text_file(file_path) + \\\" <|endoftext|> \\\"\\n                print(f\\\"Tokenizing file {index} of {total_files}: {file_path}\\\")\\n\\n                # Initialize new data loaders for each book\\n                train_loader, val_loader = create_dataloaders(\\n                    text_data,\\n                    train_ratio=train_ratio,\\n                    batch_size=batch_size,\\n                    max_length=GPT_CONFIG_124M[\\\"context_length\\\"],\\n                    stride=GPT_CONFIG_124M[\\\"context_length\\\"],\\n                    num_workers=0\\n                )\\n                print(\\\"Training ...\\\")\\n                model.train()\\n                for input_batch, target_batch in train_loader:\\n                    optimizer.zero_grad()\\n                    loss = calc_loss_batch(input_batch, target_batch, model, device)\\n                    loss.backward()\\n                    optimizer.step()\\n                    tokens_seen += input_batch.numel()\\n                    global_step += 1\\n\\n                    # Optional evaluation step\\n                    if global_step % eval_freq == 0:\\n                        train_loss, val_loss = evaluate_model(\\n                            model, train_loader, val_loader, device, eval_iter)\\n                        train_losses.append(train_loss)\\n                        val_losses.append(val_loss)\\n                        track_tokens_seen.append(tokens_seen)\\n                        print(f\\\"Ep {epoch+1} (Step {global_step}): \\\"\\n                              f\\\"Train loss {train_loss:.3f}, Val loss {val_loss:.3f}\\\")\\n\\n                    # Generate text passage\\n                    if global_step % print_sample_iter == 0:\\n                        generate_and_print_sample(\\n                            model, tokenizer, device, start_context\\n                        )\\n\\n                if global_step % save_ckpt_freq:\\n                    file_name = output_dir / f\\\"model_pg_{global_step}.pth\\\"\\n                    torch.save(model.state_dict(), file_name)\\n                    print(f\\\"Saved {file_name}\\\")\\n\\n                print_eta(start_time, book_start_time, index, total_files)\\n\\n    except KeyboardInterrupt:\\n        file_name = output_dir / f\\\"model_pg_{global_step}_interrupted.pth\\\"\\n        torch.save(model.state_dict(), file_name)\\n        print(f\\\"Saved {file_name}\\\")\\n\\n    return train_losses, val_losses, track_tokens_seen\\n\\n\\nif __name__ == \\\"__main__\\\":\\n\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"GPT Model Training Configuration\\\")\\n\\n    parser.add_argument(\\\"--data_dir\\\", type=str, default=\\\"gutenberg/data\\\",\\n                        help=\\\"Directory containing the training data\\\")\\n    parser.add_argument(\\\"--output_dir\\\", type=str, default=\\\"model_checkpoints\\\",\\n                        help=\\\"Directory where the model checkpoints will be saved\\\")\\n    parser.add_argument(\\\"--n_epochs\\\", type=int, default=1,\\n                        help=\\\"Number of epochs to train the model\\\")\\n    parser.add_argument(\\\"--print_sample_iter\\\", type=int, default=1000,\\n                        help=\\\"Iterations between printing sample outputs\\\")\\n    parser.add_argument(\\\"--eval_freq\\\", type=int, default=100,\\n                        help=\\\"Frequency of evaluations during training\\\")\\n    parser.add_argument(\\\"--save_ckpt_freq\\\", type=int, default=100_000,\\n                        help=\\\"Frequency of saving model checkpoints during training\\\")\\n    parser.add_argument(\\\"--lr\\\", type=float, default=5e-4,\\n                        help=\\\"Learning rate for the optimizer\\\")\\n    parser.add_argument(\\\"--batch_size\\\", type=int, default=4,\\n                        help=\\\"Batch size for training\\\")\\n    parser.add_argument(\\\"--debug\\\", type=bool, default=False,\\n                        help=\\\"Uses a very small model for debugging purposes\\\")\\n\\n    args = parser.parse_args()\\n\\n    if args.debug:\\n        GPT_CONFIG_124M = {\\n            \\\"vocab_size\\\": 50257,     # Vocabulary size\\n            \\\"context_length\\\": 10,    # Context length\\n            \\\"emb_dim\\\": 12,           # Embedding dimension\\n            \\\"n_heads\\\": 2,            # Number of attention heads\\n            \\\"n_layers\\\": 2,           # Number of layers\\n            \\\"drop_rate\\\": 0.0,        # Dropout rate, deactivated via 0.0 as dropout in LLMs is not recommended anymore\\n            \\\"qkv_bias\\\": False        # Query-key-value bias\\n        }\\n\\n    else:\\n        GPT_CONFIG_124M = {\\n            \\\"vocab_size\\\": 50257,     # Vocabulary size\\n            \\\"context_length\\\": 1024,  # Context length\\n            \\\"emb_dim\\\": 768,          # Embedding dimension\\n            \\\"n_heads\\\": 12,           # Number of attention heads\\n            \\\"n_layers\\\": 12,          # Number of layers\\n            \\\"drop_rate\\\": 0.1,        # Dropout rate\\n            \\\"qkv_bias\\\": False        # Query-key-value bias\\n        }\\n\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    model.to(device)\\n    optimizer = torch.optim.AdamW(model.parameters(), lr=args.lr, weight_decay=0.1)\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n\\n    data_dir = args.data_dir\\n    all_files = [os.path.join(path, name) for path, subdirs, files\\n                 in os.walk(data_dir) for name in files if name.endswith((\\\".txt\\\"))]\\n    total_files = len(all_files)\\n\\n    if total_files == 0:\\n        print(\\\"No training text files found. Make sure you \\\"\\n              \\\"selected the correct input directory\\\")\\n        quit()\\n    print(\\\"Total files:\\\", total_files)\\n\\n    output_dir = Path(args.output_dir)\\n    output_dir.mkdir(parents=True, exist_ok=True)\\n\\n    train_losses, val_losses, tokens_seen = train_model_simple(\\n        model, optimizer, device,\\n        batch_size=args.batch_size,\\n        n_epochs=args.n_epochs,\\n        eval_freq=args.eval_freq,\\n        eval_iter=1,\\n        print_sample_iter=args.print_sample_iter,\\n        output_dir=output_dir,\\n        save_ckpt_freq=args.save_ckpt_freq,\\n        start_context=\\\"Every effort moves you\\\",\\n        tokenizer=tokenizer\\n    )\\n\\n    epochs_tensor = torch.linspace(0, args.n_epochs, len(train_losses))\\n    plot_losses(epochs_tensor, tokens_seen, train_losses, val_losses)\\n\\n    torch.save(model.state_dict(), output_dir / \\\"model_pg_final.pth\\\")\\n    print(f\\\"Maximum GPU memory allocated: {torch.cuda.max_memory_allocated() / 1e9:.2f} GB\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/03_bonus_pretraining_on_gutenberg/tests.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e4e8098be444f5ec07bd0e53f4a976210c3a2dfd958bf32d8d03fbaaf58e4dc8\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# File for internal use (unit tests)\\n\\nfrom pathlib import Path\\nimport os\\nimport subprocess\\n\\n\\ndef test_pretraining():\\n\\n    sequence = \\\"a b c d\\\"\\n    repetitions = 1000\\n    content = sequence * repetitions\\n\\n    folder_path = Path(\\\"gutenberg\\\") / \\\"data\\\"\\n    file_name = \\\"repeated_sequence.txt\\\"\\n\\n    os.makedirs(folder_path, exist_ok=True)\\n\\n    with open(folder_path/file_name, \\\"w\\\") as file:\\n        file.write(content)\\n\\n    result = subprocess.run(\\n        [\\\"python\\\", \\\"pretraining_simple.py\\\", \\\"--debug\\\", \\\"true\\\"],\\n        capture_output=True, text=True\\n    )\\n    print(result.stdout)\\n    assert \\\"Maximum GPU memory allocated\\\" in result.stdout\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/04_learning_rate_schedulers/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9c8dabd2eb0fd805ba2f1e0bfb958b10b0456dd12d335025da3235d99dcbfda6\",\"content\":\"# Adding Bells and Whistles to the Training Loop\\n\\nThe main chapter used a relatively simple training function to keep the code readable and fit Chapter 5 within the page limits. Optionally, we can add a linear warm-up, a cosine decay schedule, and gradient clipping to improve the training stability and convergence.\\n\\nYou can find the code for this more sophisticated training function in [Appendix D: Adding Bells and Whistles to the Training Loop](../../appendix-D/01_main-chapter-code/appendix-D.ipynb).\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/05_bonus_hparam_tuning/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7e6d7596ceb3804100047a546c23ad7c9e36cc577c93460bdba7683034b6f110\",\"content\":\"# Optimizing Hyperparameters for Pretraining\\n\\nThe [hparam_search.py](hparam_search.py) script, based on the extended training function in [Appendix D: Adding Bells and Whistles to the Training Loop](../../appendix-D/01_main-chapter-code/appendix-D.ipynb), is designed to find optimal hyperparameters via grid search.\\n\\n>[!NOTE]\\nThis script will take a long time to run. You may want to reduce the number of hyperparameter configurations explored in the `HPARAM_GRID` dictionary at the top.\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/05_bonus_hparam_tuning/hparam_search.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"feea8602c81394cf474fbdcfedf867e0d5287de7d72381f70315d2b2829ad766\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport itertools\\nimport math\\nimport os\\nimport tiktoken\\nimport torch\\n\\n# For llms_from_scratch installation instructions, see:\\n# https://github.com/rasbt/LLMs-from-scratch/tree/main/pkg\\nfrom llms_from_scratch.ch02 import create_dataloader_v1\\nfrom llms_from_scratch.ch04 import GPTModel\\n\\n\\n# Define a grid of hyperparameters to search over\\nHPARAM_GRID = {\\n    \\\"batch_size\\\": [2, 4, 8, 16],\\n    \\\"drop_rate\\\": [0.0, 0.1, 0.2],\\n    \\\"warmup_iters\\\": [10, 20, 30],\\n    \\\"weight_decay\\\": [0.1, 0.01, 0.0],\\n    \\\"peak_lr\\\": [0.0001, 0.0005, 0.001, 0.005],\\n    \\\"initial_lr\\\": [0.00005, 0.0001],\\n    \\\"min_lr\\\": [0.00005, 0.00001, 0.0001],\\n    \\\"n_epochs\\\": [5, 10, 15, 20, 25],\\n}\\n\\n\\ndef calc_loss_loader(data_loader, model, device, num_batches=None):\\n    total_loss = 0.\\n    if len(data_loader) == 0:\\n        return float(\\\"nan\\\")\\n    elif num_batches is None:\\n        num_batches = len(data_loader)\\n    else:\\n        num_batches = min(num_batches, len(data_loader))\\n    for i, (input_batch, target_batch) in enumerate(data_loader):\\n        if i < num_batches:\\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\\n            total_loss += loss.item()\\n        else:\\n            break\\n    return total_loss / num_batches\\n\\n\\ndef calc_loss_batch(input_batch, target_batch, model, device):\\n    input_batch, target_batch = input_batch.to(device), target_batch.to(device)\\n\\n    logits = model(input_batch)\\n    logits = logits.view(-1, logits.size(-1))\\n    loss = torch.nn.functional.cross_entropy(logits, target_batch.view(-1))\\n    return loss\\n\\n\\ndef evaluate_model(model, train_loader, val_loader, device, eval_iter):\\n    model.eval()\\n    with torch.no_grad():\\n        train_loss = calc_loss_loader(train_loader, model, device, num_batches=eval_iter)\\n        val_loss = calc_loss_loader(val_loader, model, device, num_batches=eval_iter)\\n    model.train()\\n    return train_loss, val_loss\\n\\n\\ndef train_model(model, train_loader, val_loader, optimizer, device,\\n                n_epochs, eval_iter, warmup_iters=10,\\n                initial_lr=3e-05, min_lr=1e-6):\\n    global_step = 0\\n\\n    max_lr = optimizer.param_groups[0][\\\"lr\\\"]\\n\\n    # Calculate total number of iterations\\n    total_training_iters = len(train_loader) * n_epochs\\n\\n    # Calculate the learning rate increment at each step during warmup\\n    lr_increment = (optimizer.param_groups[0][\\\"lr\\\"] - initial_lr) / warmup_iters\\n\\n    for epoch in range(n_epochs):\\n        model.train()\\n        for input_batch, target_batch in train_loader:\\n            optimizer.zero_grad()\\n\\n            # Increment the global step at the beginning of the iteration\\n            global_step += 1\\n\\n            # Warmup: adjust learning rate linearly\\n            if global_step <= warmup_iters:\\n                lr = initial_lr + global_step * lr_increment\\n            # Cosine annealing phase\\n            else:\\n                progress = (global_step - warmup_iters) / (total_training_iters - warmup_iters)\\n                lr = min_lr + (max_lr - min_lr) * 0.5 * (1 + math.cos(math.pi * progress))\\n\\n            # Apply the calculated learning rate\\n            for param_group in optimizer.param_groups:\\n                param_group[\\\"lr\\\"] = lr\\n\\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\\n            loss.backward()\\n\\n            # Apply gradient clipping\\n            if global_step >= warmup_iters:\\n                torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)\\n\\n            optimizer.step()\\n\\n    train_loss, val_loss = evaluate_model(model, train_loader, val_loader, device, eval_iter)\\n\\n    return train_loss, val_loss\\n\\n\\nif __name__ == \\\"__main__\\\":\\n\\n    # Generate all combinations of hyperparameters\\n    hyperparameter_combinations = list(itertools.product(*HPARAM_GRID.values()))\\n    total_combinations = len(hyperparameter_combinations)\\n    print(f\\\"Total hyperparameter configurations: {total_combinations}\\\")\\n\\n    # Placeholder for the best loss and best hyperparameters\\n    best_val_loss = float(\\\"inf\\\")\\n    best_hparams = {}\\n\\n    script_path = os.path.abspath(__file__)\\n    script_dir = os.path.dirname(script_path)\\n    with open(os.path.join(script_dir, \\\"the-verdict.txt\\\"), \\\"r\\\", encoding=\\\"utf-8\\\") as file:\\n        text_data = file.read()\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n\\n    train_ratio = 0.95\\n    split_idx = int(train_ratio * len(text_data))\\n\\n    torch.manual_seed(123)\\n\\n    interrupted = False\\n    current_config = 0\\n    for combination in hyperparameter_combinations:\\n\\n        try:\\n            current_config += 1\\n            print(f\\\"Evaluating configuration {current_config} of {total_combinations}\\\")\\n\\n            # Unpack the current combination of hyperparameters\\n            HPARAM_CONFIG = dict(zip(HPARAM_GRID.keys(), combination))\\n\\n            GPT_CONFIG_124M = {\\n                \\\"vocab_size\\\": 50257,    # Vocabulary size\\n                \\\"context_length\\\": 256,  # Context length -- shortened from original 1024 tokens\\n                \\\"emb_dim\\\": 768,         # Embedding dimension\\n                \\\"n_heads\\\": 12,          # Number of attention heads\\n                \\\"n_layers\\\": 12,         # Number of layers\\n                \\\"drop_rate\\\": HPARAM_CONFIG[\\\"drop_rate\\\"],\\n                \\\"qkv_bias\\\": False,     # Query-Key-Value bias\\n            }\\n\\n            torch.manual_seed(123)\\n            train_loader = create_dataloader_v1(\\n                text_data[:split_idx],\\n                batch_size=HPARAM_CONFIG[\\\"batch_size\\\"],\\n                max_length=GPT_CONFIG_124M[\\\"context_length\\\"],\\n                stride=GPT_CONFIG_124M[\\\"context_length\\\"],\\n                drop_last=True,\\n                shuffle=True,\\n                num_workers=0\\n            )\\n\\n            val_loader = create_dataloader_v1(\\n                text_data[split_idx:],\\n                batch_size=HPARAM_CONFIG[\\\"batch_size\\\"],\\n                max_length=GPT_CONFIG_124M[\\\"context_length\\\"],\\n                stride=GPT_CONFIG_124M[\\\"context_length\\\"],\\n                drop_last=False,\\n                shuffle=False,\\n                num_workers=0\\n            )\\n\\n            model = GPTModel(GPT_CONFIG_124M)\\n            model.to(device)\\n\\n            optimizer = torch.optim.AdamW(\\n                model.parameters(),\\n                lr=HPARAM_CONFIG[\\\"peak_lr\\\"],\\n                weight_decay=HPARAM_CONFIG[\\\"weight_decay\\\"]\\n            )\\n\\n            encoded_start_context = tokenizer.encode(\\\"Nevertheless\\\")\\n            encoded_tensor = torch.tensor(encoded_start_context).unsqueeze(0)\\n\\n            train_loss, val_loss = train_model(\\n                model, train_loader, val_loader, optimizer, device,\\n                n_epochs=HPARAM_CONFIG[\\\"n_epochs\\\"],\\n                eval_iter=1,\\n                warmup_iters=HPARAM_CONFIG[\\\"warmup_iters\\\"],\\n                initial_lr=HPARAM_CONFIG[\\\"initial_lr\\\"],\\n                min_lr=HPARAM_CONFIG[\\\"min_lr\\\"]\\n            )\\n\\n            # Log the best hyperparameters based on validation loss\\n            if val_loss < best_val_loss:\\n                best_val_loss = val_loss\\n                best_train_loss = train_loss\\n                best_hparams = HPARAM_CONFIG\\n\\n        except KeyboardInterrupt:\\n            print(\\\"Hyperparameter search completed.\\\")\\n            print(f\\\"Best hyperparameters: {best_hparams}\\\")\\n            print(f\\\"Best Val loss: {best_val_loss} | Training loss {train_loss}\\\")\\n            interrupted = True\\n            break\\n\\n    if not interrupted:\\n        print(\\\"Hyperparameter search completed.\\\")\\n        print(f\\\"Best hyperparameters: {best_hparams}\\\")\\n        print(f\\\"Best Val loss: {best_val_loss} | Training loss {train_loss}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/06_user_interface/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"821a1479d2343498b9b141e418e0af13f7169d77244ce81fae3e0264c81319eb\",\"content\":\"# Building a User Interface to Interact With the Pretrained LLM\\n\\n\\n\\nThis bonus folder contains code for running a ChatGPT-like user interface to interact with the pretrained LLMs from chapter 5, as shown below.\\n\\n\\n\\n![Chainlit UI example](https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/chainlit/chainlit-orig.webp)\\n\\n\\n\\nTo implement this user interface, we use the open-source [Chainlit Python package](https://github.com/Chainlit/chainlit).\\n\\n&nbsp;\\n## Step 1: Install dependencies\\n\\nFirst, we install the `chainlit` package via\\n\\n```bash\\npip install chainlit\\n```\\n\\n(Alternatively, execute `pip install -r requirements-extra.txt`.)\\n\\n&nbsp;\\n## Step 2: Run `app` code\\n\\nThis folder contains 2 files:\\n\\n1. [`app_orig.py`](app_orig.py): This file loads and uses the original GPT-2 weights from OpenAI. \\n2. [`app_own.py`](app_own.py): This file loads and uses the GPT-2 weights we generated in chapter 5. This requires that you execute the [`../01_main-chapter-code/ch05.ipynb`](../01_main-chapter-code/ch05.ipynb) file first.\\n\\n(Open and inspect these files to learn more.)\\n\\nRun one of the following commands from the terminal to start the UI server:\\n\\n```bash\\nchainlit run app_orig.py\\n```\\n\\nor\\n\\n```bash\\nchainlit run app_own.py\\n```\\n\\nRunning one of the commands above should open a new browser tab where you can interact with the model. If the browser tab does not open automatically, inspect the terminal command and copy the local address into your browser address bar (usually, the address is `http://localhost:8000`).\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/06_user_interface/app_orig.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f62acb363c9fa4fa5bf448584e0927ed82bf306cda503493f477c17b39089a5d\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport tiktoken\\nimport torch\\nimport chainlit\\n\\n# For llms_from_scratch installation instructions, see:\\n# https://github.com/rasbt/LLMs-from-scratch/tree/main/pkg\\nfrom llms_from_scratch.ch04 import GPTModel\\nfrom llms_from_scratch.ch05 import (\\n    download_and_load_gpt2,\\n    generate,\\n    load_weights_into_gpt,\\n    text_to_token_ids,\\n    token_ids_to_text,\\n)\\n\\ndevice = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n\\n\\ndef get_model_and_tokenizer():\\n    \\\"\\\"\\\"\\n    Code to load a GPT-2 model with pretrained weights from OpenAI.\\n    The code is similar to chapter 5.\\n    The model will be downloaded automatically if it doesn't exist in the current folder, yet.\\n    \\\"\\\"\\\"\\n\\n    CHOOSE_MODEL = \\\"gpt2-small (124M)\\\"  # Optionally replace with another model from the model_configs dir below\\n\\n    BASE_CONFIG = {\\n        \\\"vocab_size\\\": 50257,     # Vocabulary size\\n        \\\"context_length\\\": 1024,  # Context length\\n        \\\"drop_rate\\\": 0.0,        # Dropout rate\\n        \\\"qkv_bias\\\": True         # Query-key-value bias\\n    }\\n\\n    model_configs = {\\n        \\\"gpt2-small (124M)\\\": {\\\"emb_dim\\\": 768, \\\"n_layers\\\": 12, \\\"n_heads\\\": 12},\\n        \\\"gpt2-medium (355M)\\\": {\\\"emb_dim\\\": 1024, \\\"n_layers\\\": 24, \\\"n_heads\\\": 16},\\n        \\\"gpt2-large (774M)\\\": {\\\"emb_dim\\\": 1280, \\\"n_layers\\\": 36, \\\"n_heads\\\": 20},\\n        \\\"gpt2-xl (1558M)\\\": {\\\"emb_dim\\\": 1600, \\\"n_layers\\\": 48, \\\"n_heads\\\": 25},\\n    }\\n\\n    model_size = CHOOSE_MODEL.split(\\\" \\\")[-1].lstrip(\\\"(\\\").rstrip(\\\")\\\")\\n\\n    BASE_CONFIG.update(model_configs[CHOOSE_MODEL])\\n\\n    settings, params = download_and_load_gpt2(model_size=model_size, models_dir=\\\"gpt2\\\")\\n\\n    gpt = GPTModel(BASE_CONFIG)\\n    load_weights_into_gpt(gpt, params)\\n    gpt.to(device)\\n    gpt.eval()\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n\\n    return tokenizer, gpt, BASE_CONFIG\\n\\n\\n# Obtain the necessary tokenizer and model files for the chainlit function below\\ntokenizer, model, model_config = get_model_and_tokenizer()\\n\\n\\n@chainlit.on_message\\nasync def main(message: chainlit.Message):\\n    \\\"\\\"\\\"\\n    The main Chainlit function.\\n    \\\"\\\"\\\"\\n    token_ids = generate(  # function uses `with torch.no_grad()` internally already\\n        model=model,\\n        idx=text_to_token_ids(message.content, tokenizer).to(device),  # The user text is provided via as `message.content`\\n        max_new_tokens=50,\\n        context_size=model_config[\\\"context_length\\\"],\\n        top_k=1,\\n        temperature=0.0\\n    )\\n\\n    text = token_ids_to_text(token_ids, tokenizer)\\n\\n    await chainlit.Message(\\n        content=f\\\"{text}\\\",  # This returns the model response to the interface\\n    ).send()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/06_user_interface/app_own.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"66bcaf339228e9b2a03576811513a9f82b30077ea8c4e24c12593ab0653b7934\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nfrom pathlib import Path\\nimport sys\\n\\nimport tiktoken\\nimport torch\\nimport chainlit\\n\\n# For llms_from_scratch installation instructions, see:\\n# https://github.com/rasbt/LLMs-from-scratch/tree/main/pkg\\nfrom llms_from_scratch.ch04 import GPTModel\\nfrom llms_from_scratch.ch05 import (\\n    generate,\\n    text_to_token_ids,\\n    token_ids_to_text,\\n)\\n\\n\\ndevice = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n\\n\\ndef get_model_and_tokenizer():\\n    \\\"\\\"\\\"\\n    Code to load a GPT-2 model with pretrained weights generated in chapter 5.\\n    This requires that you run the code in chapter 5 first, which generates the necessary model.pth file.\\n    \\\"\\\"\\\"\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,    # Vocabulary size\\n        \\\"context_length\\\": 256,  # Shortened context length (orig: 1024)\\n        \\\"emb_dim\\\": 768,         # Embedding dimension\\n        \\\"n_heads\\\": 12,          # Number of attention heads\\n        \\\"n_layers\\\": 12,         # Number of layers\\n        \\\"drop_rate\\\": 0.1,       # Dropout rate\\n        \\\"qkv_bias\\\": False       # Query-key-value bias\\n    }\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n\\n    model_path = Path(\\\"..\\\") / \\\"01_main-chapter-code\\\" / \\\"model.pth\\\"\\n    if not model_path.exists():\\n        print(f\\\"Could not find the {model_path} file. Please run the chapter 5 code (ch05.ipynb) to generate the model.pth file.\\\")\\n        sys.exit()\\n\\n    checkpoint = torch.load(model_path, weights_only=True)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    model.load_state_dict(checkpoint)\\n    model.to(device)\\n\\n    return tokenizer, model, GPT_CONFIG_124M\\n\\n\\n# Obtain the necessary tokenizer and model files for the chainlit function below\\ntokenizer, model, model_config = get_model_and_tokenizer()\\n\\n\\n@chainlit.on_message\\nasync def main(message: chainlit.Message):\\n    \\\"\\\"\\\"\\n    The main Chainlit function.\\n    \\\"\\\"\\\"\\n    token_ids = generate(  # function uses `with torch.no_grad()` internally already\\n        model=model,\\n        idx=text_to_token_ids(message.content, tokenizer).to(device),  # The user text is provided via as `message.content`\\n        max_new_tokens=50,\\n        context_size=model_config[\\\"context_length\\\"],\\n        top_k=1,\\n        temperature=0.0\\n    )\\n\\n    text = token_ids_to_text(token_ids, tokenizer)\\n\\n    await chainlit.Message(\\n        content=f\\\"{text}\\\",  # This returns the model response to the interface\\n    ).send()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/07_gpt_to_llama/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6924d3850ff76a608750cdea1254f013988323617f3f27577c3adac6a31d5dbe\",\"content\":\"# Converting GPT to Llama\\n\\n\\n\\nThis folder contains code for converting the GPT implementation from chapter 4 and 5 to Meta AI's Llama architecture in the following recommended reading order:\\n\\n- [converting-gpt-to-llama2.ipynb](converting-gpt-to-llama2.ipynb): contains code to convert GPT to Llama 2 7B step by step and loads pretrained weights from Meta AI\\n- [converting-llama2-to-llama3.ipynb](converting-llama2-to-llama3.ipynb): contains code to convert the Llama 2 model to Llama 3, Llama 3.1, and Llama 3.2\\n- [standalone-llama32.ipynb](standalone-llama32.ipynb): a standalone notebook implementing Llama 3.2\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/gpt-to-llama/gpt-and-all-llamas.webp\\\">\\n\\n\\n&nbsp;\\n### Using Llama 3.2 via the `llms-from-scratch` package\\n\\nFor an easy way to use the Llama 3.2 1B and 3B models, you can also use the `llms-from-scratch` PyPI package based on the source code in this repository at [pkg/llms_from_scratch](../../pkg/llms_from_scratch).\\n\\n&nbsp;\\n#### 1) Installation\\n\\n```bash\\npip install llms_from_scratch blobfile\\n```\\n\\n(Note that `blobfile` is needed to load the tokenizer.)\\n\\n&nbsp;\\n#### 2) Model and text generation settings\\n\\nSpecify which model to use:\\n\\n```python\\nMODEL_FILE = \\\"llama3.2-1B-instruct.pth\\\"\\n# MODEL_FILE = \\\"llama3.2-1B-base.pth\\\"\\n# MODEL_FILE = \\\"llama3.2-3B-instruct.pth\\\"\\n# MODEL_FILE = \\\"llama3.2-3B-base.pth\\\"\\n```\\n\\nBasic text generation settings that can be defined by the user. Note that the recommended 8192-token context size requires approximately 3 GB of VRAM for the text generation example.\\n\\n```python\\n# Text generation settings\\nif \\\"instruct\\\" in MODEL_FILE:\\n    PROMPT = \\\"What do llamas eat?\\\"\\nelse:\\n    PROMPT = \\\"Llamas eat\\\"\\n\\nMAX_NEW_TOKENS = 150\\nTEMPERATURE = 0.\\nTOP_K = 1\\n```\\n\\n&nbsp;\\n#### 3) Weight download and loading\\n\\nThis automatically downloads the weight file based on the model choice above:\\n\\n```python\\nimport os\\nimport requests\\n\\nurl = f\\\"https://huggingface.co/rasbt/llama-3.2-from-scratch/resolve/main/{MODEL_FILE}\\\"\\n\\nif not os.path.exists(MODEL_FILE):\\n    response = requests.get(url, stream=True, timeout=60)\\n    response.raise_for_status()\\n    with open(MODEL_FILE, \\\"wb\\\") as f:\\n        for chunk in response.iter_content(chunk_size=8192):\\n            if chunk:\\n                f.write(chunk)\\n    print(f\\\"Downloaded to {MODEL_FILE}\\\")\\n```\\n\\nThe model weights are then loaded as follows:\\n\\n```python\\nimport torch\\nfrom llms_from_scratch.llama3 import Llama3Model\\n\\nif \\\"1B\\\" in MODEL_FILE:\\n    from llms_from_scratch.llama3 import LLAMA32_CONFIG_1B as LLAMA32_CONFIG\\nelif \\\"3B\\\" in MODEL_FILE:\\n    from llms_from_scratch.llama3 import LLAMA32_CONFIG_3B as LLAMA32_CONFIG\\nelse:\\n    raise ValueError(\\\"Incorrect model file name\\\")\\n\\nmodel = Llama3Model(LLAMA32_CONFIG)\\nmodel.load_state_dict(torch.load(MODEL_FILE, weights_only=True, map_location=\\\"cpu\\\"))\\n\\ndevice = (\\n    torch.device(\\\"cuda\\\") if torch.cuda.is_available() else\\n    torch.device(\\\"mps\\\") if torch.backends.mps.is_available() else\\n    torch.device(\\\"cpu\\\")\\n)\\nmodel.to(device)\\n```\\n\\n&nbsp;\\n#### 4) Initialize tokenizer\\n\\nThe following code downloads and initializes the tokenizer:\\n\\n```python\\nfrom llms_from_scratch.llama3 import Llama3Tokenizer, ChatFormat, clean_text\\n\\nTOKENIZER_FILE = \\\"tokenizer.model\\\"\\n\\nurl = f\\\"https://huggingface.co/rasbt/llama-3.2-from-scratch/resolve/main/{TOKENIZER_FILE}\\\"\\n\\nif not os.path.exists(TOKENIZER_FILE):\\n    urllib.request.urlretrieve(url, TOKENIZER_FILE)\\n    print(f\\\"Downloaded to {TOKENIZER_FILE}\\\")\\n    \\ntokenizer = Llama3Tokenizer(\\\"tokenizer.model\\\")\\n\\nif \\\"instruct\\\" in MODEL_FILE:\\n    tokenizer = ChatFormat(tokenizer)\\n```\\n\\n&nbsp;\\n#### 5) Generating text\\n\\nLastly, we can generate text via the following code:\\n\\n```python\\nimport time\\n\\nfrom llms_from_scratch.ch05 import (\\n    generate,\\n    text_to_token_ids,\\n    token_ids_to_text\\n)\\n\\ntorch.manual_seed(123)\\n\\nstart = time.time()\\n\\ntoken_ids = generate(\\n    model=model,\\n    idx=text_to_token_ids(PROMPT, tokenizer).to(device),\\n    max_new_tokens=MAX_NEW_TOKENS,\\n    context_size=LLAMA32_CONFIG[\\\"context_length\\\"],\\n    top_k=TOP_K,\\n    temperature=TEMPERATURE\\n)\\n\\ntotal_time = time.time() - start\\nprint(f\\\"Time: {total_time:.2f} sec\\\")\\nprint(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n\\nif torch.cuda.is_available():\\n    max_mem_bytes = torch.cuda.max_memory_allocated()\\n    max_mem_gb = max_mem_bytes / (1024 ** 3)\\n    print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\noutput_text = token_ids_to_text(token_ids, tokenizer)\\n\\nif \\\"instruct\\\" in MODEL_FILE:\\n    output_text = clean_text(output_text)\\n\\nprint(\\\"\\\\n\\\\nOutput text:\\\\n\\\\n\\\", output_text)\\n```\\n\\nWhen using the Llama 3.2 1B Instruct model, the output should look similar to the one shown below:\\n\\n```\\nTime: 3.17 sec\\n50 tokens/sec\\nMax memory allocated: 2.91 GB\\n\\n\\nOutput text:\\n\\n Llamas are herbivores, which means they primarily eat plants. Their diet consists mainly of:\\n\\n1. Grasses: Llamas love to graze on various types of grasses, including tall grasses and grassy meadows.\\n2. Hay: Llamas also eat hay, which is a dry, compressed form of grass or other plants.\\n3. Alfalfa: Alfalfa is a legume that is commonly used as a hay substitute in llama feed.\\n4. Other plants: Llamas will also eat other plants, such as clover, dandelions, and wild grasses.\\n\\nIt's worth noting that the specific diet of llamas can vary depending on factors such as the breed,\\n```\\n\\n&nbsp;\\n#### Pro tip 1: speed up inference with FlashAttention\\n\\nInstead of using `Llama3Model`, you can use `Llama3ModelFast` as a drop-in replacement. For more information, I encourage you to inspect the [pkg/llms_from_scratch/llama3.py](../../pkg/llms_from_scratch/llama3.py) code.\\n\\nThe `Llama3ModelFast` replaces my from-scratch scaled dot-product code in the `GroupedQueryAttention` module with PyTorch's `scaled_dot_product` function, which uses `FlashAttention` on Ampere GPUs or newer.\\n\\nThe following table shows a performance comparison on an A100:\\n\\n|                 | Tokens/sec | Memory  |\\n| --------------- | ---------- | ------- |\\n| Llama3Model     | 42         | 2.91 GB |\\n| Llama3ModelFast | 54         | 2.91 GB |\\n\\n&nbsp;\\n#### Pro tip 2: speed up inference with compilation\\n\\n\\nFor up to a 4\u00d7 speed-up, replace\\n\\n```python\\nmodel.to(device)\\n```\\n\\nwith\\n\\n```python\\nmodel = torch.compile(model)\\nmodel.to(device)\\n```\\n\\nNote: There is a significant multi-minute upfront cost when compiling, and the speed-up takes effect after the first `generate` call. \\n\\nThe following table shows a performance comparison on an A100 for consequent `generate` calls:\\n\\n|                 | Tokens/sec | Memory  |\\n| --------------- | ---------- | ------- |\\n| Llama3Model     | 170        | 3.12 GB |\\n| Llama3ModelFast | 177        | 3.61 GB |\\n\\n&nbsp;\\n#### Pro tip 3: speed up inference with compilation\\n\\nYou can significantly boost inference performance using the KV cache `Llama3Model` drop-in replacement when running the model on a CPU. (See my [Understanding and Coding the KV Cache in LLMs from Scratch](https://magazine.sebastianraschka.com/p/coding-the-kv-cache-in-llms) article to learn more about KV caches.)\\n\\n```python\\nfrom llms_from_scratch.kv_cache.llama3 import Llama3Model\\nfrom llms_from_scratch.kv_cache.generate import generate_text_simple\\n\\nmodel = Llama3Model(LLAMA32_CONFIG)\\n# ...\\ntoken_ids = generate_text_simple(\\n    model=model,\\n    idx=text_to_token_ids(PROMPT, tokenizer).to(device),\\n    max_new_tokens=MAX_NEW_TOKENS,\\n    context_size=LLAMA32_CONFIG[\\\"context_length\\\"],\\n)\\n```\\n\\nNote that the peak memory usage is only listed for Nvidia CUDA devices, as it is easier to calculate. However, the memory usage on other devices is likely similar as it uses a similar precision format, and the KV cache storage results in even lower memory usage here for the generated 150-token text (however, different devices may implement matrix multiplication differently and may result in different peak memory requirements; and KV-cache memory may increase prohibitively for longer contexts lengths).\\n\\n| Model       | Mode              | Hardware        | Tokens/sec | GPU Memory (VRAM) |\\n| ----------- | ----------------- | --------------- | ---------- | ----------------- |\\n| Llama3Model | Regular           | Mac Mini M4 CPU | 1          | -                 |\\n| Llama3Model | Regular compiled  | Mac Mini M4 CPU | 1          | -                 |\\n| Llama3Model | KV cache          | Mac Mini M4 CPU | 68         | -                 |\\n| Llama3Model | KV cache compiled | Mac Mini M4 CPU | 86         | -                 |\\n|             |                   |                 |            |                   |\\n| Llama3Model | Regular           | Mac Mini M4 GPU | 15         | -                 |\\n| Llama3Model | Regular compiled  | Mac Mini M4 GPU | Error      | -                 |\\n| Llama3Model | KV cache          | Mac Mini M4 GPU | 62         | -                 |\\n| Llama3Model | KV cache compiled | Mac Mini M4 GPU | Error      | -                 |\\n|             |                   |                 |            |                   |\\n| Llama3Model | Regular           | Nvidia A100 GPU | 42         | 2.91 GB           |\\n| Llama3Model | Regular compiled  | Nvidia A100 GPU | 170        | 3.12 GB           |\\n| Llama3Model | KV cache          | Nvidia A100 GPU | 58         | 2.87 GB           |\\n| Llama3Model | KV cache compiled | Nvidia A100 GPU | 161        | 3.61 GB           |\\n\\nNote that all settings above have been tested to produce the same text outputs.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/07_gpt_to_llama/config.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"87933181423c4bc08a8fda35fc5d592344d9adb5801680d3e26101239fc0022d\",\"content\":\"{\\n    \\\"HF_ACCESS_TOKEN\\\": \\\"hf-...\\\",\\n    \\\"_comment\\\": \\\"Enter your access token from https://huggingface.co/settings/tokens\\\"\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/07_gpt_to_llama/previous_chapters.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1fd4087ea6a9e820088edaf666ff157ed708f17ae35d841c4ef598f91999f7cf\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n#\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 2-4.\\n# This file can be run as a standalone script.\\n\\nimport torch\\n\\n\\n#####################################\\n# Chapter 5\\n#####################################\\ndef text_to_token_ids(text, tokenizer):\\n    encoded = tokenizer.encode(text)\\n    encoded_tensor = torch.tensor(encoded).unsqueeze(0)  # add batch dimension\\n    return encoded_tensor\\n\\n\\ndef token_ids_to_text(token_ids, tokenizer):\\n    flat = token_ids.squeeze(0)  # remove batch dimension\\n    return tokenizer.decode(flat.tolist())\\n\\n\\ndef generate(model, idx, max_new_tokens, context_size, temperature=0.0, top_k=None, eos_id=None):\\n\\n    # For-loop is the same as before: Get logits, and only focus on last time step\\n    for _ in range(max_new_tokens):\\n        idx_cond = idx[:, -context_size:]\\n        with torch.no_grad():\\n            logits = model(idx_cond)\\n        logits = logits[:, -1, :]\\n\\n        # New: Filter logits with top_k sampling\\n        if top_k is not None:\\n            # Keep only top_k values\\n            top_logits, _ = torch.topk(logits, top_k)\\n            min_val = top_logits[:, -1]\\n            logits = torch.where(logits < min_val, torch.tensor(float(\\\"-inf\\\")).to(logits.device), logits)\\n\\n        # New: Apply temperature scaling\\n        if temperature > 0.0:\\n            logits = logits / temperature\\n\\n            # New (not in book): numerical stability tip to get equivalent results on mps device\\n            # subtract rowwise max before softmax\\n            logits = logits - logits.max(dim=-1, keepdim=True).values\\n\\n            # Apply softmax to get probabilities\\n            probs = torch.softmax(logits, dim=-1)  # (batch_size, context_len)\\n\\n            # Sample from the distribution\\n            idx_next = torch.multinomial(probs, num_samples=1)  # (batch_size, 1)\\n\\n        # Otherwise same as before: get idx of the vocab entry with the highest logits value\\n        else:\\n            idx_next = torch.argmax(logits, dim=-1, keepdim=True)  # (batch_size, 1)\\n\\n        if idx_next == eos_id:  # Stop generating early if end-of-sequence token is encountered and eos_id is specified\\n            break\\n\\n        # Same as before: append sampled index to the running sequence\\n        idx = torch.cat((idx, idx_next), dim=1)  # (batch_size, num_tokens+1)\\n\\n    return idx\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/07_gpt_to_llama/tests/test_llama32_nb.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8103d99d6c6df82a1ba72e80f700d3ef389724a444d1a713a2753336df221ff1\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport importlib\\nfrom pathlib import Path\\n\\nimport pytest\\nimport torch\\n\\nfrom llms_from_scratch.utils import import_definitions_from_notebook\\n\\n\\ntransformers_installed = importlib.util.find_spec(\\\"transformers\\\") is not None\\n\\n\\n@pytest.fixture\\ndef import_notebook_defs():\\n    nb_dir = Path(__file__).resolve().parents[1]\\n    mod = import_definitions_from_notebook(nb_dir, \\\"standalone-llama32.ipynb\\\")\\n    return mod\\n\\n\\n@pytest.fixture\\ndef dummy_input():\\n    torch.manual_seed(123)\\n    return torch.randint(0, 100, (1, 8))  # batch size 1, seq length 8\\n\\n\\n@pytest.fixture\\ndef dummy_cfg_base():\\n    return {\\n        \\\"vocab_size\\\": 100,\\n        \\\"emb_dim\\\": 32,            # hidden_size\\n        \\\"hidden_dim\\\": 64,         # intermediate_size (FFN)\\n        \\\"n_layers\\\": 2,\\n        \\\"n_heads\\\": 4,\\n        \\\"head_dim\\\": 8,\\n        \\\"n_kv_groups\\\": 1,\\n        \\\"dtype\\\": torch.float32,\\n        \\\"rope_base\\\": 500_000.0,\\n        \\\"rope_freq\\\": {\\n            \\\"factor\\\": 8.0,\\n            \\\"low_freq_factor\\\": 1.0,\\n            \\\"high_freq_factor\\\": 4.0,\\n            \\\"original_context_length\\\": 8192,\\n        },\\n        \\\"context_length\\\": 64,\\n    }\\n\\n\\n@torch.inference_mode()\\ndef test_dummy_llama3_forward(dummy_cfg_base, dummy_input, import_notebook_defs):\\n    torch.manual_seed(123)\\n    model = import_notebook_defs.Llama3Model(dummy_cfg_base)\\n    out = model(dummy_input)\\n    assert out.shape == (1, dummy_input.size(1), dummy_cfg_base[\\\"vocab_size\\\"])\\n\\n\\n@torch.inference_mode()\\n@pytest.mark.skipif(not transformers_installed, reason=\\\"transformers not installed\\\")\\ndef test_llama3_base_equivalence_with_transformers(import_notebook_defs):\\n    from transformers.models.llama import LlamaConfig, LlamaForCausalLM\\n    cfg = {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8192,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"n_kv_groups\\\": 2,\\n        \\\"rope_base\\\": 500_000.0,\\n        \\\"rope_freq\\\": {\\n            \\\"factor\\\": 32.0,\\n            \\\"low_freq_factor\\\": 1.0,\\n            \\\"high_freq_factor\\\": 4.0,\\n            \\\"original_context_length\\\": 8192,\\n        },\\n        \\\"dtype\\\": torch.float32,\\n    }\\n\\n    ours = import_notebook_defs.Llama3Model(cfg)\\n\\n    hf_cfg = LlamaConfig(\\n        vocab_size=cfg[\\\"vocab_size\\\"],\\n        hidden_size=cfg[\\\"emb_dim\\\"],\\n        num_attention_heads=cfg[\\\"n_heads\\\"],\\n        num_key_value_heads=cfg[\\\"n_kv_groups\\\"],\\n        num_hidden_layers=cfg[\\\"n_layers\\\"],\\n        intermediate_size=cfg[\\\"hidden_dim\\\"],\\n        max_position_embeddings=cfg[\\\"context_length\\\"],\\n        rms_norm_eps=1e-5,\\n        attention_bias=False,\\n        rope_theta=cfg[\\\"rope_base\\\"],\\n        tie_word_embeddings=False,\\n        attn_implementation=\\\"eager\\\",\\n        torch_dtype=torch.float32,\\n        rope_scaling={\\n            \\\"type\\\": \\\"llama3\\\",\\n            \\\"factor\\\": cfg[\\\"rope_freq\\\"][\\\"factor\\\"],\\n            \\\"low_freq_factor\\\": cfg[\\\"rope_freq\\\"][\\\"low_freq_factor\\\"],\\n            \\\"high_freq_factor\\\": cfg[\\\"rope_freq\\\"][\\\"high_freq_factor\\\"],\\n            \\\"original_max_position_embeddings\\\": cfg[\\\"rope_freq\\\"][\\\"original_context_length\\\"],\\n        },\\n    )\\n    theirs = LlamaForCausalLM(hf_cfg)\\n\\n    hf_state = theirs.state_dict()\\n    import_notebook_defs.load_weights_into_llama(ours, {\\\"n_layers\\\": cfg[\\\"n_layers\\\"], \\\"hidden_dim\\\": cfg[\\\"hidden_dim\\\"]}, hf_state)\\n\\n    x = torch.randint(0, cfg[\\\"vocab_size\\\"], (2, 8), dtype=torch.long)\\n    ours_logits = ours(x)\\n    theirs_logits = theirs(x).logits.to(ours_logits.dtype)\\n\\n    torch.testing.assert_close(ours_logits, theirs_logits, rtol=1e-5, atol=1e-5)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/07_gpt_to_llama/tests/tests_rope_and_parts.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aa5a58309ed0918af9ac5103f07265dbc68be14a557361056b55ab44a26f618b\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# File for internal use (unit tests)\\n\\nimport io\\nimport os\\nimport sys\\nimport types\\nimport nbformat\\nfrom packaging import version\\nfrom typing import Optional, Tuple\\nimport torch\\nimport pytest\\nimport transformers\\nfrom transformers.models.llama.modeling_llama import LlamaRotaryEmbedding, apply_rotary_pos_emb\\n\\n\\ntransformers_version = transformers.__version__\\n\\n# LitGPT code function `litgpt_build_rope_cache` from https://github.com/Lightning-AI/litgpt/blob/main/litgpt/model.py\\n# LitGPT is licensed under Apache v2: https://github.com/Lightning-AI/litgpt/blob/main/LICENSE\\n\\n\\ndef litgpt_build_rope_cache(\\n    seq_len: int,\\n    n_elem: int,\\n    device: Optional[torch.device] = None,\\n    base: int = 10000,\\n    condense_ratio: int = 1,\\n    extra_config: Optional[dict] = None,\\n) -> Tuple[torch.Tensor, torch.Tensor]:\\n    \\\"\\\"\\\"\\n    Enhanced Transformer with Rotary Position Embedding.\\n\\n    Args:\\n        seq_len (int): Sequence length.\\n        n_elem (int): Number of elements (head dimension).\\n        device (torch.device, optional): Device for tensor allocations.\\n        base (int, optional): Base for computing inverse frequencies.\\n        condense_ratio (int, optional): Ratio to condense the position indices.\\n        extra_config (dict, optional): Configuration parameters for frequency adjustments (used by Llama 3.1 and 3.2)\\n\\n    Returns:\\n        Tuple[torch.Tensor, torch.Tensor]: Cosine and sine caches for RoPE.\\n    \\\"\\\"\\\"\\n\\n    # Compute the inverse frequencies theta\\n    theta = 1.0 / (base ** (torch.arange(0, n_elem, 2, device=device).float() / n_elem))\\n\\n    if extra_config is not None:\\n        orig_context_len = extra_config[\\\"original_max_seq_len\\\"]\\n        factor = extra_config[\\\"factor\\\"]\\n        low_freq_factor = extra_config[\\\"low_freq_factor\\\"]\\n        high_freq_factor = extra_config[\\\"high_freq_factor\\\"]\\n\\n        wavelen = 2 * torch.pi / theta\\n        ratio = orig_context_len / wavelen\\n        smooth_factor = (ratio - low_freq_factor) / (high_freq_factor - low_freq_factor)\\n        smooth_factor = torch.clamp(smooth_factor, min=0.0, max=1.0)\\n\\n        # Compute adjusted_theta without masked indexing\\n        adjusted_theta = (1 - smooth_factor) * (theta / factor) + smooth_factor * theta\\n        theta = adjusted_theta\\n\\n    # Create position indices `[0, 1, ..., seq_len - 1]`\\n    seq_idx = torch.arange(seq_len, device=device) / condense_ratio\\n\\n    # Calculate the product of position index and $\\\\theta_i$\\n    idx_theta = torch.outer(seq_idx, theta).repeat(1, 2)\\n\\n    return torch.cos(idx_theta), torch.sin(idx_theta)\\n\\n\\n# LitGPT code from https://github.com/Lightning-AI/litgpt/blob/main/litgpt/model.py\\n# LitGPT is licensed under Apache v2: https://github.com/Lightning-AI/litgpt/blob/main/LICENSE\\ndef litgpt_apply_rope(x: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor) -> torch.Tensor:\\n    head_size = x.size(-1)\\n    x1 = x[..., : head_size // 2]  # (B, nh, T, hs/2)\\n    x2 = x[..., head_size // 2:]  # (B, nh, T, hs/2)\\n    rotated = torch.cat((-x2, x1), dim=-1)  # (B, nh, T, hs)\\n    if cos.dim() > 1:\\n        # batch dimensions must align\\n        # sin/cos are (B, T, hs) so we unsqeeze -3 for nh\\n        # we count from back because all of apply_rope does\\n        cos = cos.unsqueeze(-3)\\n        sin = sin.unsqueeze(-3)\\n\\n    roped = (x * cos) + (rotated * sin)\\n    return roped.to(dtype=x.dtype)\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef notebook():\\n    def import_definitions_from_notebook(notebooks):\\n        imported_modules = {}\\n\\n        for fullname, names in notebooks.items():\\n            # Get the directory of the current test file\\n            current_dir = os.path.dirname(__file__)\\n            path = os.path.join(current_dir, \\\"..\\\", fullname + \\\".ipynb\\\")\\n            path = os.path.normpath(path)\\n\\n            # Load the notebook\\n            if not os.path.exists(path):\\n                raise FileNotFoundError(f\\\"Notebook file not found at: {path}\\\")\\n\\n            with io.open(path, \\\"r\\\", encoding=\\\"utf-8\\\") as f:\\n                nb = nbformat.read(f, as_version=4)\\n\\n            # Create a module to store the imported functions and classes\\n            mod = types.ModuleType(fullname)\\n            sys.modules[fullname] = mod\\n\\n            # Go through the notebook cells and only execute function or class definitions\\n            for cell in nb.cells:\\n                if cell.cell_type == \\\"code\\\":\\n                    cell_code = cell.source\\n                    for name in names:\\n                        # Check for function or class definitions\\n                        if f\\\"def {name}\\\" in cell_code or f\\\"class {name}\\\" in cell_code:\\n                            exec(cell_code, mod.__dict__)\\n\\n            imported_modules[fullname] = mod\\n\\n        return imported_modules\\n\\n    notebooks = {\\n        \\\"converting-gpt-to-llama2\\\": [\\\"SiLU\\\", \\\"RMSNorm\\\", \\\"precompute_rope_params\\\", \\\"compute_rope\\\"],\\n        \\\"converting-llama2-to-llama3\\\": [\\\"precompute_rope_params\\\"]\\n    }\\n\\n    return import_definitions_from_notebook(notebooks)\\n\\n\\n@pytest.fixture(autouse=True)\\ndef set_seed():\\n    torch.manual_seed(123)\\n\\n\\ndef test_rope_llama2(notebook):\\n\\n    this_nb = notebook[\\\"converting-gpt-to-llama2\\\"]\\n\\n    # Settings\\n    batch_size = 1\\n    context_len = 4096\\n    num_heads = 4\\n    head_dim = 16\\n    theta_base = 10_000\\n\\n    # Instantiate RoPE parameters\\n    cos, sin = this_nb.precompute_rope_params(head_dim=head_dim, context_length=context_len)\\n\\n    # Dummy query and key tensors\\n    queries = torch.randn(batch_size, num_heads, context_len, head_dim)\\n    keys = torch.randn(batch_size, num_heads, context_len, head_dim)\\n\\n    # Apply rotary position embeddings\\n    queries_rot = this_nb.compute_rope(queries, cos, sin)\\n    keys_rot = this_nb.compute_rope(keys, cos, sin)\\n\\n    # Generate reference RoPE via HF\\n\\n    if version.parse(transformers_version) < version.parse(\\\"4.48\\\"):\\n        rot_emb = LlamaRotaryEmbedding(\\n            dim=head_dim,\\n            max_position_embeddings=context_len,\\n            base=theta_base\\n        )\\n    else:\\n        class RoPEConfig:\\n            dim: int = head_dim\\n            rope_theta = theta_base\\n            max_position_embeddings: int = 8192\\n            hidden_size = head_dim * num_heads\\n            num_attention_heads = num_heads\\n            rope_parameters = {\\\"rope_type\\\": \\\"default\\\", \\\"rope_theta\\\": theta_base}\\n\\n            def standardize_rope_params(self):\\n                return\\n\\n        config = RoPEConfig()\\n        rot_emb = LlamaRotaryEmbedding(config=config)\\n\\n    position_ids = torch.arange(context_len, dtype=torch.long).unsqueeze(0)\\n    ref_cos, ref_sin = rot_emb(queries, position_ids)\\n    ref_queries_rot, ref_keys_rot = apply_rotary_pos_emb(queries, keys, ref_cos, ref_sin)\\n    torch.testing.assert_close(sin, ref_sin.squeeze(0))\\n    torch.testing.assert_close(cos, ref_cos.squeeze(0))\\n    torch.testing.assert_close(keys_rot, ref_keys_rot)\\n    torch.testing.assert_close(queries_rot, ref_queries_rot)\\n\\n    # Generate reference RoPE via LitGPT\\n    litgpt_cos, litgpt_sin = litgpt_build_rope_cache(context_len, n_elem=head_dim, base=10_000)\\n    litgpt_queries_rot = litgpt_apply_rope(queries, litgpt_cos, litgpt_sin)\\n    litgpt_keys_rot = litgpt_apply_rope(keys, litgpt_cos, litgpt_sin)\\n\\n    torch.testing.assert_close(sin, litgpt_sin)\\n    torch.testing.assert_close(cos, litgpt_cos)\\n    torch.testing.assert_close(keys_rot, litgpt_keys_rot)\\n    torch.testing.assert_close(queries_rot, litgpt_queries_rot)\\n\\n\\ndef test_rope_llama3(notebook):\\n\\n    nb1 = notebook[\\\"converting-gpt-to-llama2\\\"]\\n    nb2 = notebook[\\\"converting-llama2-to-llama3\\\"]\\n\\n    # Settings\\n    batch_size = 1\\n    context_len = 8192\\n    num_heads = 4\\n    head_dim = 16\\n    theta_base = 500_000\\n\\n    # Instantiate RoPE parameters\\n    cos, sin = nb2.precompute_rope_params(\\n        head_dim=head_dim,\\n        context_length=context_len,\\n        theta_base=theta_base\\n    )\\n\\n    # Dummy query and key tensors\\n    torch.manual_seed(123)\\n    queries = torch.randn(batch_size, num_heads, context_len, head_dim)\\n    keys = torch.randn(batch_size, num_heads, context_len, head_dim)\\n\\n    # Apply rotary position embeddings\\n    queries_rot = nb1.compute_rope(queries, cos, sin)\\n    keys_rot = nb1.compute_rope(keys, cos, sin)\\n\\n    # Generate reference RoPE via HF\\n    if version.parse(transformers_version) < version.parse(\\\"4.48\\\"):\\n        rot_emb = LlamaRotaryEmbedding(\\n            dim=head_dim,\\n            max_position_embeddings=context_len,\\n            base=theta_base\\n        )\\n    else:\\n        class RoPEConfig:\\n            dim: int = head_dim\\n            rope_theta = theta_base\\n            max_position_embeddings: int = 8192\\n            hidden_size = head_dim * num_heads\\n            num_attention_heads = num_heads\\n            rope_parameters = {\\\"rope_type\\\": \\\"default\\\", \\\"rope_theta\\\": theta_base}\\n\\n            def standardize_rope_params(self):\\n                return\\n\\n        config = RoPEConfig()\\n        rot_emb = LlamaRotaryEmbedding(config=config)\\n\\n    position_ids = torch.arange(context_len, dtype=torch.long).unsqueeze(0)\\n    ref_cos, ref_sin = rot_emb(queries, position_ids)\\n    ref_queries_rot, ref_keys_rot = apply_rotary_pos_emb(queries, keys, ref_cos, ref_sin)\\n\\n    torch.testing.assert_close(sin, ref_sin.squeeze(0))\\n    torch.testing.assert_close(cos, ref_cos.squeeze(0))\\n    torch.testing.assert_close(keys_rot, ref_keys_rot)\\n    torch.testing.assert_close(queries_rot, ref_queries_rot)\\n\\n    # Generate reference RoPE via LitGPT\\n    litgpt_cos, litgpt_sin = litgpt_build_rope_cache(context_len, n_elem=head_dim, base=theta_base)\\n    litgpt_queries_rot = litgpt_apply_rope(queries, litgpt_cos, litgpt_sin)\\n    litgpt_keys_rot = litgpt_apply_rope(keys, litgpt_cos, litgpt_sin)\\n\\n    torch.testing.assert_close(sin, litgpt_sin)\\n    torch.testing.assert_close(cos, litgpt_cos)\\n    torch.testing.assert_close(keys_rot, litgpt_keys_rot)\\n    torch.testing.assert_close(queries_rot, litgpt_queries_rot)\\n\\n\\ndef test_rope_llama3_12(notebook):\\n\\n    nb1 = notebook[\\\"converting-gpt-to-llama2\\\"]\\n    nb2 = notebook[\\\"converting-llama2-to-llama3\\\"]\\n\\n    # Settings\\n    batch_size = 1\\n    context_len = 8192\\n    num_heads = 4\\n    head_dim = 16\\n    rope_theta = 500_000\\n\\n    rope_config = {\\n        \\\"factor\\\": 8.0,\\n        \\\"low_freq_factor\\\": 1.0,\\n        \\\"high_freq_factor\\\": 4.0,\\n        \\\"original_context_length\\\": 8192,\\n    }\\n\\n    # Instantiate RoPE parameters\\n    cos, sin = nb2.precompute_rope_params(\\n        head_dim=head_dim,\\n        theta_base=rope_theta,\\n        context_length=context_len,\\n        freq_config=rope_config,\\n    )\\n\\n    # Dummy query and key tensors\\n    torch.manual_seed(123)\\n    queries = torch.randn(batch_size, num_heads, context_len, head_dim)\\n    keys = torch.randn(batch_size, num_heads, context_len, head_dim)\\n\\n    # Apply rotary position embeddings\\n    queries_rot = nb1.compute_rope(queries, cos, sin)\\n    keys_rot = nb1.compute_rope(keys, cos, sin)\\n\\n    # Generate reference RoPE via HF\\n    hf_rope_params = {\\n        \\\"factor\\\": 8.0,\\n        \\\"low_freq_factor\\\": 1.0,\\n        \\\"high_freq_factor\\\": 4.0,\\n        \\\"original_max_position_embeddings\\\": 8192,\\n        \\\"rope_type\\\": \\\"llama3\\\"\\n    }\\n\\n    class RoPEConfig:\\n        rope_type = \\\"llama3\\\"\\n        rope_scaling = hf_rope_params\\n        factor = 1.0\\n        dim: int = head_dim\\n        rope_theta = 500_000\\n        max_position_embeddings: int = 8192\\n        hidden_size = head_dim * num_heads\\n        num_attention_heads = num_heads\\n        rope_parameters = {**hf_rope_params, \\\"rope_theta\\\": rope_theta}\\n\\n        def standardize_rope_params(self):\\n            return\\n\\n    config = RoPEConfig()\\n\\n    rot_emb = LlamaRotaryEmbedding(config=config)\\n    position_ids = torch.arange(context_len, dtype=torch.long).unsqueeze(0)\\n    ref_cos, ref_sin = rot_emb(queries, position_ids)\\n    ref_queries_rot, ref_keys_rot = apply_rotary_pos_emb(queries, keys, ref_cos, ref_sin)\\n\\n    torch.testing.assert_close(sin, ref_sin.squeeze(0))\\n    torch.testing.assert_close(cos, ref_cos.squeeze(0))\\n    torch.testing.assert_close(keys_rot, ref_keys_rot)\\n    torch.testing.assert_close(queries_rot, ref_queries_rot)\\n\\n    # Generate reference RoPE via LitGPT\\n    litgpt_rope_config = {\\n        \\\"factor\\\": 8.0,\\n        \\\"low_freq_factor\\\": 1.0,\\n        \\\"high_freq_factor\\\": 4.0,\\n        \\\"original_max_seq_len\\\": 8192\\n    }\\n\\n    litgpt_cos, litgpt_sin = litgpt_build_rope_cache(\\n        context_len,\\n        n_elem=head_dim,\\n        base=rope_theta,\\n        extra_config=litgpt_rope_config\\n    )\\n    litgpt_queries_rot = litgpt_apply_rope(queries, litgpt_cos, litgpt_sin)\\n    litgpt_keys_rot = litgpt_apply_rope(keys, litgpt_cos, litgpt_sin)\\n\\n    torch.testing.assert_close(sin, litgpt_sin)\\n    torch.testing.assert_close(cos, litgpt_cos)\\n    torch.testing.assert_close(keys_rot, litgpt_keys_rot)\\n    torch.testing.assert_close(queries_rot, litgpt_queries_rot)\\n\\n\\ndef test_silu(notebook):\\n    example_batch = torch.randn(2, 3, 4)\\n    silu = notebook[\\\"converting-gpt-to-llama2\\\"].SiLU()\\n    assert torch.allclose(silu(example_batch), torch.nn.functional.silu(example_batch))\\n\\n\\n@pytest.mark.skipif(torch.__version__ < \\\"2.4\\\", reason=\\\"Requires PyTorch 2.4 or newer\\\")\\ndef test_rmsnorm(notebook):\\n    example_batch = torch.randn(2, 3, 4)\\n    rms_norm = notebook[\\\"converting-gpt-to-llama2\\\"].RMSNorm(emb_dim=example_batch.shape[-1], eps=1e-5)\\n    rmsnorm_pytorch = torch.nn.RMSNorm(example_batch.shape[-1], eps=1e-5)\\n\\n    assert torch.allclose(rms_norm(example_batch), rmsnorm_pytorch(example_batch))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/08_memory_efficient_weight_loading/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f7528ad7a9f15d2c05032f8550ecd4dc8e0169f928bfafa59e78ca08b224c119\",\"content\":\"# Memory-efficient Model Weight Loading\\n\\nThis folder contains code to illustrate how to load model weights more efficiently\\n\\n- [memory-efficient-state-dict.ipynb](memory-efficient-state-dict.ipynb): contains code to load model weights via PyTorch's `load_state_dict` method more efficiently\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/08_memory_efficient_weight_loading/previous_chapters.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d40f8de9dfb936b9ad99bae810a818dc98c1f6dfd17cbf8a82fb565d3ee32c1e\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n#\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 2-5.\\n\\n\\nimport torch\\nimport torch.nn as nn\\n\\n#####################################\\n# Chapter 3\\n#####################################\\n\\n\\nclass MultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, context_length, dropout, num_heads, qkv_bias=False):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by n_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n        self.register_buffer(\\\"mask\\\", torch.triu(torch.ones(context_length, context_length), diagonal=1))\\n\\n    def forward(self, x):\\n        b, num_tokens, d_in = x.shape\\n\\n        keys = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n        queries = self.W_query(x)\\n        values = self.W_value(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        keys = keys.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values = values.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        # Original mask truncated to the number of tokens and converted to boolean\\n        mask_bool = self.mask.bool()[:num_tokens, :num_tokens]\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.reshape(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            context_length=cfg[\\\"context_length\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n        x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        self.trf_blocks = nn.Sequential(\\n            *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n        pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n        x = self.trf_blocks(x)\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/09_extending-tokenizers/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c69477cabf9c31f8db907c8e609705df1be2c2e63bbe369dfa75647bcdf97af0\",\"content\":\"# Extending the Tiktoken BPE Tokenizer with New Tokens\\n\\n- [extend-tiktoken.ipynb](extend-tiktoken.ipynb) contains optional (bonus) code to explain how we can add special tokens to a tokenizer implemented via `tiktoken` and how to update the LLM accordingly\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/10_llm-training-speed/00_orig.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2eecb3656604acfe201cf019b5de6ae6673381f00616ab773e259d539c7189f3\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n\\nimport os\\nimport time\\nimport urllib.request\\n\\nimport matplotlib.pyplot as plt\\nimport torch\\nimport torch.nn as nn\\nfrom torch.utils.data import Dataset, DataLoader\\nimport tiktoken\\n\\n#####################################\\n# Chapter 2\\n#####################################\\n\\n\\nclass GPTDatasetV1(Dataset):\\n    def __init__(self, txt, tokenizer, max_length, stride):\\n        self.input_ids = []\\n        self.target_ids = []\\n\\n        # Tokenize the entire text\\n        token_ids = tokenizer.encode(txt, allowed_special={\\\"<|endoftext|>\\\"})\\n\\n        # Use a sliding window to chunk the book into overlapping sequences of max_length\\n        for i in range(0, len(token_ids) - max_length, stride):\\n            input_chunk = token_ids[i:i + max_length]\\n            target_chunk = token_ids[i + 1: i + max_length + 1]\\n            self.input_ids.append(torch.tensor(input_chunk))\\n            self.target_ids.append(torch.tensor(target_chunk))\\n\\n    def __len__(self):\\n        return len(self.input_ids)\\n\\n    def __getitem__(self, idx):\\n        return self.input_ids[idx], self.target_ids[idx]\\n\\n\\ndef create_dataloader_v1(txt, batch_size=4, max_length=256,\\n                         stride=128, shuffle=True, drop_last=True, num_workers=0):\\n    # Initialize the tokenizer\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n\\n    # Create dataset\\n    dataset = GPTDatasetV1(txt, tokenizer, max_length, stride)\\n\\n    # Create dataloader\\n    dataloader = DataLoader(\\n        dataset, batch_size=batch_size, shuffle=shuffle, drop_last=drop_last, num_workers=num_workers)\\n\\n    return dataloader\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass MultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, context_length, dropout, num_heads, qkv_bias=False):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by n_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n        self.register_buffer(\\\"mask\\\", torch.triu(torch.ones(context_length, context_length), diagonal=1))\\n\\n    def forward(self, x):\\n        b, num_tokens, d_in = x.shape\\n\\n        keys = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n        queries = self.W_query(x)\\n        values = self.W_value(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        keys = keys.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values = values.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        # Original mask truncated to the number of tokens and converted to boolean\\n        mask_bool = self.mask.bool()[:num_tokens, :num_tokens]\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.reshape(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            context_length=cfg[\\\"context_length\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n        x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        self.trf_blocks = nn.Sequential(\\n            *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n        pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n        x = self.trf_blocks(x)\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n\\ndef generate_text_simple(model, idx, max_new_tokens, context_size):\\n    # idx is (B, T) array of indices in the current context\\n    for _ in range(max_new_tokens):\\n\\n        # Crop current context if it exceeds the supported context size\\n        # E.g., if LLM supports only 5 tokens, and the context size is 10\\n        # then only the last 5 tokens are used as context\\n        idx_cond = idx[:, -context_size:]\\n\\n        # Get the predictions\\n        with torch.no_grad():\\n            logits = model(idx_cond)\\n\\n        # Focus only on the last time step\\n        # (batch, n_token, vocab_size) becomes (batch, vocab_size)\\n        logits = logits[:, -1, :]\\n\\n        # Get the idx of the vocab entry with the highest logits value\\n        idx_next = torch.argmax(logits, dim=-1, keepdim=True)  # (batch, 1)\\n\\n        # Append sampled index to the running sequence\\n        idx = torch.cat((idx, idx_next), dim=1)  # (batch, n_tokens+1)\\n\\n    return idx\\n\\n#####################################\\n# Chapter 5\\n#####################################\\n\\n\\ndef text_to_token_ids(text, tokenizer):\\n    encoded = tokenizer.encode(text)\\n    encoded_tensor = torch.tensor(encoded).unsqueeze(0)  # add batch dimension\\n    return encoded_tensor\\n\\n\\ndef token_ids_to_text(token_ids, tokenizer):\\n    flat = token_ids.squeeze(0)  # remove batch dimension\\n    return tokenizer.decode(flat.tolist())\\n\\n\\ndef calc_loss_batch(input_batch, target_batch, model, device):\\n    input_batch, target_batch = input_batch.to(device), target_batch.to(device)\\n    logits = model(input_batch)\\n    loss = torch.nn.functional.cross_entropy(logits.flatten(0, 1), target_batch.flatten())\\n    return loss\\n\\n\\ndef calc_loss_loader(data_loader, model, device, num_batches=None):\\n    total_loss = 0.\\n    if len(data_loader) == 0:\\n        return float(\\\"nan\\\")\\n    elif num_batches is None:\\n        num_batches = len(data_loader)\\n    else:\\n        num_batches = min(num_batches, len(data_loader))\\n    for i, (input_batch, target_batch) in enumerate(data_loader):\\n        if i < num_batches:\\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\\n            total_loss += loss.item()\\n        else:\\n            break\\n    return total_loss / num_batches\\n\\n\\ndef evaluate_model(model, train_loader, val_loader, device, eval_iter):\\n    model.eval()\\n    with torch.no_grad():\\n        train_loss = calc_loss_loader(train_loader, model, device, num_batches=eval_iter)\\n        val_loss = calc_loss_loader(val_loader, model, device, num_batches=eval_iter)\\n    model.train()\\n    return train_loss, val_loss\\n\\n\\ndef generate_and_print_sample(model, tokenizer, device, start_context):\\n    model.eval()\\n    context_size = model.pos_emb.weight.shape[0]\\n    encoded = text_to_token_ids(start_context, tokenizer).to(device)\\n    with torch.no_grad():\\n        token_ids = generate_text_simple(\\n            model=model, idx=encoded,\\n            max_new_tokens=50, context_size=context_size\\n        )\\n        decoded_text = token_ids_to_text(token_ids, tokenizer)\\n        print(decoded_text.replace(\\\"\\\\n\\\", \\\" \\\"))  # Compact print format\\n    model.train()\\n\\n\\ndef train_model_simple_with_timing(model, train_loader, val_loader, optimizer, device,\\n                                   num_epochs, eval_freq, eval_iter, start_context, tokenizer):\\n    train_losses, val_losses, track_tokens = [], [], []\\n    total_tokens, global_step, last_tokens = 0, -1, 0\\n\\n    # Variables for cumulative average tokens/sec\\n    cumulative_tokens, cumulative_time = 0.0, 0.0\\n\\n    # CUDA-specific timing setup\\n    use_cuda = device.type == \\\"cuda\\\"\\n    if use_cuda:\\n        t_start = torch.cuda.Event(enable_timing=True)\\n        t_end = torch.cuda.Event(enable_timing=True)\\n        torch.cuda.synchronize()  # Ensure all prior CUDA operations are done\\n        t_start.record()          # Start the timer for the first interval\\n    else:\\n        t0 = time.time()          # Start the timer for the first interval\\n\\n    # Main training loop\\n    for epoch in range(num_epochs):\\n        model.train()\\n        for inp_batch, tgt_batch in train_loader:\\n            optimizer.zero_grad()\\n            global_step += 1\\n\\n            # Forward and backward pass\\n            loss = calc_loss_batch(inp_batch, tgt_batch, model, device)\\n            loss.backward()\\n            optimizer.step()\\n\\n            total_tokens += inp_batch.numel()\\n\\n            # At evaluation intervals, measure elapsed time and tokens per second\\n            if global_step % eval_freq == 0:\\n                # End timing for the current interval\\n                if use_cuda:\\n                    t_end.record()\\n                    torch.cuda.synchronize()  # Wait for all CUDA ops to complete.\\n                    elapsed = t_start.elapsed_time(t_end) / 1000  # Convert ms to seconds\\n                    t_start.record()  # Reset timer for the next interval\\n                else:\\n                    elapsed = time.time() - t0\\n                    t0 = time.time()  # Reset timer for the next interval\\n\\n                # Calculate tokens processed in this interval\\n                tokens_interval = total_tokens - last_tokens\\n                last_tokens = total_tokens\\n                tps = tokens_interval / elapsed if elapsed > 0 else 0  # Tokens per second\\n\\n                # Update cumulative counters (skip the first evaluation interval)\\n                if global_step:  # This is False only when global_step == 0 (first evaluation)\\n                    cumulative_tokens += tokens_interval\\n                    cumulative_time += elapsed\\n\\n                # Compute cumulative average tokens/sec (excluding the first interval)\\n                avg_tps = cumulative_tokens / cumulative_time if cumulative_time > 0 else 0\\n\\n                # Evaluate model performance (this may add overhead)\\n                train_loss, val_loss = evaluate_model(model, train_loader, val_loader, device, eval_iter)\\n                train_losses.append(train_loss)\\n                val_losses.append(val_loss)\\n                track_tokens.append(total_tokens)\\n\\n                print(f\\\"Ep {epoch+1}, Step {global_step:06d}, \\\"\\n                      f\\\"Train: {train_loss:.3f}, Val: {val_loss:.3f}, \\\"\\n                      f\\\"Step tok/sec: {round(tps)}, Avg tok/sec: {round(avg_tps)}\\\")\\n\\n        generate_and_print_sample(model, tokenizer, device, start_context)\\n\\n        # Memory stats\\n        if torch.cuda.is_available():\\n            device = torch.cuda.current_device()\\n\\n            allocated = torch.cuda.memory_allocated(device) / 1024**3  # Convert to GB\\n            reserved = torch.cuda.memory_reserved(device) / 1024**3  # Convert to GB\\n\\n            print(f\\\"\\\\nAllocated memory: {allocated:.4f} GB\\\")\\n            print(f\\\"Reserved memory: {reserved:.4f} GB\\\\n\\\")\\n\\n    return train_losses, val_losses, track_tokens\\n\\n\\ndef plot_losses(epochs_seen, tokens_seen, train_losses, val_losses):\\n    fig, ax1 = plt.subplots()\\n\\n    # Plot training and validation loss against epochs\\n    ax1.plot(epochs_seen, train_losses, label=\\\"Training loss\\\")\\n    ax1.plot(epochs_seen, val_losses, linestyle=\\\"-.\\\", label=\\\"Validation loss\\\")\\n    ax1.set_xlabel(\\\"Epochs\\\")\\n    ax1.set_ylabel(\\\"Loss\\\")\\n    ax1.legend(loc=\\\"upper right\\\")\\n\\n    # Create a second x-axis for tokens seen\\n    ax2 = ax1.twiny()  # Create a second x-axis that shares the same y-axis\\n    ax2.plot(tokens_seen, train_losses, alpha=0)  # Invisible plot for aligning ticks\\n    ax2.set_xlabel(\\\"Tokens seen\\\")\\n\\n    fig.tight_layout()  # Adjust layout to make room\\n    # plt.show()\\n\\n\\n#####################################\\n# Main function calls\\n#####################################\\n\\ndef main(gpt_config, settings):\\n\\n    torch.manual_seed(123)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    print(f\\\"PyTorch version: {torch.__version__}\\\")\\n    print(f\\\"Using {device}\\\")\\n    if torch.cuda.is_available():\\n        print(f\\\"CUDA version: {torch.version.cuda}\\\")\\n    print()\\n\\n    ##############################\\n    # Download data if necessary\\n    ##############################\\n\\n    file_path = \\\"middlemarch.txt\\\"\\n    url = \\\"https://www.gutenberg.org/cache/epub/145/pg145.txt\\\"\\n\\n    if not os.path.exists(file_path):\\n        with urllib.request.urlopen(url) as response:\\n            text_data = response.read().decode(\\\"utf-8\\\")\\n        with open(file_path, \\\"w\\\", encoding=\\\"utf-8\\\") as file:\\n            file.write(text_data)\\n    else:\\n        with open(file_path, \\\"r\\\", encoding=\\\"utf-8\\\") as file:\\n            text_data = file.read()\\n\\n    ##############################\\n    # Initialize model\\n    ##############################\\n\\n    model = GPTModel(gpt_config)\\n    model.to(device)  # no assignment model = model.to(device) necessary for nn.Module classes\\n    optimizer = torch.optim.AdamW(\\n        model.parameters(), lr=settings[\\\"learning_rate\\\"], weight_decay=settings[\\\"weight_decay\\\"]\\n    )\\n\\n    ##############################\\n    # Set up dataloaders\\n    ##############################\\n\\n    # Train/validation ratio\\n    train_ratio = 0.90\\n    split_idx = int(train_ratio * len(text_data))\\n\\n    train_loader = create_dataloader_v1(\\n        text_data[:split_idx],\\n        batch_size=settings[\\\"batch_size\\\"],\\n        max_length=gpt_config[\\\"context_length\\\"],\\n        stride=gpt_config[\\\"context_length\\\"],\\n        drop_last=True,\\n        shuffle=True,\\n        num_workers=4\\n    )\\n\\n    val_loader = create_dataloader_v1(\\n        text_data[split_idx:],\\n        batch_size=settings[\\\"batch_size\\\"],\\n        max_length=gpt_config[\\\"context_length\\\"],\\n        stride=gpt_config[\\\"context_length\\\"],\\n        drop_last=False,\\n        shuffle=False,\\n        num_workers=4\\n    )\\n\\n    ##############################\\n    # Train model\\n    ##############################\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n\\n    train_losses, val_losses, tokens_seen = train_model_simple_with_timing(\\n        model=model,\\n        train_loader=train_loader,\\n        val_loader=val_loader,\\n        optimizer=optimizer,\\n        device=device,\\n        num_epochs=settings[\\\"num_epochs\\\"],\\n        eval_freq=15,\\n        eval_iter=1,\\n        start_context=\\\"Every effort moves you\\\",\\n        tokenizer=tokenizer\\n    )\\n\\n    return train_losses, val_losses, tokens_seen, model\\n\\n\\nif __name__ == \\\"__main__\\\":\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,     # Vocabulary size\\n        \\\"context_length\\\": 1024,  # Input tokens per training example\\n        \\\"emb_dim\\\": 768,          # Embedding dimension\\n        \\\"n_heads\\\": 12,           # Number of attention heads\\n        \\\"n_layers\\\": 12,          # Number of layers\\n        \\\"drop_rate\\\": 0.1,        # Dropout rate\\n        \\\"qkv_bias\\\": False        # Query-key-value bias\\n    }\\n\\n    OTHER_SETTINGS = {\\n        \\\"learning_rate\\\": 5e-4,\\n        \\\"num_epochs\\\": 15,\\n        \\\"batch_size\\\": 8,\\n        \\\"weight_decay\\\": 0.1\\n    }\\n\\n    ###########################\\n    # Initiate training\\n    ###########################\\n\\n    train_losses, val_losses, tokens_seen, model = main(GPT_CONFIG_124M, OTHER_SETTINGS)\\n\\n    ###########################\\n    # After training\\n    ###########################\\n\\n    # Plot results\\n    epochs_tensor = torch.linspace(0, OTHER_SETTINGS[\\\"num_epochs\\\"], len(train_losses))\\n    plot_losses(epochs_tensor, tokens_seen, train_losses, val_losses)\\n    plt.savefig(\\\"loss.pdf\\\")\\n\\n    # Save and load model\\n    # torch.save(model.state_dict(), \\\"model.pth\\\")\\n    # model = GPTModel(GPT_CONFIG_124M)\\n    # model.load_state_dict(torch.load(\\\"model.pth\\\", weights_only=True))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/10_llm-training-speed/01_opt_single_gpu.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"512abcb5eedfa37aadeac0753dcbf253f0df748d9aed2bf439d8b8e528826717\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n\\nimport os\\nimport time\\n\\nimport matplotlib.pyplot as plt\\nimport requests\\nimport torch\\nimport torch.nn as nn\\nfrom torch.utils.data import Dataset, DataLoader\\nimport tiktoken\\n\\n#####################################\\n# Chapter 2\\n#####################################\\n\\n\\nclass GPTDatasetV1(Dataset):\\n    def __init__(self, txt, tokenizer, max_length, stride):\\n        self.input_ids = []\\n        self.target_ids = []\\n\\n        # Tokenize the entire text\\n        token_ids = tokenizer.encode(txt, allowed_special={\\\"<|endoftext|>\\\"})\\n\\n        # Use a sliding window to chunk the book into overlapping sequences of max_length\\n        for i in range(0, len(token_ids) - max_length, stride):\\n            input_chunk = token_ids[i:i + max_length]\\n            target_chunk = token_ids[i + 1: i + max_length + 1]\\n            self.input_ids.append(torch.tensor(input_chunk))\\n            self.target_ids.append(torch.tensor(target_chunk))\\n\\n    def __len__(self):\\n        return len(self.input_ids)\\n\\n    def __getitem__(self, idx):\\n        return self.input_ids[idx], self.target_ids[idx]\\n\\n\\ndef create_dataloader_v1(txt, batch_size=4, max_length=256,\\n                         stride=128, shuffle=True, drop_last=True, num_workers=0):\\n    # Initialize the tokenizer\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n\\n    # Create dataset\\n    dataset = GPTDatasetV1(txt, tokenizer, max_length, stride)\\n\\n    # Create dataloader\\n    dataloader = DataLoader(\\n        dataset, batch_size=batch_size, shuffle=shuffle, drop_last=drop_last, num_workers=num_workers,\\n        pin_memory=True\\n    )\\n\\n    return dataloader\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass PyTorchMultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, num_heads, dropout=0.0, qkv_bias=False):\\n        super().__init__()\\n\\n        assert d_out % num_heads == 0, \\\"d_out is indivisible by num_heads\\\"\\n\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads\\n        self.d_out = d_out\\n\\n        self.qkv = nn.Linear(d_in, 3 * d_out, bias=qkv_bias)\\n        self.proj = nn.Linear(d_out, d_out)\\n        self.dropout = dropout\\n\\n    def forward(self, x):\\n        batch_size, num_tokens, embed_dim = x.shape\\n\\n        # (b, num_tokens, embed_dim) --> (b, num_tokens, 3 * embed_dim)\\n        qkv = self.qkv(x)\\n\\n        # (b, num_tokens, 3 * embed_dim) --> (b, num_tokens, 3, num_heads, head_dim)\\n        qkv = qkv.view(batch_size, num_tokens, 3, self.num_heads, self.head_dim)\\n\\n        # (b, num_tokens, 3, num_heads, head_dim) --> (3, b, num_heads, num_tokens, head_dim)\\n        qkv = qkv.permute(2, 0, 3, 1, 4)\\n\\n        # (3, b, num_heads, num_tokens, head_dim) -> 3 times (b, num_heads, num_tokens, head_dim)\\n        queries, keys, values = qkv\\n\\n        use_dropout = 0. if not self.training else self.dropout\\n\\n        context_vec = nn.functional.scaled_dot_product_attention(\\n            queries, keys, values, attn_mask=None, dropout_p=use_dropout, is_causal=True)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.transpose(1, 2).contiguous().view(batch_size, num_tokens, self.d_out)\\n\\n        context_vec = self.proj(context_vec)\\n\\n        return context_vec\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            nn.GELU(approximate=\\\"tanh\\\"),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = PyTorchMultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = nn.LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = nn.LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n        x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        self.trf_blocks = nn.Sequential(\\n            *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.final_norm = nn.LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n        pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n        x = self.trf_blocks(x)\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n\\ndef generate_text_simple(model, idx, max_new_tokens, context_size):\\n    # idx is (B, T) array of indices in the current context\\n    for _ in range(max_new_tokens):\\n\\n        # Crop current context if it exceeds the supported context size\\n        # E.g., if LLM supports only 5 tokens, and the context size is 10\\n        # then only the last 5 tokens are used as context\\n        idx_cond = idx[:, -context_size:]\\n\\n        # Get the predictions\\n        with torch.no_grad():\\n            logits = model(idx_cond)\\n\\n        # Focus only on the last time step\\n        # (batch, n_token, vocab_size) becomes (batch, vocab_size)\\n        logits = logits[:, -1, :]\\n\\n        # Get the idx of the vocab entry with the highest logits value\\n        idx_next = torch.argmax(logits, dim=-1, keepdim=True)  # (batch, 1)\\n\\n        # Append sampled index to the running sequence\\n        idx = torch.cat((idx, idx_next), dim=1)  # (batch, n_tokens+1)\\n\\n    return idx\\n\\n#####################################\\n# Chapter 5\\n#####################################\\n\\n\\ndef text_to_token_ids(text, tokenizer):\\n    encoded = tokenizer.encode(text)\\n    encoded_tensor = torch.tensor(encoded).unsqueeze(0)  # add batch dimension\\n    return encoded_tensor\\n\\n\\ndef token_ids_to_text(token_ids, tokenizer):\\n    flat = token_ids.squeeze(0)  # remove batch dimension\\n    return tokenizer.decode(flat.tolist())\\n\\n\\ndef calc_loss_batch(input_batch, target_batch, model, device):\\n    input_batch, target_batch = input_batch.to(device), target_batch.to(device)\\n    logits = model(input_batch)\\n    loss = torch.nn.functional.cross_entropy(logits.flatten(0, 1), target_batch.flatten())\\n    return loss\\n\\n\\ndef calc_loss_loader(data_loader, model, device, num_batches=None):\\n    total_loss = 0.\\n    if len(data_loader) == 0:\\n        return float(\\\"nan\\\")\\n    elif num_batches is None:\\n        num_batches = len(data_loader)\\n    else:\\n        num_batches = min(num_batches, len(data_loader))\\n    for i, (input_batch, target_batch) in enumerate(data_loader):\\n        if i < num_batches:\\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\\n            total_loss += loss.item()\\n        else:\\n            break\\n    return total_loss / num_batches\\n\\n\\ndef evaluate_model(model, train_loader, val_loader, device, eval_iter):\\n    model.eval()\\n    with torch.no_grad():\\n        train_loss = calc_loss_loader(train_loader, model, device, num_batches=eval_iter)\\n        val_loss = calc_loss_loader(val_loader, model, device, num_batches=eval_iter)\\n    model.train()\\n    return train_loss, val_loss\\n\\n\\ndef generate_and_print_sample(model, tokenizer, device, start_context):\\n    model.eval()\\n    context_size = model.pos_emb.weight.shape[0]\\n    encoded = text_to_token_ids(start_context, tokenizer).to(device)\\n    with torch.no_grad():\\n        token_ids = generate_text_simple(\\n            model=model, idx=encoded,\\n            max_new_tokens=50, context_size=context_size\\n        )\\n        decoded_text = token_ids_to_text(token_ids, tokenizer)\\n        print(decoded_text.replace(\\\"\\\\n\\\", \\\" \\\"))  # Compact print format\\n    model.train()\\n\\n\\ndef train_model_simple_with_timing(model, train_loader, val_loader, optimizer, device,\\n                                   num_epochs, eval_freq, eval_iter, start_context, tokenizer):\\n    train_losses, val_losses, track_tokens = [], [], []\\n    total_tokens, global_step, last_tokens = 0, -1, 0\\n\\n    # Variables for cumulative average tokens/sec\\n    cumulative_tokens, cumulative_time = 0.0, 0.0\\n\\n    # CUDA-specific timing setup\\n    use_cuda = device.type == \\\"cuda\\\"\\n    if use_cuda:\\n        t_start = torch.cuda.Event(enable_timing=True)\\n        t_end = torch.cuda.Event(enable_timing=True)\\n        torch.cuda.synchronize()  # Ensure all prior CUDA operations are done\\n        t_start.record()          # Start the timer for the first interval\\n    else:\\n        t0 = time.time()          # Start the timer for the first interval\\n\\n    # Main training loop\\n    for epoch in range(num_epochs):\\n        model.train()\\n        for inp_batch, tgt_batch in train_loader:\\n            optimizer.zero_grad()\\n            global_step += 1\\n\\n            # Forward and backward pass\\n            loss = calc_loss_batch(inp_batch, tgt_batch, model, device)\\n            loss.backward()\\n            optimizer.step()\\n\\n            total_tokens += inp_batch.numel()\\n\\n            # At evaluation intervals, measure elapsed time and tokens per second\\n            if global_step % eval_freq == 0:\\n                # End timing for the current interval\\n                if use_cuda:\\n                    t_end.record()\\n                    torch.cuda.synchronize()  # Wait for all CUDA ops to complete.\\n                    elapsed = t_start.elapsed_time(t_end) / 1000  # Convert ms to seconds\\n                    t_start.record()  # Reset timer for the next interval\\n                else:\\n                    elapsed = time.time() - t0\\n                    t0 = time.time()  # Reset timer for the next interval\\n\\n                # Calculate tokens processed in this interval\\n                tokens_interval = total_tokens - last_tokens\\n                last_tokens = total_tokens\\n                tps = tokens_interval / elapsed if elapsed > 0 else 0  # Tokens per second\\n\\n                # Update cumulative counters (skip the first evaluation interval)\\n                if global_step:  # This is False only when global_step == 0 (first evaluation)\\n                    cumulative_tokens += tokens_interval\\n                    cumulative_time += elapsed\\n\\n                # Compute cumulative average tokens/sec (excluding the first interval)\\n                avg_tps = cumulative_tokens / cumulative_time if cumulative_time > 0 else 0\\n\\n                # Evaluate model performance (this may add overhead)\\n                train_loss, val_loss = evaluate_model(model, train_loader, val_loader, device, eval_iter)\\n                train_losses.append(train_loss)\\n                val_losses.append(val_loss)\\n                track_tokens.append(total_tokens)\\n\\n                print(f\\\"Ep {epoch+1}, Step {global_step:06d}, \\\"\\n                      f\\\"Train: {train_loss:.3f}, Val: {val_loss:.3f}, \\\"\\n                      f\\\"Step tok/sec: {round(tps)}, Avg tok/sec: {round(avg_tps)}\\\")\\n\\n        generate_and_print_sample(model, tokenizer, device, start_context)\\n\\n        # Memory stats\\n        if torch.cuda.is_available():\\n            device = torch.cuda.current_device()\\n\\n            allocated = torch.cuda.memory_allocated(device) / 1024**3  # Convert to GB\\n            reserved = torch.cuda.memory_reserved(device) / 1024**3  # Convert to GB\\n\\n            print(f\\\"\\\\nAllocated memory: {allocated:.4f} GB\\\")\\n            print(f\\\"Reserved memory: {reserved:.4f} GB\\\\n\\\")\\n\\n    return train_losses, val_losses, track_tokens\\n\\n\\ndef plot_losses(epochs_seen, tokens_seen, train_losses, val_losses):\\n    fig, ax1 = plt.subplots()\\n\\n    # Plot training and validation loss against epochs\\n    ax1.plot(epochs_seen, train_losses, label=\\\"Training loss\\\")\\n    ax1.plot(epochs_seen, val_losses, linestyle=\\\"-.\\\", label=\\\"Validation loss\\\")\\n    ax1.set_xlabel(\\\"Epochs\\\")\\n    ax1.set_ylabel(\\\"Loss\\\")\\n    ax1.legend(loc=\\\"upper right\\\")\\n\\n    # Create a second x-axis for tokens seen\\n    ax2 = ax1.twiny()  # Create a second x-axis that shares the same y-axis\\n    ax2.plot(tokens_seen, train_losses, alpha=0)  # Invisible plot for aligning ticks\\n    ax2.set_xlabel(\\\"Tokens seen\\\")\\n\\n    fig.tight_layout()  # Adjust layout to make room\\n    # plt.show()\\n\\n\\n#####################################\\n# Main function calls\\n#####################################\\n\\ndef main(gpt_config, settings):\\n\\n    torch.manual_seed(123)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    print(f\\\"PyTorch version: {torch.__version__}\\\")\\n    print(f\\\"Using {device}\\\")\\n    if torch.cuda.is_available():\\n        print(f\\\"CUDA version: {torch.version.cuda}\\\")\\n\\n        capability = torch.cuda.get_device_capability()\\n        if capability[0] >= 7:  # Volta (7.0+), Turing (7.5+), Ampere (8.0+), Hopper (9.0+)\\n            torch.set_float32_matmul_precision(\\\"high\\\")\\n            print(\\\"Uses tensor cores\\\")\\n        else:\\n            print(\\\"Tensor cores not supported on this GPU. Using default precision.\\\")\\n    print(f\\\"Uses tensor cores: {torch.cuda.is_available()}\\\")\\n    print()\\n\\n    ##############################\\n    # Download data if necessary\\n    ##############################\\n\\n    file_path = \\\"middlemarch.txt\\\"\\n    url = \\\"https://www.gutenberg.org/cache/epub/145/pg145.txt\\\"\\n\\n    if not os.path.exists(file_path):\\n        response = requests.get(url, timeout=30)\\n        response.raise_for_status()\\n        text_data = response.text\\n        with open(file_path, \\\"w\\\", encoding=\\\"utf-8\\\") as file:\\n            file.write(text_data)\\n    else:\\n        with open(file_path, \\\"r\\\", encoding=\\\"utf-8\\\") as file:\\n            text_data = file.read()\\n\\n    ##############################\\n    # Initialize model\\n    ##############################\\n\\n    model = GPTModel(gpt_config)\\n    model = torch.compile(model)\\n    model.to(device).to(torch.bfloat16)\\n    optimizer = torch.optim.AdamW(\\n        model.parameters(), lr=settings[\\\"learning_rate\\\"], weight_decay=settings[\\\"weight_decay\\\"],\\n        fused=True\\n    )\\n\\n    ##############################\\n    # Set up dataloaders\\n    ##############################\\n\\n    # Train/validation ratio\\n    train_ratio = 0.90\\n    split_idx = int(train_ratio * len(text_data))\\n\\n    train_loader = create_dataloader_v1(\\n        text_data[:split_idx],\\n        batch_size=settings[\\\"batch_size\\\"],\\n        max_length=gpt_config[\\\"context_length\\\"],\\n        stride=gpt_config[\\\"context_length\\\"],\\n        drop_last=True,\\n        shuffle=True,\\n        num_workers=4\\n    )\\n\\n    val_loader = create_dataloader_v1(\\n        text_data[split_idx:],\\n        batch_size=settings[\\\"batch_size\\\"],\\n        max_length=gpt_config[\\\"context_length\\\"],\\n        stride=gpt_config[\\\"context_length\\\"],\\n        drop_last=False,\\n        shuffle=False,\\n        num_workers=4\\n    )\\n\\n    ##############################\\n    # Train model\\n    ##############################\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n\\n    train_losses, val_losses, tokens_seen = train_model_simple_with_timing(\\n        model=model,\\n        train_loader=train_loader,\\n        val_loader=val_loader,\\n        optimizer=optimizer,\\n        device=device,\\n        num_epochs=settings[\\\"num_epochs\\\"],\\n        eval_freq=10,\\n        eval_iter=1,\\n        start_context=\\\"Every effort moves you\\\",\\n        tokenizer=tokenizer\\n    )\\n\\n    return train_losses, val_losses, tokens_seen, model\\n\\n\\nif __name__ == \\\"__main__\\\":\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50304,     # Vocabulary size\\n        \\\"context_length\\\": 1024,  # Input tokens per training example\\n        \\\"emb_dim\\\": 768,          # Embedding dimension\\n        \\\"n_heads\\\": 12,           # Number of attention heads\\n        \\\"n_layers\\\": 12,          # Number of layers\\n        \\\"drop_rate\\\": 0.1,        # Dropout rate\\n        \\\"qkv_bias\\\": False        # Query-key-value bias\\n    }\\n\\n    OTHER_SETTINGS = {\\n        \\\"learning_rate\\\": 5e-4,\\n        \\\"num_epochs\\\": 15,\\n        \\\"batch_size\\\": 32,\\n        \\\"weight_decay\\\": 0.1\\n    }\\n\\n    ###########################\\n    # Initiate training\\n    ###########################\\n\\n    train_losses, val_losses, tokens_seen, model = main(GPT_CONFIG_124M, OTHER_SETTINGS)\\n\\n    ###########################\\n    # After training\\n    ###########################\\n\\n    # Plot results\\n    epochs_tensor = torch.linspace(0, OTHER_SETTINGS[\\\"num_epochs\\\"], len(train_losses))\\n    plot_losses(epochs_tensor, tokens_seen, train_losses, val_losses)\\n    plt.savefig(\\\"loss.pdf\\\")\\n\\n    # Save and load model\\n    #\\n    # compiled = hasattr(model, \\\"_orig_mod\\\")\\n    # if compiled:\\n    #     torch.save(model._orig_mod.state_dict(), \\\"model.pth\\\")\\n    # else:\\n    #     torch.save(model.state_dict(), \\\"model.pth\\\")\\n    #\\n    # model = GPTModel(GPT_CONFIG_124M)\\n    # model.load_state_dict(torch.load(\\\"model.pth\\\", weights_only=True))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/10_llm-training-speed/02_opt_multi_gpu_ddp.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5514600b813d323ca10bff5a41da4b7ded66c3af9c9f4295147d2d7d2ec973b2\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n\\nimport os\\nimport time\\n\\nimport matplotlib.pyplot as plt\\nimport requests\\nimport torch\\nimport torch.nn as nn\\nfrom torch.utils.data import Dataset, DataLoader\\nimport tiktoken\\n\\n# NEW imports (see Appendix A):\\nimport platform\\nfrom torch.utils.data.distributed import DistributedSampler\\nfrom torch.nn.parallel import DistributedDataParallel as DDP\\nfrom torch.distributed import init_process_group, destroy_process_group\\n\\n\\n# NEW: function to initialize a distributed process group (1 process / GPU)\\n# this allows communication among processes\\n# (see Appendix A):\\ndef ddp_setup(rank, world_size):\\n    \\\"\\\"\\\"\\n    Arguments:\\n        rank: a unique process ID\\n        world_size: total number of processes in the group\\n    \\\"\\\"\\\"\\n    # Only set MASTER_ADDR and MASTER_PORT if not already defined by torchrun\\n    if \\\"MASTER_ADDR\\\" not in os.environ:\\n        os.environ[\\\"MASTER_ADDR\\\"] = \\\"localhost\\\"\\n    if \\\"MASTER_PORT\\\" not in os.environ:\\n        os.environ[\\\"MASTER_PORT\\\"] = \\\"12345\\\"\\n\\n    # initialize process group\\n    if platform.system() == \\\"Windows\\\":\\n        # Disable libuv because PyTorch for Windows isn't built with support\\n        os.environ[\\\"USE_LIBUV\\\"] = \\\"0\\\"\\n        # Windows users may have to use \\\"gloo\\\" instead of \\\"nccl\\\" as backend\\n        # gloo: Facebook Collective Communication Library\\n        init_process_group(backend=\\\"gloo\\\", rank=rank, world_size=world_size)\\n    else:\\n        # nccl: NVIDIA Collective Communication Library\\n        init_process_group(backend=\\\"nccl\\\", rank=rank, world_size=world_size)\\n\\n    torch.cuda.set_device(rank)\\n\\n\\n#####################################\\n# Chapter 2\\n#####################################\\n\\n\\nclass GPTDatasetV1(Dataset):\\n    def __init__(self, txt, tokenizer, max_length, stride):\\n        self.input_ids = []\\n        self.target_ids = []\\n\\n        # Tokenize the entire text\\n        token_ids = tokenizer.encode(txt, allowed_special={\\\"<|endoftext|>\\\"})\\n\\n        # Use a sliding window to chunk the book into overlapping sequences of max_length\\n        for i in range(0, len(token_ids) - max_length, stride):\\n            input_chunk = token_ids[i:i + max_length]\\n            target_chunk = token_ids[i + 1: i + max_length + 1]\\n            self.input_ids.append(torch.tensor(input_chunk))\\n            self.target_ids.append(torch.tensor(target_chunk))\\n\\n    def __len__(self):\\n        return len(self.input_ids)\\n\\n    def __getitem__(self, idx):\\n        return self.input_ids[idx], self.target_ids[idx]\\n\\n\\n# NEW: Modify to set shuffle=False and use a sampler\\n# (See Appendix A):\\ndef create_dataloader_v1(txt, batch_size=4, max_length=256,\\n                         stride=128, drop_last=True, num_workers=0):\\n    # Initialize the tokenizer\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n\\n    # Create dataset\\n    dataset = GPTDatasetV1(txt, tokenizer, max_length, stride)\\n\\n    # Create dataloader\\n    dataloader = DataLoader(\\n        dataset=dataset,\\n        batch_size=batch_size,\\n        shuffle=False,  # NEW: False because of DistributedSampler below\\n        drop_last=drop_last,\\n        num_workers=num_workers,\\n        pin_memory=True,\\n        # NEW: chunk batches across GPUs without overlapping samples:\\n        sampler=DistributedSampler(dataset)  # NEW\\n    )\\n    return dataloader\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass PyTorchMultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, num_heads, dropout=0.0, qkv_bias=False):\\n        super().__init__()\\n\\n        assert d_out % num_heads == 0, \\\"d_out is indivisible by num_heads\\\"\\n\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads\\n        self.d_out = d_out\\n\\n        self.qkv = nn.Linear(d_in, 3 * d_out, bias=qkv_bias)\\n        self.proj = nn.Linear(d_out, d_out)\\n        self.dropout = dropout\\n\\n    def forward(self, x):\\n        batch_size, num_tokens, embed_dim = x.shape\\n\\n        # (b, num_tokens, embed_dim) --> (b, num_tokens, 3 * embed_dim)\\n        qkv = self.qkv(x)\\n\\n        # (b, num_tokens, 3 * embed_dim) --> (b, num_tokens, 3, num_heads, head_dim)\\n        qkv = qkv.view(batch_size, num_tokens, 3, self.num_heads, self.head_dim)\\n\\n        # (b, num_tokens, 3, num_heads, head_dim) --> (3, b, num_heads, num_tokens, head_dim)\\n        qkv = qkv.permute(2, 0, 3, 1, 4)\\n\\n        # (3, b, num_heads, num_tokens, head_dim) -> 3 times (b, num_heads, num_tokens, head_dim)\\n        queries, keys, values = qkv\\n\\n        use_dropout = 0. if not self.training else self.dropout\\n\\n        context_vec = nn.functional.scaled_dot_product_attention(\\n            queries, keys, values, attn_mask=None, dropout_p=use_dropout, is_causal=True)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.transpose(1, 2).contiguous().view(batch_size, num_tokens, self.d_out)\\n\\n        context_vec = self.proj(context_vec)\\n\\n        return context_vec\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            nn.GELU(approximate=\\\"tanh\\\"),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = PyTorchMultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = nn.LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = nn.LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n        x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        self.trf_blocks = nn.Sequential(\\n            *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.final_norm = nn.LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n        pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n        x = self.trf_blocks(x)\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n\\ndef generate_text_simple(model, idx, max_new_tokens, context_size):\\n    # idx is (B, T) array of indices in the current context\\n    for _ in range(max_new_tokens):\\n\\n        # Crop current context if it exceeds the supported context size\\n        # E.g., if LLM supports only 5 tokens, and the context size is 10\\n        # then only the last 5 tokens are used as context\\n        idx_cond = idx[:, -context_size:]\\n\\n        # Get the predictions\\n        with torch.no_grad():\\n            logits = model(idx_cond)\\n\\n        # Focus only on the last time step\\n        # (batch, n_token, vocab_size) becomes (batch, vocab_size)\\n        logits = logits[:, -1, :]\\n\\n        # Get the idx of the vocab entry with the highest logits value\\n        idx_next = torch.argmax(logits, dim=-1, keepdim=True)  # (batch, 1)\\n\\n        # Append sampled index to the running sequence\\n        idx = torch.cat((idx, idx_next), dim=1)  # (batch, n_tokens+1)\\n\\n    return idx\\n\\n#####################################\\n# Chapter 5\\n#####################################\\n\\n\\ndef text_to_token_ids(text, tokenizer):\\n    encoded = tokenizer.encode(text)\\n    encoded_tensor = torch.tensor(encoded).unsqueeze(0)  # add batch dimension\\n    return encoded_tensor\\n\\n\\ndef token_ids_to_text(token_ids, tokenizer):\\n    flat = token_ids.squeeze(0)  # remove batch dimension\\n    return tokenizer.decode(flat.tolist())\\n\\n\\ndef calc_loss_batch(input_batch, target_batch, model, device):\\n    input_batch, target_batch = input_batch.to(device), target_batch.to(device)\\n    logits = model(input_batch)\\n    loss = torch.nn.functional.cross_entropy(logits.flatten(0, 1), target_batch.flatten())\\n    return loss\\n\\n\\ndef calc_loss_loader(data_loader, model, device, num_batches=None):\\n    total_loss = 0.\\n    if len(data_loader) == 0:\\n        return float(\\\"nan\\\")\\n    elif num_batches is None:\\n        num_batches = len(data_loader)\\n    else:\\n        num_batches = min(num_batches, len(data_loader))\\n    for i, (input_batch, target_batch) in enumerate(data_loader):\\n        if i < num_batches:\\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\\n            total_loss += loss.item()\\n        else:\\n            break\\n    return total_loss / num_batches\\n\\n\\ndef evaluate_model(model, train_loader, val_loader, device, eval_iter):\\n    model.eval()\\n    with torch.no_grad():\\n        train_loss = calc_loss_loader(train_loader, model, device, num_batches=eval_iter)\\n        val_loss = calc_loss_loader(val_loader, model, device, num_batches=eval_iter)\\n    model.train()\\n    return train_loss, val_loss\\n\\n\\ndef generate_and_print_sample(model, device, start_context):\\n    model.eval()\\n\\n    # NEW: Modify for DDP\\n    context_size = model.module.pos_emb.weight.shape[0] if isinstance(model, DDP) else model.pos_emb.weight.shape[0]\\n    encoded = text_to_token_ids(start_context, tiktoken.get_encoding(\\\"gpt2\\\")).to(device)\\n    with torch.no_grad():\\n        token_ids = generate_text_simple(\\n            model=model, idx=encoded,\\n            max_new_tokens=50, context_size=context_size\\n        )\\n        decoded_text = token_ids_to_text(token_ids, tiktoken.get_encoding(\\\"gpt2\\\"))\\n        print(decoded_text.replace(\\\"\\\\n\\\", \\\" \\\"))  # Compact print format\\n    model.train()\\n\\n\\ndef train_model_simple_with_timing(model, train_loader, val_loader, optimizer, device,\\n                                   num_epochs, eval_freq, eval_iter, start_context):\\n    train_losses, val_losses, track_tokens = [], [], []\\n    total_tokens, global_step, last_tokens = 0, -1, 0\\n\\n    # NEW: Determine the current rank (default to 0 if not distributed)\\n    rank = torch.distributed.get_rank() if torch.distributed.is_initialized() else 0\\n    # world_size = torch.distributed.get_world_size() if torch.distributed.is_initialized() else 1\\n\\n    # Variables for cumulative average tokens/sec\\n    cumulative_tokens, cumulative_time = 0.0, 0.0\\n\\n    # CUDA-specific timing setup\\n    use_cuda = device.type == \\\"cuda\\\"\\n    if use_cuda:\\n        t_start = torch.cuda.Event(enable_timing=True)\\n        t_end = torch.cuda.Event(enable_timing=True)\\n        torch.cuda.synchronize()  # Ensure all prior CUDA operations are done\\n        t_start.record()          # Start the timer for the first interval\\n    else:\\n        t0 = time.time()          # Start the timer for the first interval\\n\\n    # Main training loop\\n    for epoch in range(num_epochs):\\n        # NEW: set epoch for DistributedSampler so each process gets a unique shuffle order\\n        if isinstance(train_loader.sampler, DistributedSampler):\\n            train_loader.sampler.set_epoch(epoch)\\n\\n        model.train()\\n        for inp_batch, tgt_batch in train_loader:\\n            optimizer.zero_grad()\\n            global_step += 1\\n\\n            # Forward and backward pass\\n            loss = calc_loss_batch(inp_batch, tgt_batch, model, device)\\n            loss.backward()\\n            optimizer.step()\\n\\n            total_tokens += inp_batch.numel()\\n\\n            # At evaluation intervals, measure elapsed time and tokens per second\\n            if global_step % eval_freq == 0:\\n                # End timing for the current interval\\n                if use_cuda:\\n                    t_end.record()\\n                    torch.cuda.synchronize()  # Wait for all CUDA ops to complete.\\n                    elapsed = t_start.elapsed_time(t_end) / 1000  # Convert ms to seconds\\n                    t_start.record()  # Reset timer for the next interval\\n                else:\\n                    elapsed = time.time() - t0\\n                    t0 = time.time()  # Reset timer for the next interval\\n\\n                # Calculate local tokens processed during this interval\\n                local_interval = total_tokens - last_tokens\\n                last_tokens = total_tokens\\n\\n                # Aggregate the tokens processed over all devices\\n                local_tensor = torch.tensor([local_interval], device=device, dtype=torch.float)\\n                global_tensor = local_tensor.clone()\\n                torch.distributed.all_reduce(global_tensor, op=torch.distributed.ReduceOp.SUM)\\n                global_interval = global_tensor.item()\\n\\n                # Global tokens per second for this interval\\n                global_tps = global_interval / elapsed if elapsed > 0 else 0\\n\\n                # Update cumulative tokens (local) and aggregate globally\\n                cumulative_tokens += local_interval\\n                local_cum_tensor = torch.tensor([cumulative_tokens], device=device, dtype=torch.float)\\n                global_cum_tensor = local_cum_tensor.clone()\\n                torch.distributed.all_reduce(global_cum_tensor, op=torch.distributed.ReduceOp.SUM)\\n                global_cumulative_tokens = global_cum_tensor.item()\\n                cumulative_time += elapsed\\n                global_avg_tps = global_cumulative_tokens / cumulative_time if cumulative_time > 0 else 0\\n\\n                # Evaluate model performance (this may add overhead)\\n                train_loss, val_loss = evaluate_model(model, train_loader, val_loader, device, eval_iter)\\n                train_losses.append(train_loss)\\n                val_losses.append(val_loss)\\n                track_tokens.append(total_tokens)\\n\\n                # NEW: Only print logs once per GPU (choosing the rank 0 GPU)\\n                if rank == 0:\\n                    print(f\\\"Ep {epoch+1}, Step {global_step:06d}, \\\"\\n                          f\\\"Train: {train_loss:.3f}, Val: {val_loss:.3f}, \\\"\\n                          f\\\"Step tok/sec: {round(global_tps)}, Global avg tok/sec: {round(global_avg_tps)}\\\")\\n\\n        # NEW Only rank 0 prints the generated sample and memory usage stats\\n        if rank == 0 and epoch % 5 == 0:\\n            generate_and_print_sample(model, device, start_context)\\n\\n            # Memory stats\\n            if torch.cuda.is_available():\\n                current_device = torch.cuda.current_device()\\n                allocated = torch.cuda.memory_allocated(current_device) / 1024**3  # Convert to GB\\n                reserved = torch.cuda.memory_reserved(current_device) / 1024**3    # Convert to GB\\n\\n                print(f\\\"\\\\nAllocated memory: {allocated:.4f} GB\\\")\\n                print(f\\\"Reserved memory: {reserved:.4f} GB\\\\n\\\")\\n\\n    return train_losses, val_losses, track_tokens\\n\\n\\ndef plot_losses(epochs_seen, tokens_seen, train_losses, val_losses):\\n    fig, ax1 = plt.subplots()\\n\\n    # Plot training and validation loss against epochs\\n    ax1.plot(epochs_seen, train_losses, label=\\\"Training loss\\\")\\n    ax1.plot(epochs_seen, val_losses, linestyle=\\\"-.\\\", label=\\\"Validation loss\\\")\\n    ax1.set_xlabel(\\\"Epochs\\\")\\n    ax1.set_ylabel(\\\"Loss\\\")\\n    ax1.legend(loc=\\\"upper right\\\")\\n\\n    # Create a second x-axis for tokens seen\\n    ax2 = ax1.twiny()  # Create a second x-axis that shares the same y-axis\\n    ax2.plot(tokens_seen, train_losses, alpha=0)  # Invisible plot for aligning ticks\\n    ax2.set_xlabel(\\\"Tokens seen\\\")\\n\\n    fig.tight_layout()  # Adjust layout to make room\\n    # plt.show()\\n\\n\\n#####################################\\n# Main function calls\\n#####################################\\n\\n# NEW: Add rank and world_size\\ndef main(gpt_config, settings, rank, world_size):\\n\\n    ddp_setup(rank, world_size)  # NEW: initialize process groups\\n    device = torch.device(\\\"cuda\\\", rank)\\n\\n    torch.manual_seed(123)\\n\\n    # NEW: Print info only on 1 GPU\\n    if rank == 0:\\n        print(f\\\"PyTorch version: {torch.__version__}\\\")\\n        if torch.cuda.is_available():\\n            print(f\\\"CUDA version: {torch.version.cuda}\\\")\\n\\n            capability = torch.cuda.get_device_capability()\\n            if capability[0] >= 7:  # Volta (7.0+), Turing (7.5+), Ampere (8.0+), Hopper (9.0+)\\n                torch.set_float32_matmul_precision(\\\"high\\\")\\n                print(\\\"Uses tensor cores\\\")\\n            else:\\n                print(\\\"Tensor cores not supported on this GPU. Using default precision.\\\")\\n        print()\\n\\n    ##############################\\n    # Download data if necessary\\n    ##############################\\n\\n    file_path = \\\"middlemarch.txt\\\"\\n    url = \\\"https://www.gutenberg.org/cache/epub/145/pg145.txt\\\"\\n\\n    # NEW: Only download 1 time\\n    if rank == 0:\\n        if not os.path.exists(file_path):\\n            response = requests.get(url, timeout=30)\\n            response.raise_for_status()\\n            text_data = response.text\\n            with open(file_path, \\\"w\\\", encoding=\\\"utf-8\\\") as file:\\n                file.write(text_data)\\n    # NEW: All processes wait until rank 0 is done, using the GPU index.\\n    torch.distributed.barrier(device_ids=[device.index])\\n\\n    with open(file_path, \\\"r\\\", encoding=\\\"utf-8\\\") as file:\\n        text_data = file.read()\\n\\n    ##############################\\n    # Initialize model\\n    ##############################\\n\\n    model = GPTModel(gpt_config)\\n    model = torch.compile(model)\\n    model = model.to(device)\\n    model = model.to(torch.bfloat16)\\n    # NEW: Wrap model with DDP\\n    model = DDP(model, device_ids=[rank])\\n    optimizer = torch.optim.AdamW(\\n        model.parameters(), lr=settings[\\\"learning_rate\\\"], weight_decay=settings[\\\"weight_decay\\\"],\\n        fused=True\\n    )\\n\\n    ##############################\\n    # Set up dataloaders\\n    ##############################\\n\\n    # Train/validation ratio\\n    train_ratio = 0.90\\n    split_idx = int(train_ratio * len(text_data))\\n\\n    train_loader = create_dataloader_v1(\\n        text_data[:split_idx],\\n        batch_size=settings[\\\"batch_size\\\"],\\n        max_length=gpt_config[\\\"context_length\\\"],\\n        stride=gpt_config[\\\"context_length\\\"],\\n        drop_last=True,\\n        num_workers=4\\n    )\\n\\n    val_loader = create_dataloader_v1(\\n        text_data[split_idx:],\\n        batch_size=settings[\\\"batch_size\\\"],\\n        max_length=gpt_config[\\\"context_length\\\"],\\n        stride=gpt_config[\\\"context_length\\\"],\\n        drop_last=False,\\n        num_workers=4\\n    )\\n\\n    ##############################\\n    # Train model\\n    ##############################\\n\\n    train_losses, val_losses, tokens_seen = train_model_simple_with_timing(\\n        model=model,\\n        train_loader=train_loader,\\n        val_loader=val_loader,\\n        optimizer=optimizer,\\n        device=device,\\n        num_epochs=settings[\\\"num_epochs\\\"],\\n        eval_freq=5,\\n        eval_iter=1,\\n        start_context=\\\"Every effort moves you\\\",\\n    )\\n\\n    # NEW: Clean up distributed processes\\n    destroy_process_group()\\n\\n    return train_losses, val_losses, tokens_seen, model\\n\\n\\nif __name__ == \\\"__main__\\\":\\n\\n    # NEW: Extract rank and world size from environment variables\\n    if \\\"WORLD_SIZE\\\" in os.environ:\\n        world_size = int(os.environ[\\\"WORLD_SIZE\\\"])\\n    else:\\n        world_size = 1\\n\\n    if \\\"LOCAL_RANK\\\" in os.environ:\\n        rank = int(os.environ[\\\"LOCAL_RANK\\\"])\\n    elif \\\"RANK\\\" in os.environ:\\n        rank = int(os.environ[\\\"RANK\\\"])\\n    else:\\n        rank = 0\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50304,     # Vocabulary size\\n        \\\"context_length\\\": 1024,  # Input tokens per training example\\n        \\\"emb_dim\\\": 768,          # Embedding dimension\\n        \\\"n_heads\\\": 12,           # Number of attention heads\\n        \\\"n_layers\\\": 12,          # Number of layers\\n        \\\"drop_rate\\\": 0.1,        # Dropout rate\\n        \\\"qkv_bias\\\": False        # Query-key-value bias\\n    }\\n\\n    OTHER_SETTINGS = {\\n        \\\"learning_rate\\\": 5e-4,  # * world_size,  # NEW: Increase learning rate to account for multiple GPUs\\n        \\\"num_epochs\\\": 50,\\n        \\\"batch_size\\\": 32,\\n        \\\"weight_decay\\\": 0.1\\n    }\\n\\n    ###########################\\n    # Initiate training\\n    ###########################\\n\\n    train_losses, val_losses, tokens_seen, model = main(\\n        GPT_CONFIG_124M, OTHER_SETTINGS,\\n        rank, world_size  # NEW\\n    )\\n\\n    ###########################\\n    # After training\\n    ###########################\\n\\n    # NEW: Only create 1 plot\\n    if rank == 0:\\n        # Plot results\\n        epochs_tensor = torch.linspace(0, OTHER_SETTINGS[\\\"num_epochs\\\"], len(train_losses))\\n        plot_losses(epochs_tensor, tokens_seen, train_losses, val_losses)\\n        plt.savefig(\\\"loss.pdf\\\")\\n\\n    # Save and load model\\n    #\\n    # compiled = hasattr(model, \\\"_orig_mod\\\")\\n    # if compiled:\\n    #     torch.save(model._orig_mod.state_dict(), \\\"model.pth\\\")\\n    # else:\\n    #     torch.save(model.state_dict(), \\\"model.pth\\\")\\n    #\\n    # model = GPTModel(GPT_CONFIG_124M)\\n    # model.load_state_dict(torch.load(\\\"model.pth\\\", weights_only=True))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/10_llm-training-speed/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8d73d9845fae065ee72552ba57b76a3ffe477594cdabf1f174b6ad1ee4ab1f80\",\"content\":\"# PyTorch Performance Tips for Faster LLM Training\\n\\n\\n\\nNote that the book is written for education purposes, meaning the original code is kept purposefully simple. This is to aid readability and ensure compatibility across different hardware, including CPUs and GPUs. However, you might be curious about some more advanced PyTorch and GPU features to make the LLM training more performant.\\n\\nThis folder contains three code files that demonstrate performance optimizations for the LLM and the training function introduced in Chapter 5:\\n\\n1. [`00_orig.py`](00_orig.py): The original Chapter 5 code for CPU and single-GPU training.  \\n   \u27a4 Run via: `python 00_orig.py`\\n\\n2. [`01_opt_single_gpu.py`](01_opt_single_gpu.py): An optimized version for single-GPU training.  \\n   \u27a4 Run via: `python 01_opt_single_gpu.py`\\n\\n3. [`02_opt_multi_gpu_ddp.py`](02_opt_multi_gpu_ddp.py): An optimized version for multi-GPU training using Distributed Data Parallel (DDP).  \\n   \u27a4 Run via: `torchrun --nproc_per_node=4 02_opt_multi_gpu_ddp.py`  \\n   (**Note:** To keep the changes minimal compared to `01_opt_single_gpu.py`, this script supports multi-processing only via `torchrun` as shown above. This means multi-GPU support is **not** supported via `python 02_opt_multi_gpu_ddp.py`)\\n\\n**Note that these modifications take the training speed from 12,525 tokens per second (single A100) to 142,156 tokens per second (single A100) and 419,259 tokens per second (4x A100s).**\\n\\nI plan to expand on the differences in a more detailed write-up sometime in the future. For now, the easiest way to see what improvements have been added to the code is to open the files in Visual Studio Code and look at the differences via the \\\"Compare Selected\\\" feature.\\n\\n![VS compare](https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/llm-training-speed/vs-code-compare.png)\\n\\n![PyTorch Tips](https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/pytorch-tips/pytorch-tips.webp?1)\\n\\n\\n&nbsp;\\n## Single GPU speed comparisons\\n\\nAs mentioned above, I plan to elaborate more on the changes in the future. For now, this section contains a simple performance overview in terms of tokens/second for each modification. All experiments were run on A100 GPUs.\\n\\n&nbsp;\\n### Baseline\\n\\nNote that `00_orig.py` servers as the baseline and contains no significant modification and uses the code from Chapter 5 as is besides the following:\\n\\n- 4 times larger context length (which explains the relatively large memory footprint of `00_orig.py` compared to Chapter 5);\\n- 4-times batch size changes (another contributor to the relatively large memory footprint of `00_orig.py`);\\n- a larger public domain book to increase the training data size. \\n\\nThe hyperparameters are not very optimized for minimizing loss and reducing overfitting, and the text generated by the LLM at the very end may not be super sophisticated; however, this shouldn't matter as the main takeaway is the `tok/sec` metric that serves as a speed reference here (higher is better).\\n\\n```bash\\nubuntu@159-13-52-60:~$ python 00_orig.py\\nPyTorch version: 2.6.0+cu124\\nUsing cuda\\nCUDA version: 12.4\\n\\nEp 1, Step 000000, Train: 9.535, Val: 9.609, Step tok/sec: 7238, Avg tok/sec: 0\\nEp 1, Step 000015, Train: 6.201, Val: 6.152, Step tok/sec: 12545, Avg tok/sec: 12545\\nEp 1, Step 000030, Train: 5.663, Val: 5.688, Step tok/sec: 12490, Avg tok/sec: 12517\\nEp 1, Step 000045, Train: 5.316, Val: 5.362, Step tok/sec: 12541, Avg tok/sec: 12525\\nEvery effort moves you, and's, and I am not be a\\n\\n...\\n\\nEp 15, Step 000735, Train: 0.227, Val: 6.818, Step tok/sec: 11599, Avg tok/sec: 12248\\nEp 15, Step 000750, Train: 0.300, Val: 6.895, Step tok/sec: 12530, Avg tok/sec: 12253\\nEp 15, Step 000765, Train: 0.150, Val: 6.914, Step tok/sec: 12532, Avg tok/sec: 12259\\nEvery effort moves you like best to think which he held in the room in him, the interest was the night, the realities of the affairs Bulstrode's duty, now!' the fact is another man, conquests\\n\\nAllocated memory: 2.5069 GB\\nReserved memory: 26.2617 GB\\n```\\n\\nNote that `01_opt_single_gpu.py` contains all the modifications listed sequentially below. \\n\\nThe comparison is always based on the average tok/sec and allocated memory after the first epoch from the previous section.\\n\\n&nbsp;\\n### 1. Create causal mask on the fly\\n\\n- Instead of saving the causal mask, this creates the causal mask on the fly to reduce memory usage (here it has minimal effect, but it can add up in long-context size models like Llama 3.2 with 131k-input-tokens support)\\n\\nBefore:\\n- `Avg tok/sec: 12525`\\n- `Reserved memory: 26.2617 GB`\\n\\nAfter:\\n- `Avg tok/sec: 12526`\\n- `Reserved memory: 26.2422 GB`\\n\\n&nbsp;\\n### 2. Use  tensor cores\\n\\n- Uses tensor cores (only works for Ampere GPUs like A100 and newer)\\n\\nBefore:\\n- `Avg tok/sec: 12526`\\n- `Reserved memory: 26.2422 GB`\\n\\nAfter:\\n- `Avg tok/sec: 27648`\\n- `Reserved memory: 26.2422 GB`\\n\\n&nbsp;\\n### 3. Fused AdamW optimizer\\n\\n- Uses the fused kernels for `AdamW` by setting `fused=True`\\n\\nBefore:\\n- `Avg tok/sec: 27648`\\n- `Reserved memory: 26.2422 GB`\\n\\nAfter:\\n- `Avg tok/sec: 28399`\\n- `Reserved memory: 26.2422 GB`\\n\\n&nbsp;\\n### 4. Pinned memory in the data loader\\n\\n- Uses `pin_memory=True` in the data loaders to pre-allocate and re-use GPU memory\\n\\nBefore:\\n- `Avg tok/sec: 28399`\\n- `Reserved memory: 26.2422 GB`\\n\\nAfter:\\n- `Avg tok/sec: 28402`\\n- `Reserved memory: 26.2422 GB`\\n\\n&nbsp;\\n### 5. Using bfloat16 precision\\n\\n- Switches from 32-bit float to 16-bit brain float (bfloat16) precision (for more on this topic, see my [article here](https://magazine.sebastianraschka.com/p/the-missing-bits-llama-2-weights))\\n\\nBefore:\\n- `Avg tok/sec: 28402`\\n- `Reserved memory: 26.2422 GB`\\n\\nAfter:\\n- `Avg tok/sec: 45486`\\n- `Reserved memory: 13.7871 GB`\\n\\n&nbsp;\\n### 6. Replacing from-scratch code by PyTorch classes\\n\\n- Replaces the LayerNorm and GeLU from-scratch implementation by PyTorch's native implementations\\n\\nBefore:\\n- `Avg tok/sec: 45486`\\n- `Reserved memory: 13.7871 GB`\\n\\nAfter:\\n- `Avg tok/sec: 55256`\\n- `Reserved memory: 11.5645 GB`\\n\\n&nbsp;\\n### 7. Using FlashAttention\\n\\n- Uses PyTorch's self-attention function with FlashAttention instead of our from-scratch multi-head attention implementation.\\n\\n\\nBefore:\\n- `Avg tok/sec: 55256`\\n- `Reserved memory: 11.5645 GB`\\n\\nAfter:\\n- `Avg tok/sec: 91901`\\n- `Reserved memory: 5.9004 GB`\\n\\n&nbsp;\\n### 8. Using `pytorch.compile`\\n\\n- Uses `torch.compile(model)`. Note that the first iterations are always slow before it picks up speed. Since the `Avg tok/sec` measurement only includes the first row from the average calculation, we now use the `Step tok/sec` at the end of epoch 1.\\n\\n\\nBefore:\\n- `Avg tok/sec: 91901`\\n- `Reserved memory: 5.9004 GB`\\n\\nAfter:\\n- `Step tok/sec: 112046`\\n- `Reserved memory: 6.1875 GB`\\n\\n<br>\\n\\n---\\n\\n**Windows note**\\n\\n- Compilation can be tricky on Windows\\n- `torch.compile()` uses Inductor, which JIT-compiles kernels and needs a working C/C++ toolchain\\n- For CUDA, Inductor also depends on Triton, available via the community package `triton-windows`\\n  - If you see `cl not found`, [install Visual Studio Build Tools with the \\\"C++ workload\\\"](https://learn.microsoft.com/en-us/cpp/build/vscpp-step-0-installation?view=msvc-170) and run Python from the \\\"x64 Native Tools\\\" prompt\\n  - If you see `triton not found` with CUDA, install `triton-windows` (for example, `uv pip install \\\"triton-windows<3.4\\\"`).\\n- For CPU, a reader further recommended following this [PyTorch Inductor guide for Windows](https://docs.pytorch.org/tutorials/unstable/inductor_windows.html)\\n  - Here, it is important to install the English language package when installing Visual Studio 2022 to avoid a UTF-8 error\\n  - Also, please note that the code needs to be run via the \\\"Visual Studio 2022 Developer Command Prompt\\\" rather than a notebook\\n- If this setup proves tricky, you can skip compilation; **compilation is optional, and all code examples work fine without it**\\n\\n---\\n\\n&nbsp;\\n### 9. Vocabulary padding\\n\\n- Here, we slightly increase the vocabulary size from 50,257 to 50,304, which is the nearest multiple of 64. This tip was suggested to me by my former colleague Carlos Mocholi, who mentioned that it originally came from Andrej Karpathy (likely from [this post](https://x.com/karpathy/status/1621578354024677377)). Karpathy's recommendation is based on an interaction with the PyTorch team, who gave advice on `torch.compile` as mentioned by [Bertrand Maher](https://www.linkedin.com/feed/update/urn:li:activity:7309569006057795584?commentUrn=urn%3Ali%3Acomment%3A%28activity%3A7309569006057795584%2C7309754284185669632%29&dashCommentUrn=urn%3Ali%3Afsd_comment%3A%287309754284185669632%2Curn%3Ali%3Aactivity%3A7309569006057795584%29). A good resource for this are [NVIDIA's guidelines on tensor shapes](https://docs.nvidia.com/deeplearning/performance/mixed-precision-training/index.html#tensor-core-shape), where batch sizes and linear layer dimensions are commonly chosen as multiples of certain values. Furthermore, the vocab-padding trick was described by NVIDIA's Megatron team a long time ago (see the 2019 [Megatron-LM: Training Multi-Billion Parameter Language Models Using Model Parallelism](https://arxiv.org/abs/1909.08053) paper).\\n\\nBefore:\\n- `Step tok/sec: 112046`\\n- `Reserved memory: 6.1875 GB`\\n\\nAfter:\\n- `Step tok/sec: 127345`\\n- `Reserved memory: 5.8906 GB`\\n\\n&nbsp;\\n### 10. Increasing the batch size\\n\\n- Lastly, we increase the batch size to the largest power of 2 supported by the GPU\\n\\nBefore:\\n- `Step tok/sec: 127345`\\n- `Reserved memory: 5.8906 GB`\\n\\nAfter:\\n- `Step tok/sec: 142156`\\n- `Reserved memory: 22.5078 GB`\\n\\n\\n&nbsp;\\n## Multi-GPU speed comparisons\\n\\nThis may not be an entirely fair comparison as we now use 4 GPUs instead of 1, but using distributed data parallelism, the fastest multi-GPU technique that can be used if the training is not bottle-necked by limited GPU memory, can, of course, result in noticeable speed-ups:\\n\\nBefore (single GPU):\\n- `Step tok/sec: 142156`\\n- `Reserved memory: 22.5078 GB`\\n\\nAfter (4 GPUs):\\n- `Step tok/sec: 419259`\\n- `Reserved memory: 22.7969 GB`\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/11_qwen3/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"df03d79f3f634407b58c619845807939dd9917ad12a1a5550da4425aa1e44109\",\"content\":\"# Qwen3 From Scratch\\n\\nThis [standalone-qwen3.ipynb](standalone-qwen3.ipynb) Jupyter notebook in this folder contains a from-scratch implementation of Qwen3 0.6B, 1.7B, 4B, 8B, and 32B.\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/qwen/qwen-overview.webp\\\">\\n\\n\\nThis [standalone-qwen3-moe.ipynb](standalone-qwen3-moe.ipynb) and [standalone-qwen3-moe-plus-kvcache.ipynb](standalone-qwen3-moe-plus-kvcache.ipynb) Jupyter notebooks in this folder contain a from-scratch implementation of 30B-A3B Mixture-of-Experts (MoE), including the Thinking, Instruct, and Coder model variants.\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/qwen/qwen3-coder-flash-overview.webp?123\\\" width=\\\"430px\\\">\\n\\n&nbsp;\\n# Qwen3 from-scratch code\\n\\nThe standalone notebooks in this folder contain from-scratch codes in linear fashion:\\n\\n1. [standalone-qwen3.ipynb](standalone-qwen3.ipynb): The dense Qwen3 model without bells and whistles\\n2. [standalone-qwen3-plus-kvcache.ipynb](standalone-qwen3-plus-kvcache.ipynb): Same as above but with KV cache for better inference efficiency\\n3. [standalone-qwen3-moe.ipynb](standalone-qwen3-moe.ipynb): Like the first notebook but the Mixture-of-Experts (MoE) variant\\n4. [standalone-qwen3-moe-plus-kvcache.ipynb](standalone-qwen3-moe-plus-kvcache.ipynb): Same as above but with KV cache for better inference efficiency\\n\\nAlternatively, I also organized the code into a Python package [here](../../pkg/llms_from_scratch/) (including unit tests and CI), which you can run as described below.\\n\\n&nbsp;\\n# Training\\n\\nThe `Qwen3Model` class is implemented in a similar style as the `GPTModel` class, so it can be used as a drop-in replacement for training in chapter 5 and finetuning in chapters 6 and 7.\\n\\n\\n&nbsp;\\n# Using Qwen3 via the `llms-from-scratch` package\\n\\nFor an easy way to use the Qwen3 from-scratch implementation, you can also use the `llms-from-scratch` PyPI package based on the source code in this repository at [pkg/llms_from_scratch](../../pkg/llms_from_scratch).\\n\\n&nbsp;\\n#### 1) Installation\\n\\n```bash\\npip install llms_from_scratch tokenizers\\n```\\n\\n&nbsp;\\n#### 2) Model and text generation settings\\n\\nSpecify which model to use:\\n\\n```python\\nUSE_REASONING_MODEL = True\\n# Uses the base model if USE_REASONING_MODEL = False\\n\\nUSE_INSTRUCT_MODEL = False\\n# Uses the instruct mode (without reasoning) if \\n# USE_REASONING_MODEL = True\\n# USE_INSTRUCT_MODEL = True\\n# This setting does have no effect if USE_REASONING_MODEL = False\\n\\n\\n# Use\\n# USE_REASONING_MODEL = True\\n# For Qwen3 Coder Flash model as well\\n```\\n\\nBasic text generation settings that can be defined by the user. With 150 tokens, the 0.6B model requires approximately 1.5 GB memory.\\n\\n```python\\nMAX_NEW_TOKENS = 150\\nTEMPERATURE = 0.\\nTOP_K = 1\\n```\\n\\n&nbsp;\\n#### 3a) Weight download and loading of the 0.6B model\\n\\nThe following automatically downloads the weight file based on the model choice (reasoning or base) above. Note that this section focuses on the 0.6B model. Skip this section and continue with section 3b) if you want to work with any of the larger models (1.7B, 4B, 8B, or 32B).\\n\\n```python\\nfrom llms_from_scratch.qwen3 import download_from_huggingface\\n\\nrepo_id = \\\"rasbt/qwen3-from-scratch\\\"\\n\\nif USE_REASONING_MODEL:\\n    filename = \\\"qwen3-0.6B.pth\\\"\\n    local_dir = \\\"Qwen3-0.6B\\\"    \\nelse:\\n    filename = \\\"qwen3-0.6B-base.pth\\\"   \\n    local_dir = \\\"Qwen3-0.6B-Base\\\"\\n\\ndownload_from_huggingface(\\n    repo_id=repo_id,\\n    filename=filename,\\n    local_dir=local_dir\\n)\\n```\\n\\nThe model weights are then loaded as follows:\\n\\n```python\\nfrom pathlib import Path\\nimport torch\\n\\nfrom llms_from_scratch.qwen3 import Qwen3Model, QWEN_CONFIG_06_B\\n\\nmodel_file = Path(local_dir) / filename\\n\\nmodel = Qwen3Model(QWEN_CONFIG_06_B)\\nmodel.load_state_dict(torch.load(model_file, weights_only=True, map_location=\\\"cpu\\\"))\\n\\ndevice = (\\n    torch.device(\\\"cuda\\\") if torch.cuda.is_available() else\\n    torch.device(\\\"mps\\\") if torch.backends.mps.is_available() else\\n    torch.device(\\\"cpu\\\")\\n)\\nmodel.to(device);\\n```\\n\\n&nbsp;\\n#### 3b) Weight download and loading of the larger Qwen models\\n\\nIf you are interested in working with any of the larger Qwen models, for instance, 1.7B, 4B, 8B, or 32B, please use the following code below instead of the code under 3a), which requires additional code dependencies:\\n\\n```bash\\npip install safetensors huggingface_hub\\n```\\n\\nThen use the following code (make appropriate changes to `USE_MODEL` to select the desired model size)\\n\\n```python\\nUSE_MODEL = \\\"1.7B\\\"\\n\\nif USE_MODEL == \\\"1.7B\\\":\\n    from llms_from_scratch.qwen3 import QWEN3_CONFIG_1_7B as QWEN3_CONFIG\\nelif USE_MODEL == \\\"4B\\\":\\n    from llms_from_scratch.qwen3 import QWEN3_CONFIG_4B as QWEN3_CONFIG\\nelif USE_MODEL == \\\"8B\\\":\\n    from llms_from_scratch.qwen3 import QWEN3_CONFIG_8B as QWEN3_CONFIG\\nelif USE_MODEL == \\\"14B\\\":\\n    from llms_from_scratch.qwen3 import QWEN3_CONFIG_14B as QWEN3_CONFIG\\nelif USE_MODEL == \\\"32B\\\":\\n    from llms_from_scratch.qwen3 import QWEN3_CONFIG_32B as QWEN3_CONFIG\\nelif USE_MODEL == \\\"30B-A3B\\\":\\n    from llms_from_scratch.qwen3 import QWEN3_CONFIG_30B_A3B as QWEN3_CONFIG\\nelse:\\n    raise ValueError(\\\"Invalid USE_MODEL name.\\\")\\n    \\nrepo_id = f\\\"Qwen/Qwen3-{USE_MODEL}\\\"\\nlocal_dir = f\\\"Qwen3-{USE_MODEL}\\\"\\n\\nif not USE_REASONING_MODEL:\\n  repo_id = f\\\"{repo_id}-Base\\\"\\n  local_dir = f\\\"{local_dir}-Base\\\"\\n```\\n\\nNow, download and load the weights into the `model`:\\n\\n```python\\nfrom llms_from_scratch.qwen3 import (\\n    Qwen3Model,\\n    download_from_huggingface_from_snapshots,\\n    load_weights_into_qwen\\n)\\n\\ndevice = (\\n    torch.device(\\\"cuda\\\") if torch.cuda.is_available() else\\n    torch.device(\\\"mps\\\") if torch.backends.mps.is_available() else\\n    torch.device(\\\"cpu\\\")\\n)\\n\\nwith device:\\n    model = Qwen3Model(QWEN3_CONFIG)\\n\\nweights_dict = download_from_huggingface_from_snapshots(\\n    repo_id=repo_id,\\n    local_dir=local_dir\\n)\\nload_weights_into_qwen(model, QWEN3_CONFIG, weights_dict)\\nmodel.to(device)  # only required for the MoE models\\ndel weights_dict  # delete weight dictionary to free up disk space\\n```\\n\\n\\n&nbsp;\\n\\n#### 4) Initialize tokenizer\\n\\nThe following code downloads and initializes the tokenizer:\\n\\n```python\\nfrom llms_from_scratch.qwen3 import Qwen3Tokenizer\\n\\nif USE_REASONING_MODEL:\\n    tok_filename = \\\"tokenizer.json\\\"    \\nelse:\\n    tok_filename = \\\"tokenizer-base.json\\\"   \\n\\ntokenizer = Qwen3Tokenizer(\\n    tokenizer_file_path=tokenizer_file_path,\\n    repo_id=repo_id,\\n    apply_chat_template=USE_REASONING_MODEL,\\n    add_generation_prompt=USE_REASONING_MODEL,\\n    add_thinking=not USE_INSTRUCT_MODEL\\n)\\n```\\n\\n\\n\\n&nbsp;\\n\\n#### 5) Generating text\\n\\nLastly, we can generate text via the following code:\\n\\n```python\\nprompt = \\\"Give me a short introduction to large language models.\\\"\\ninput_token_ids = tokenizer.encode(prompt)\\n```\\n\\n\\n\\n\\n\\n```python\\nfrom llms_from_scratch.ch05 import generate\\nimport time\\n\\ntorch.manual_seed(123)\\n\\nstart = time.time()\\n\\noutput_token_ids = generate(\\n    model=model,\\n    idx=torch.tensor(input_token_ids, device=device).unsqueeze(0),\\n    max_new_tokens=150,\\n    context_size=QWEN_CONFIG_06_B[\\\"context_length\\\"],\\n    top_k=1,\\n    temperature=0.\\n)\\n\\ntotal_time = time.time() - start\\nprint(f\\\"Time: {total_time:.2f} sec\\\")\\nprint(f\\\"{int(len(output_token_ids[0])/total_time)} tokens/sec\\\")\\n\\nif torch.cuda.is_available():\\n    max_mem_bytes = torch.cuda.max_memory_allocated()\\n    max_mem_gb = max_mem_bytes / (1024 ** 3)\\n    print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\noutput_text = tokenizer.decode(output_token_ids.squeeze(0).tolist())\\n\\nprint(\\\"\\\\n\\\\nOutput text:\\\\n\\\\n\\\", output_text + \\\"...\\\")\\n```\\n\\nWhen using the Qwen3 0.6B reasoning model, the output should look similar to the one shown below (this was run on an A100):\\n\\n```\\nTime: 6.35 sec\\n25 tokens/sec\\nMax memory allocated: 1.49 GB\\n\\n\\nOutput text:\\n\\n <|im_start|>user\\nGive me a short introduction to large language models.<|im_end|>\\nLarge language models (LLMs) are advanced artificial intelligence systems designed to generate human-like text. They are trained on vast amounts of text data, allowing them to understand and generate coherent, contextually relevant responses. LLMs are used in a variety of applications, including chatbots, virtual assistants, content generation, and more. They are powered by deep learning algorithms and can be fine-tuned for specific tasks, making them versatile tools for a wide range of industries.<|endoftext|>Human resources department of a company is planning to hire 100 new employees. The company has a budget of $100,000 for the recruitment process. The company has a minimum wage of $10 per hour. The company has a total of...\\n```\\n\\n\\n\\nFor the larger models, you may prefer the streaming variant, which prints each token as soon as it's generated:\\n\\n```python\\nfrom llms_from_scratch.generate import generate_text_simple_stream\\n\\ninput_token_ids_tensor = torch.tensor(input_token_ids, device=device).unsqueeze(0)\\n\\nfor token in generate_text_simple_stream(\\n    model=model,\\n    token_ids=input_token_ids_tensor,\\n    max_new_tokens=150,\\n    eos_token_id=tokenizer.eos_token_id\\n):\\n    token_id = token.squeeze(0).tolist()\\n    print(\\n        tokenizer.decode(token_id),\\n        end=\\\"\\\",\\n        flush=True\\n    )\\n```\\n\\n```\\n <|im_start|>user\\nGive me a short introduction to large language models.<|im_end|>\\nLarge language models (LLMs) are advanced artificial intelligence systems designed to generate human-like text. They are trained on vast amounts of text data, allowing them to understand and generate coherent, contextually relevant responses. LLMs are used in a variety of applications, including chatbots, virtual assistants, content generation, and more. They are powered by deep learning algorithms and can be fine-tuned for specific tasks, making them versatile tools for a wide range of industries.<|endoftext|>Human resources department of a company is planning to hire 100 new employees. The company has a budget of $100,000 for the recruitment process. The company has a minimum wage of $10 per hour. The company has a total of...\\n```\\n\\n\\n\\n&nbsp;\\n\\n#### Pro tip 1: speed up inference with compilation\\n\\n\\nFor up to a 4\u00d7 speed-up, replace\\n\\n```python\\nmodel.to(device)\\n```\\n\\nwith\\n\\n```python\\nmodel.to(device)\\nmodel = torch.compile(model)\\n```\\n\\nNote: There is a significant multi-minute upfront cost when compiling, and the speed-up takes effect after the first `generate` call. \\n\\nThe following table shows a performance comparison on an A100 for consequent `generate` calls:\\n\\n|                          | Hardware        | Tokens/sec | Memory   |\\n| ------------------------ | ----------------|----------- | -------- |\\n| Qwen3Model 0.6B          | Nvidia A100 GPU | 25         | 1.49 GB  |\\n| Qwen3Model 0.6B compiled | Nvidia A100 GPU | 107        | 1.99 GB  |\\n\\n\\n&nbsp;\\n#### Pro tip 2: speed up inference with KV cache\\n\\nYou can significantly boost inference performance using the KV cache `Qwen3Model` drop-in replacement when running the model on a CPU. (See my [Understanding and Coding the KV Cache in LLMs from Scratch](https://magazine.sebastianraschka.com/p/coding-the-kv-cache-in-llms) article to learn more about KV caches.)\\n\\n```python\\nfrom llms_from_scratch.kv_cache.qwen3 import Qwen3Model\\nfrom llms_from_scratch.kv_cache.generate import generate_text_simple\\n\\nmodel = Qwen3Model(QWEN_CONFIG_06_B)\\n# ...\\ntoken_ids = generate_text_simple(\\n    model=model,\\n    idx=text_to_token_ids(PROMPT, tokenizer).to(device),\\n    max_new_tokens=MAX_NEW_TOKENS,\\n    context_size=QWEN_CONFIG_06_B[\\\"context_length\\\"],\\n)\\n```\\n\\nNote that the peak memory usage is only listed for Nvidia CUDA devices, as it is easier to calculate. However, the memory usage on other devices is likely similar as it uses a similar precision format, and the KV cache storage results in even lower memory usage here for the generated 150-token text (however, different devices may implement matrix multiplication differently and may result in different peak memory requirements; and KV-cache memory may increase prohibitively for longer contexts lengths).\\n\\n| Model           | Mode              | Hardware        | Tokens/sec | GPU Memory (VRAM) |\\n| --------------- | ----------------- | --------------- | ---------- | ----------------- |\\n| Qwen3Model 0.6B | Regular           | Mac Mini M4 CPU | 1          | -                 |\\n| Qwen3Model 0.6B | Regular compiled  | Mac Mini M4 CPU | 1          | -                 |\\n| Qwen3Model 0.6B | KV cache          | Mac Mini M4 CPU | 80         | -                 |\\n| Qwen3Model 0.6B | KV cache compiled | Mac Mini M4 CPU | 137        | -                 |\\n|                 |                   |                 |            |                   |\\n| Qwen3Model 0.6B | Regular           | Mac Mini M4 GPU | 21         | -                 |\\n| Qwen3Model 0.6B | Regular compiled  | Mac Mini M4 GPU | Error      | -                 |\\n| Qwen3Model 0.6B | KV cache          | Mac Mini M4 GPU | 28         | -                 |\\n| Qwen3Model 0.6B | KV cache compiled | Mac Mini M4 GPU | Error      | -                 |\\n|                 |                   |                 |            |                   |\\n| Qwen3Model 0.6B | Regular           | Nvidia A100 GPU | 26         | 1.49 GB           |\\n| Qwen3Model 0.6B | Regular compiled  | Nvidia A100 GPU | 107        | 1.99 GB           |\\n| Qwen3Model 0.6B | KV cache          | Nvidia A100 GPU | 25         | 1.47 GB           |\\n| Qwen3Model 0.6B | KV cache compiled | Nvidia A100 GPU | 90         | 1.48 GB           |\\n\\nNote that all settings above have been tested to produce the same text outputs.\\n\\n\\n\\n&nbsp;\\n\\n#### Pro tip 3: batched inference\\n\\nWe can further increase the throughput via batched inference. While it's not an apples-to-apples comparison, as we are now running inference with a higher number of input sequences, this increases the tokens per second throughput while trading it off against increased memory usage.\\n\\nThis only requires a small code modification with respect to preparing the prompt. For example, consider this batched prompt below:\\n\\n```python\\nfrom llms_from_scratch.ch04 import generate_text_simple\\nfrom llms_from_scratch.qwen3 import Qwen3Model, QWEN_CONFIG_06_B\\n# ...\\n\\nprompts = [\\n    \\\"Give me a short introduction to neural networks.\\\",\\n    \\\"Give me a short introduction to machine learning.\\\",\\n    \\\"Give me a short introduction to deep learning models.\\\",\\n    \\\"Give me a short introduction to natural language processing.\\\",\\n    \\\"Give me a short introduction to generative AI systems.\\\",\\n    \\\"Give me a short introduction to transformer architectures.\\\",\\n    \\\"Give me a short introduction to supervised learning methods.\\\",\\n    \\\"Give me a short introduction to unsupervised learning.\\\",\\n]\\n\\ntokenized_prompts = [tokenizer.encode(p) for p in prompts]\\nmax_len = max(len(t) for t in tokenized_prompts)\\npadded_token_ids = [\\n    t + [tokenizer.pad_token_id] * (max_len - len(t)) for t in tokenized_prompts\\n]\\ninput_tensor = torch.tensor(padded_token_ids).to(device)\\n\\noutput_token_ids = generate_text_simple(\\n    model=model,\\n    idx=input_tensor,\\n    max_new_tokens=150,\\n    context_size=QWEN_CONFIG_06_B[\\\"context_length\\\"],\\n)\\n```\\n\\nThe code for the KV cache version is similar, except that it requires using these drop-in replacements:\\n\\n```python\\nfrom llms_from_scratch.kv_cache_batched.generate import generate_text_simple\\nfrom llms_from_scratch.kv_cache_batched.qwen3 import Qwen3Model\\n```\\n\\n\\nThe experiments below are run with a batch size of 8.\\n\\n| Model            | Mode              | Hardware        | Batch size | Tokens/sec | GPU Memory (VRAM) |\\n| ---------------- | ----------------- | --------------- | ---------- | ---------- | ----------------- |\\n| Qwen3Model  0.6B | Regular           | Mac Mini M4 CPU | 8          | 2          | -                 |\\n| Qwen3Model 0.6B  | Regular compiled  | Mac Mini M4 CPU | 8          | -          | -                 |\\n| Qwen3Model 0.6B  | KV cache          | Mac Mini M4 CPU | 8          | 92         | -                 |\\n| Qwen3Model 0.6B  | KV cache compiled | Mac Mini M4 CPU | 8          | 128        | -                 |\\n|                  |                   |                 |            |            |                   |\\n| Qwen3Model 0.6B  | Regular           | Mac Mini M4 GPU | 8          | 36         | -                 |\\n| Qwen3Model 0.6B  | Regular compiled  | Mac Mini M4 GPU | 8          | -          | -                 |\\n| Qwen3Model 0.6B  | KV cache          | Mac Mini M4 GPU | 8          | 61         | -                 |\\n| Qwen3Model 0.6B  | KV cache compiled | Mac Mini M4 GPU | 8          | -          | -                 |\\n|                  |                   |                 |            |            |                   |\\n| Qwen3Model 0.6B  | Regular           | Nvidia A100 GPU | 8          | 184        | 2.19 GB           |\\n| Qwen3Model 0.6B  | Regular compiled  | Nvidia A100 GPU | 8          | 351        | 2.19 GB           |\\n| Qwen3Model 0.6B  | KV cache          | Nvidia A100 GPU | 8          | 140        | 3.13 GB           |\\n| Qwen3Model 0.6B  | KV cache compiled | Nvidia A100 GPU | 8          | 280        | 1.75 GB           |\\n\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/11_qwen3/qwen3-chat-interface/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"27ccad0925bafbdaa47b76d9bfdf9e80452b2c796c933eb45d601e41747ff83e\",\"content\":\"# Qwen3 From Scratch with Chat Interface\\n\\n\\n\\nThis bonus folder contains code for running a ChatGPT-like user interface to interact with the pretrained Qwen3 model.\\n\\n\\n\\n![Chainlit UI example](https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/qwen/qwen3-chainlit.gif)\\n\\n\\n\\nTo implement this user interface, we use the open-source [Chainlit Python package](https://github.com/Chainlit/chainlit).\\n\\n&nbsp;\\n## Step 1: Install dependencies\\n\\nFirst, we install the `chainlit` package and dependencies from the [requirements-extra.txt](requirements-extra.txt) list via\\n\\n```bash\\npip install -r requirements-extra.txt\\n```\\n\\nOr, if you are using `uv`:\\n\\n```bash\\nuv pip install -r requirements-extra.txt\\n```\\n\\n\\n\\n&nbsp;\\n\\n## Step 2: Run `app` code\\n\\nThis folder contains 2 files:\\n\\n1. [`qwen3-chat-interface.py`](qwen3-chat-interface.py): This file loads and uses the Qwen3 0.6B model in thinking mode. \\n2. [`qwen3-chat-interface-multiturn.py`](qwen3-chat-interface-multiturn.py): The same as above, but configured to remember the message history.\\n\\n(Open and inspect these files to learn more.)\\n\\nRun one of the following commands from the terminal to start the UI server:\\n\\n```bash\\nchainlit run qwen3-chat-interface.py\\n```\\n\\nor, if you are using `uv`:\\n\\n```bash\\nuv run chainlit run qwen3-chat-interface.py\\n```\\n\\nRunning one of the commands above should open a new browser tab where you can interact with the model. If the browser tab does not open automatically, inspect the terminal command and copy the local address into your browser address bar (usually, the address is `http://localhost:8000`).\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/11_qwen3/qwen3-chat-interface/qwen3-chat-interface-multiturn.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b13be60591d90159ed3ba507d6a0dc0e9bd82938b08bc6c0e598294fe07c41c2\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport torch\\nimport chainlit\\n\\n# For llms_from_scratch installation instructions, see:\\n# https://github.com/rasbt/LLMs-from-scratch/tree/main/pkg\\nfrom llms_from_scratch.kv_cache.qwen3 import (\\n    Qwen3Model,\\n    Qwen3Tokenizer,\\n    download_from_huggingface_from_snapshots,\\n    load_weights_into_qwen\\n)\\nfrom llms_from_scratch.kv_cache.generate import (\\n    generate_text_simple_stream,\\n    trim_input_tensor\\n)\\n\\n# ============================================================\\n# EDIT ME: Simple configuration\\n# ============================================================\\nMODEL = \\\"0.6B\\\"            # options: \\\"0.6B\\\",\\\"1.7B\\\",\\\"4B\\\",\\\"8B\\\",\\\"14B\\\",\\\"32B\\\",\\\"30B-A3B\\\"\\nREASONING = True          # True = \\\"thinking\\\" chat model, False = Base\\nDEVICE = \\\"auto\\\"           # \\\"auto\\\" | \\\"cuda\\\" | \\\"mps\\\" | \\\"cpu\\\"\\nMAX_NEW_TOKENS = 38912\\nLOCAL_DIR = None          # e.g., \\\"Qwen3-0.6B-Base\\\"; None auto-selects\\n# ============================================================\\n\\n\\ndef get_qwen_config(name):\\n    if name == \\\"0.6B\\\":\\n        from llms_from_scratch.qwen3 import QWEN_CONFIG_06_B as QWEN3_CONFIG\\n    elif name == \\\"1.7B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_1_7B as QWEN3_CONFIG\\n    elif name == \\\"4B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_4B as QWEN3_CONFIG\\n    elif name == \\\"8B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_8B as QWEN3_CONFIG\\n    elif name == \\\"14B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_14B as QWEN3_CONFIG\\n    elif name == \\\"32B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_32B as QWEN3_CONFIG\\n    elif name == \\\"30B-A3B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_30B_A3B as QWEN3_CONFIG\\n    else:\\n        raise ValueError(f\\\"Invalid model name: {name}\\\")\\n    return QWEN3_CONFIG\\n\\n\\ndef build_repo_and_local(model_name, reasoning, local_dir_arg):\\n    base = f\\\"Qwen3-{model_name}\\\"\\n    repo_id = f\\\"Qwen/{base}-Base\\\" if not reasoning else f\\\"Qwen/{base}\\\"\\n    local_dir = local_dir_arg if local_dir_arg else (f\\\"{base}-Base\\\" if not reasoning else base)\\n    return repo_id, local_dir\\n\\n\\ndef get_device(name):\\n    if name == \\\"auto\\\":\\n        if torch.cuda.is_available():\\n            return torch.device(\\\"cuda\\\")\\n        elif torch.backends.mps.is_available():\\n            return torch.device(\\\"mps\\\")\\n        else:\\n            return torch.device(\\\"cpu\\\")\\n    elif name == \\\"cuda\\\":\\n        return torch.device(\\\"cuda\\\")\\n    elif name == \\\"mps\\\":\\n        return torch.device(\\\"mps\\\")\\n    else:\\n        return torch.device(\\\"cpu\\\")\\n\\n\\ndef get_model_and_tokenizer(qwen3_config, repo_id, local_dir, device, use_reasoning):\\n    model = Qwen3Model(qwen3_config)\\n    weights_dict = download_from_huggingface_from_snapshots(\\n        repo_id=repo_id,\\n        local_dir=local_dir\\n    )\\n    load_weights_into_qwen(model, qwen3_config, weights_dict)\\n    del weights_dict\\n\\n    model.to(device)  # safe for all but required by the MoE model\\n    model.eval()\\n\\n    tok_filename = \\\"tokenizer.json\\\"\\n    tokenizer = Qwen3Tokenizer(\\n        tokenizer_file_path=tok_filename,\\n        repo_id=repo_id,\\n        apply_chat_template=False,    # disable to avoid double-wrapping prompts in history\\n        add_generation_prompt=False,  # we add the assistant header manually\\n        add_thinking=use_reasoning\\n    )\\n    return model, tokenizer\\n\\n\\ndef build_prompt_from_history(history, add_assistant_header=True):\\n    \\\"\\\"\\\"\\n    history: [{\\\"role\\\": \\\"system\\\"|\\\"user\\\"|\\\"assistant\\\", \\\"content\\\": str}, ...]\\n    \\\"\\\"\\\"\\n    parts = []\\n    for m in history:\\n        role = m[\\\"role\\\"]\\n        content = m[\\\"content\\\"]\\n        parts.append(f\\\"<|im_start|>{role}\\\\n{content}<|im_end|>\\\\n\\\")\\n\\n    if add_assistant_header:\\n        parts.append(\\\"<|im_start|>assistant\\\\n\\\")\\n    return \\\"\\\".join(parts)\\n\\n\\nQWEN3_CONFIG = get_qwen_config(MODEL)\\nREPO_ID, LOCAL_DIR = build_repo_and_local(MODEL, REASONING, LOCAL_DIR)\\nDEVICE = get_device(DEVICE)\\nMODEL, TOKENIZER = get_model_and_tokenizer(QWEN3_CONFIG, REPO_ID, LOCAL_DIR, DEVICE, REASONING)\\n\\n# Even though the official TOKENIZER.eos_token_id is either <|im_end|> (reasoning)\\n# or <|endoftext|> (base), the reasoning model sometimes emits both.\\nEOS_TOKEN_IDS = (TOKENIZER.encode(\\\"<|im_end|>\\\")[0], TOKENIZER.encode(\\\"<|endoftext|>\\\")[0])\\n\\n\\n@chainlit.on_chat_start\\nasync def on_start():\\n    chainlit.user_session.set(\\\"history\\\", [])\\n    chainlit.user_session.get(\\\"history\\\").append(\\n        {\\\"role\\\": \\\"system\\\", \\\"content\\\": \\\"You are a helpful assistant.\\\"}\\n    )\\n\\n\\n@chainlit.on_message\\nasync def main(message: chainlit.Message):\\n    \\\"\\\"\\\"\\n    The main Chainlit function.\\n    \\\"\\\"\\\"\\n    # 0) Get and track chat history\\n    history = chainlit.user_session.get(\\\"history\\\")\\n    history.append({\\\"role\\\": \\\"user\\\", \\\"content\\\": message.content})\\n\\n    # 1) Encode input\\n    prompt = build_prompt_from_history(history, add_assistant_header=True)\\n    input_ids = TOKENIZER.encode(prompt)\\n    input_ids_tensor = torch.tensor(input_ids, device=DEVICE).unsqueeze(0)\\n    input_ids_tensor = trim_input_tensor(\\n        input_ids_tensor=input_ids_tensor,\\n        context_len=MODEL.cfg[\\\"context_length\\\"],\\n        max_new_tokens=MAX_NEW_TOKENS\\n    )\\n\\n    # 2) Start an outgoing message we can stream into\\n    out_msg = chainlit.Message(content=\\\"\\\")\\n    await out_msg.send()\\n\\n    # 3) Stream generation\\n    for tok in generate_text_simple_stream(\\n        model=MODEL,\\n        token_ids=input_ids_tensor,\\n        max_new_tokens=MAX_NEW_TOKENS,\\n        # eos_token_id=TOKENIZER.eos_token_id\\n    ):\\n        token_id = tok.squeeze(0)\\n        if token_id in EOS_TOKEN_IDS:\\n            break\\n        piece = TOKENIZER.decode(token_id.tolist())\\n        await out_msg.stream_token(piece)\\n\\n    # 4) Finalize the streamed message\\n    await out_msg.update()\\n\\n    # 5) Update chat history\\n    history.append({\\\"role\\\": \\\"assistant\\\", \\\"content\\\": out_msg.content})\\n    chainlit.user_session.set(\\\"history\\\", history)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/11_qwen3/qwen3-chat-interface/qwen3-chat-interface.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"083081d39a20e8e67fe0bc658268c5841149d959aaf7d9bfcd39c839db6436ce\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport torch\\nimport chainlit\\n\\n# For llms_from_scratch installation instructions, see:\\n# https://github.com/rasbt/LLMs-from-scratch/tree/main/pkg\\nfrom llms_from_scratch.kv_cache.qwen3 import (\\n    Qwen3Model,\\n    Qwen3Tokenizer,\\n    download_from_huggingface_from_snapshots,\\n    load_weights_into_qwen\\n)\\nfrom llms_from_scratch.kv_cache.generate import (\\n    generate_text_simple_stream\\n)\\n\\n# ============================================================\\n# EDIT ME: Simple configuration\\n# ============================================================\\nMODEL = \\\"0.6B\\\"            # options: \\\"0.6B\\\",\\\"1.7B\\\",\\\"4B\\\",\\\"8B\\\",\\\"14B\\\",\\\"32B\\\",\\\"30B-A3B\\\"\\nREASONING = True          # True = \\\"thinking\\\" chat model, False = Base\\nDEVICE = \\\"auto\\\"           # \\\"auto\\\" | \\\"cuda\\\" | \\\"mps\\\" | \\\"cpu\\\"\\nMAX_NEW_TOKENS = 38912\\nLOCAL_DIR = None          # e.g., \\\"Qwen3-0.6B-Base\\\"; None auto-selects\\n# ============================================================\\n\\n\\ndef get_qwen_config(name):\\n    if name == \\\"0.6B\\\":\\n        from llms_from_scratch.qwen3 import QWEN_CONFIG_06_B as QWEN3_CONFIG\\n    elif name == \\\"1.7B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_1_7B as QWEN3_CONFIG\\n    elif name == \\\"4B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_4B as QWEN3_CONFIG\\n    elif name == \\\"8B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_8B as QWEN3_CONFIG\\n    elif name == \\\"14B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_14B as QWEN3_CONFIG\\n    elif name == \\\"32B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_32B as QWEN3_CONFIG\\n    elif name == \\\"30B-A3B\\\":\\n        from llms_from_scratch.qwen3 import QWEN3_CONFIG_30B_A3B as QWEN3_CONFIG\\n    else:\\n        raise ValueError(f\\\"Invalid model name: {name}\\\")\\n    return QWEN3_CONFIG\\n\\n\\ndef build_repo_and_local(model_name, reasoning, local_dir_arg):\\n    base = f\\\"Qwen3-{model_name}\\\"\\n    repo_id = f\\\"Qwen/{base}-Base\\\" if not reasoning else f\\\"Qwen/{base}\\\"\\n    local_dir = local_dir_arg if local_dir_arg else (f\\\"{base}-Base\\\" if not reasoning else base)\\n    return repo_id, local_dir\\n\\n\\ndef get_device(name):\\n    if name == \\\"auto\\\":\\n        if torch.cuda.is_available():\\n            return torch.device(\\\"cuda\\\")\\n        elif torch.backends.mps.is_available():\\n            return torch.device(\\\"mps\\\")\\n        else:\\n            return torch.device(\\\"cpu\\\")\\n    elif name == \\\"cuda\\\":\\n        return torch.device(\\\"cuda\\\")\\n    elif name == \\\"mps\\\":\\n        return torch.device(\\\"mps\\\")\\n    else:\\n        return torch.device(\\\"cpu\\\")\\n\\n\\ndef get_model_and_tokenizer(qwen3_config, repo_id, local_dir, device, use_reasoning):\\n    model = Qwen3Model(qwen3_config)\\n    weights_dict = download_from_huggingface_from_snapshots(\\n        repo_id=repo_id,\\n        local_dir=local_dir\\n    )\\n    load_weights_into_qwen(model, qwen3_config, weights_dict)\\n    del weights_dict\\n\\n    model.to(device)  # safe for all but required by the MoE model\\n    model.eval()\\n\\n    tok_filename = \\\"tokenizer.json\\\"\\n    tokenizer = Qwen3Tokenizer(\\n        tokenizer_file_path=tok_filename,\\n        repo_id=repo_id,\\n        apply_chat_template=use_reasoning,\\n        add_generation_prompt=use_reasoning,\\n        add_thinking=use_reasoning\\n    )\\n    return model, tokenizer\\n\\n\\nQWEN3_CONFIG = get_qwen_config(MODEL)\\nREPO_ID, LOCAL_DIR = build_repo_and_local(MODEL, REASONING, LOCAL_DIR)\\nDEVICE = get_device(DEVICE)\\nMODEL, TOKENIZER = get_model_and_tokenizer(QWEN3_CONFIG, REPO_ID, LOCAL_DIR, DEVICE, REASONING)\\n\\n\\n@chainlit.on_chat_start\\nasync def on_start():\\n    chainlit.user_session.set(\\\"history\\\", [])\\n    chainlit.user_session.get(\\\"history\\\").append(\\n        {\\\"role\\\": \\\"system\\\", \\\"content\\\": \\\"You are a helpful assistant.\\\"}\\n    )\\n\\n\\n@chainlit.on_message\\nasync def main(message: chainlit.Message):\\n    \\\"\\\"\\\"\\n    The main Chainlit function.\\n    \\\"\\\"\\\"\\n    # 1) Encode input\\n    input_ids = TOKENIZER.encode(message.content)\\n    input_ids_tensor = torch.tensor(input_ids, device=DEVICE).unsqueeze(0)\\n\\n    # 2) Start an outgoing message we can stream into\\n    out_msg = chainlit.Message(content=\\\"\\\")\\n    await out_msg.send()\\n\\n    # 3) Stream generation\\n    for tok in generate_text_simple_stream(\\n        model=MODEL,\\n        token_ids=input_ids_tensor,\\n        max_new_tokens=MAX_NEW_TOKENS,\\n        eos_token_id=TOKENIZER.eos_token_id\\n    ):\\n        token_id = tok.squeeze(0)\\n        piece = TOKENIZER.decode(token_id.tolist())\\n        await out_msg.stream_token(piece)\\n\\n    # 4) Finalize the streamed message\\n    await out_msg.update()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/11_qwen3/tests/test_qwen3_kvcache_nb.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0ef572e6894271ef9be9a031f149ee2bb4367e859b232e469cacf3dc5f0e38be\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport importlib\\nfrom pathlib import Path\\n\\nimport pytest\\nimport torch\\n\\nfrom llms_from_scratch.utils import import_definitions_from_notebook\\n\\n\\ntransformers_installed = importlib.util.find_spec(\\\"transformers\\\") is not None\\n\\n\\n@pytest.fixture\\ndef import_notebook_defs():\\n    nb_dir = Path(__file__).resolve().parents[1]\\n    mod = import_definitions_from_notebook(nb_dir, \\\"standalone-qwen3-plus-kvcache.ipynb\\\")\\n    return mod\\n\\n\\n@pytest.fixture\\ndef dummy_input():\\n    torch.manual_seed(123)\\n    return torch.randint(0, 100, (1, 8))  # batch size 1, seq length 8\\n\\n\\n@pytest.fixture\\ndef dummy_cfg_base():\\n    return {\\n        \\\"vocab_size\\\": 100,\\n        \\\"emb_dim\\\": 32,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"n_layers\\\": 2,\\n        \\\"n_heads\\\": 4,\\n        \\\"head_dim\\\": 8,\\n        \\\"n_kv_groups\\\": 1,\\n        \\\"qk_norm\\\": False,\\n        \\\"dtype\\\": torch.float32,\\n        \\\"rope_base\\\": 10000,\\n        \\\"context_length\\\": 64,\\n        \\\"num_experts\\\": 0,\\n    }\\n\\n\\n@pytest.fixture\\ndef dummy_cfg_moe(dummy_cfg_base):\\n    cfg = dummy_cfg_base.copy()\\n    cfg.update({\\n        \\\"num_experts\\\": 4,\\n        \\\"num_experts_per_tok\\\": 2,\\n        \\\"moe_intermediate_size\\\": 64,\\n    })\\n    return cfg\\n\\n\\n@torch.inference_mode()\\ndef test_dummy_qwen3_forward(dummy_cfg_base, dummy_input, import_notebook_defs):\\n    torch.manual_seed(123)\\n    model = import_notebook_defs.Qwen3Model(dummy_cfg_base)\\n    out = model(dummy_input)\\n    assert out.shape == (1, dummy_input.size(1), dummy_cfg_base[\\\"vocab_size\\\"]), \\\\\\n        f\\\"Expected shape (1, seq_len, vocab_size), got {out.shape}\\\"\\n\\n\\n@torch.inference_mode()\\n@pytest.mark.skipif(not transformers_installed, reason=\\\"transformers not installed\\\")\\ndef test_qwen3_base_equivalence_with_transformers(import_notebook_defs):\\n    from transformers import Qwen3Config, Qwen3ForCausalLM\\n\\n    # Tiny config so the test is fast\\n    cfg = {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"head_dim\\\": 8,\\n        \\\"qk_norm\\\": True,\\n        \\\"n_kv_groups\\\": 2,\\n        \\\"rope_base\\\": 1_000_000.0,\\n        \\\"rope_local_base\\\": 10_000.0,\\n        \\\"sliding_window\\\": 4,\\n        \\\"layer_types\\\": [\\\"full_attention\\\", \\\"full_attention\\\"],\\n        \\\"dtype\\\": torch.float32,\\n        \\\"query_pre_attn_scalar\\\": 256,\\n    }\\n    model = import_notebook_defs.Qwen3Model(cfg)\\n\\n    hf_cfg = Qwen3Config(\\n        vocab_size=cfg[\\\"vocab_size\\\"],\\n        max_position_embeddings=cfg[\\\"context_length\\\"],\\n        hidden_size=cfg[\\\"emb_dim\\\"],\\n        num_attention_heads=cfg[\\\"n_heads\\\"],\\n        num_hidden_layers=cfg[\\\"n_layers\\\"],\\n        intermediate_size=cfg[\\\"hidden_dim\\\"],\\n        head_dim=cfg[\\\"head_dim\\\"],\\n        num_key_value_heads=cfg[\\\"n_kv_groups\\\"],\\n        rope_theta=cfg[\\\"rope_base\\\"],\\n        rope_local_base_freq=cfg[\\\"rope_local_base\\\"],\\n        layer_types=cfg[\\\"layer_types\\\"],\\n        sliding_window=cfg[\\\"sliding_window\\\"],\\n        tie_word_embeddings=False,\\n        attn_implementation=\\\"eager\\\",\\n        torch_dtype=torch.float32,\\n        query_pre_attn_scalar=cfg[\\\"query_pre_attn_scalar\\\"],\\n        rope_scaling={\\\"rope_type\\\": \\\"default\\\"},\\n    )\\n    hf_model = Qwen3ForCausalLM(hf_cfg)\\n\\n    hf_state = hf_model.state_dict()\\n    param_config = {\\\"n_layers\\\": cfg[\\\"n_layers\\\"], \\\"hidden_dim\\\": cfg[\\\"hidden_dim\\\"]}\\n    import_notebook_defs.load_weights_into_qwen(model, param_config, hf_state)\\n\\n    x = torch.randint(0, cfg[\\\"vocab_size\\\"], (2, cfg[\\\"context_length\\\"]), dtype=torch.long)\\n    ours_logits = model(x)\\n    theirs_logits = hf_model(x).logits\\n    torch.testing.assert_close(ours_logits, theirs_logits, rtol=1e-5, atol=1e-5)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/11_qwen3/tests/test_qwen3_nb.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ee0cb36fab6c71072636e0afb5752fc72da729d5c42aa771710e0065fb9a8b41\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport importlib\\nfrom pathlib import Path\\n\\nimport pytest\\nimport torch\\n\\nfrom llms_from_scratch.utils import import_definitions_from_notebook\\n\\n\\ntransformers_installed = importlib.util.find_spec(\\\"transformers\\\") is not None\\n\\n\\n@pytest.fixture\\ndef import_notebook_defs():\\n    nb_dir = Path(__file__).resolve().parents[1]\\n    mod = import_definitions_from_notebook(nb_dir, \\\"standalone-qwen3.ipynb\\\")\\n    return mod\\n\\n\\n@pytest.fixture\\ndef dummy_input():\\n    torch.manual_seed(123)\\n    return torch.randint(0, 100, (1, 8))  # batch size 1, seq length 8\\n\\n\\n@pytest.fixture\\ndef dummy_cfg_base():\\n    return {\\n        \\\"vocab_size\\\": 100,\\n        \\\"emb_dim\\\": 32,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"n_layers\\\": 2,\\n        \\\"n_heads\\\": 4,\\n        \\\"head_dim\\\": 8,\\n        \\\"n_kv_groups\\\": 1,\\n        \\\"qk_norm\\\": False,\\n        \\\"dtype\\\": torch.float32,\\n        \\\"rope_base\\\": 10000,\\n        \\\"context_length\\\": 64,\\n        \\\"num_experts\\\": 0,\\n    }\\n\\n\\n@pytest.fixture\\ndef dummy_cfg_moe(dummy_cfg_base):\\n    cfg = dummy_cfg_base.copy()\\n    cfg.update({\\n        \\\"num_experts\\\": 4,\\n        \\\"num_experts_per_tok\\\": 2,\\n        \\\"moe_intermediate_size\\\": 64,\\n    })\\n    return cfg\\n\\n\\n@torch.inference_mode()\\ndef test_dummy_qwen3_forward(dummy_cfg_base, dummy_input, import_notebook_defs):\\n    torch.manual_seed(123)\\n    model = import_notebook_defs.Qwen3Model(dummy_cfg_base)\\n    out = model(dummy_input)\\n    assert out.shape == (1, dummy_input.size(1), dummy_cfg_base[\\\"vocab_size\\\"]), \\\\\\n        f\\\"Expected shape (1, seq_len, vocab_size), got {out.shape}\\\"\\n\\n\\n@torch.inference_mode()\\n@pytest.mark.skipif(not transformers_installed, reason=\\\"transformers not installed\\\")\\ndef test_qwen3_base_equivalence_with_transformers(import_notebook_defs):\\n    from transformers import Qwen3Config, Qwen3ForCausalLM\\n\\n    # Tiny config so the test is fast\\n    cfg = {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"head_dim\\\": 8,\\n        \\\"qk_norm\\\": True,\\n        \\\"n_kv_groups\\\": 2,\\n        \\\"rope_base\\\": 1_000_000.0,\\n        \\\"rope_local_base\\\": 10_000.0,\\n        \\\"sliding_window\\\": 4,\\n        \\\"layer_types\\\": [\\\"full_attention\\\", \\\"full_attention\\\"],\\n        \\\"dtype\\\": torch.float32,\\n        \\\"query_pre_attn_scalar\\\": 256,\\n    }\\n    model = import_notebook_defs.Qwen3Model(cfg)\\n\\n    hf_cfg = Qwen3Config(\\n        vocab_size=cfg[\\\"vocab_size\\\"],\\n        max_position_embeddings=cfg[\\\"context_length\\\"],\\n        hidden_size=cfg[\\\"emb_dim\\\"],\\n        num_attention_heads=cfg[\\\"n_heads\\\"],\\n        num_hidden_layers=cfg[\\\"n_layers\\\"],\\n        intermediate_size=cfg[\\\"hidden_dim\\\"],\\n        head_dim=cfg[\\\"head_dim\\\"],\\n        num_key_value_heads=cfg[\\\"n_kv_groups\\\"],\\n        rope_theta=cfg[\\\"rope_base\\\"],\\n        rope_local_base_freq=cfg[\\\"rope_local_base\\\"],\\n        layer_types=cfg[\\\"layer_types\\\"],\\n        sliding_window=cfg[\\\"sliding_window\\\"],\\n        tie_word_embeddings=False,\\n        attn_implementation=\\\"eager\\\",\\n        torch_dtype=torch.float32,\\n        query_pre_attn_scalar=cfg[\\\"query_pre_attn_scalar\\\"],\\n        rope_scaling={\\\"rope_type\\\": \\\"default\\\"},\\n    )\\n    hf_model = Qwen3ForCausalLM(hf_cfg)\\n\\n    hf_state = hf_model.state_dict()\\n    param_config = {\\\"n_layers\\\": cfg[\\\"n_layers\\\"], \\\"hidden_dim\\\": cfg[\\\"hidden_dim\\\"]}\\n    import_notebook_defs.load_weights_into_qwen(model, param_config, hf_state)\\n\\n    x = torch.randint(0, cfg[\\\"vocab_size\\\"], (2, cfg[\\\"context_length\\\"]), dtype=torch.long)\\n    ours_logits = model(x)\\n    theirs_logits = hf_model(x).logits\\n    torch.testing.assert_close(ours_logits, theirs_logits, rtol=1e-5, atol=1e-5)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/12_gemma3/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4067ae1ba28644e9a9ced45eca3c265a67013d37797df2f3888c39a51cdbdf57\",\"content\":\"# Gemma 3 270M From Scratch\\n\\nThis [standalone-gemma3.ipynb](standalone-gemma3.ipynb) Jupyter notebook in this folder contains a from-scratch implementation of Gemma 3 270M. It requires about 2 GB of RAM to run. \\n\\nThe alternative [standalone-gemma3-plus-kvcache.ipynb](standalone-gemma3-plus-kvcache.ipynb) notebook adds a KV cache for better runtime performance (but adds more code complexity). To learn more about KV caching, see my [Understanding and Coding the KV Cache in LLMs from Scratch](https://magazine.sebastianraschka.com/p/coding-the-kv-cache-in-llms) article.\\n\\n| Model             | Mode              | Hardware        | Tokens/sec | GPU Memory (VRAM) |\\n| ----------------- | ----------------- | --------------- | ---------- | ----------------- |\\n| Gemma3Model 270M  | Regular           | Mac Mini M4 CPU | 8          | -                 |\\n| Gemma3Model 270M  | Regular compiled  | Mac Mini M4 CPU | 9          | -                 |\\n| Gemma3Model 270M  | KV cache          | Mac Mini M4 CPU | 130        | -                 |\\n| Gemma3Model 270M  | KV cache compiled | Mac Mini M4 CPU | 224        | -                 |\\n|                   |                   |                 |            |                   |\\n| Gemma3Model 270M  | Regular           | Mac Mini M4 GPU | 16         | -                 |\\n| Gemma3Model 270M  | Regular compiled  | Mac Mini M4 GPU | Error      | -                 |\\n| Gemma3Model 270M  | KV cache          | Mac Mini M4 GPU | 23         | -                 |\\n| Gemma3Model 270M  | KV cache compiled | Mac Mini M4 GPU | Error      | -                 |\\n|                   |                   |                 |            |                   |\\n| Gemma3Model 270M  | Regular           | Nvidia A100 GPU | 28         | 1.84 GB           |\\n| Gemma3Model 270M  | Regular compiled  | Nvidia A100 GPU | 128        | 2.12 GB           |\\n| Gemma3Model 270M  | KV cache          | Nvidia A100 GPU | 26         | 1.77 GB           |\\n| Gemma3Model 270M  | KV cache compiled | Nvidia A100 GPU | 99         | 2.12 GB           |\\n\\n\\nBelow is a side-by-side comparison with Qwen3 0.6B as a reference model; if you are interested in the Qwen3 0.6B standalone notebook, you can find it [here](../11_qwen3).\\n\\n<br>\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/gemma3/gemma3-vs-qwen3.webp\\\">\\n\\n<br>\\n\\nTo learn more about the architecture differences and read about comparisons with other architectures, see my [The Big LLM Architecture Comparison: From DeepSeek-V3 to Kimi K2: A Look At Modern LLM Architecture Design](https://magazine.sebastianraschka.com/p/the-big-llm-architecture-comparison) article.\\n\\n\\n\\n\\n\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/12_gemma3/tests/gemma3_layer_debugger.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"33805dcb88fcfd4962d22424f891c2da2d5228e3552009765d19df3666a07163\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport importlib\\nfrom pathlib import Path\\n\\nimport torch\\n\\nfrom llms_from_scratch.utils import import_definitions_from_notebook\\n\\ntry:\\n    from transformers import Gemma3ForCausalLM, Gemma3TextConfig\\nexcept ImportError:\\n    Gemma3ForCausalLM = None\\n    Gemma3TextConfig = None\\n\\n\\ndef tiny_debug_config():\\n    return {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"head_dim\\\": 8,\\n        \\\"qk_norm\\\": True,\\n        \\\"n_kv_groups\\\": 2,\\n        \\\"rope_base\\\": 1_000_000.0,\\n        \\\"rope_local_base\\\": 10_000.0,\\n        \\\"sliding_window\\\": 4,\\n        \\\"layer_types\\\": [\\\"full_attention\\\", \\\"full_attention\\\"],\\n        \\\"dtype\\\": torch.float32,\\n        \\\"query_pre_attn_scalar\\\": 256,\\n    }\\n\\n\\ndef _hf_config_from_dict(cfg):\\n    if Gemma3TextConfig is None:\\n        raise ImportError(\\\"transformers is required for the Gemma 3 debugger.\\\")\\n\\n    return Gemma3TextConfig(\\n        vocab_size=cfg[\\\"vocab_size\\\"],\\n        max_position_embeddings=cfg[\\\"context_length\\\"],\\n        hidden_size=cfg[\\\"emb_dim\\\"],\\n        num_attention_heads=cfg[\\\"n_heads\\\"],\\n        num_hidden_layers=cfg[\\\"n_layers\\\"],\\n        intermediate_size=cfg[\\\"hidden_dim\\\"],\\n        head_dim=cfg[\\\"head_dim\\\"],\\n        num_key_value_heads=cfg[\\\"n_kv_groups\\\"],\\n        rope_theta=cfg[\\\"rope_base\\\"],\\n        rope_local_base_freq=cfg[\\\"rope_local_base\\\"],\\n        layer_types=cfg[\\\"layer_types\\\"],\\n        sliding_window=cfg[\\\"sliding_window\\\"],\\n        tie_word_embeddings=False,\\n        attn_implementation=\\\"eager\\\",\\n        torch_dtype=cfg.get(\\\"dtype\\\", torch.float32),\\n        query_pre_attn_scalar=cfg[\\\"query_pre_attn_scalar\\\"],\\n        rope_scaling={\\\"rope_type\\\": \\\"default\\\"},\\n        ignore_keys_at_rope_validation={\\\"full_attention\\\", \\\"sliding_attention\\\"},\\n    )\\n\\n\\ndef load_notebook_defs(nb_name=\\\"standalone-gemma3.ipynb\\\"):\\n    nb_dir = Path(__file__).resolve().parents[1]\\n    return import_definitions_from_notebook(nb_dir, nb_name)\\n\\n\\ndef build_gemma3_pair(import_notebook_defs, cfg, hf_checkpoint=None):\\n    if Gemma3ForCausalLM is None:\\n        raise ImportError(\\\"transformers is required for the Gemma 3 debugger.\\\")\\n\\n    ours = import_notebook_defs.Gemma3Model(cfg)\\n\\n    if hf_checkpoint:\\n        hf_model = Gemma3ForCausalLM.from_pretrained(\\n            hf_checkpoint,\\n            torch_dtype=cfg.get(\\\"dtype\\\", torch.float32),\\n            attn_implementation=\\\"eager\\\",\\n        )\\n    else:\\n        hf_cfg = _hf_config_from_dict(cfg)\\n        hf_model = Gemma3ForCausalLM(hf_cfg)\\n\\n    param_config = {\\\"n_layers\\\": cfg[\\\"n_layers\\\"], \\\"hidden_dim\\\": cfg[\\\"hidden_dim\\\"]}\\n    import_notebook_defs.load_weights_into_gemma(ours, param_config, hf_model.state_dict())\\n\\n    ours.eval()\\n    hf_model.eval()\\n    return ours, hf_model\\n\\n\\ndef _attach_debug_hooks(model, is_hf):\\n    traces = {}\\n    handles = []\\n\\n    def hook(name, scale=None):\\n        def _record(_, __, output):\\n            if isinstance(output, tuple):\\n                output = output[0]\\n            if scale is not None:\\n                output = output * scale\\n            traces[name] = output.detach().to(torch.float32).cpu()\\n\\n        return _record\\n\\n    if is_hf:\\n        core = model.model\\n        handles.append(core.embed_tokens.register_forward_hook(hook(\\\"embedding\\\")))\\n        for idx, layer in enumerate(core.layers):\\n            handles.append(layer.register_forward_hook(hook(f\\\"block_{idx}\\\")))\\n        handles.append(core.norm.register_forward_hook(hook(\\\"final_norm\\\")))\\n        handles.append(model.lm_head.register_forward_hook(hook(\\\"logits\\\")))\\n    else:\\n        emb_scale = float(getattr(model, \\\"cfg\\\", {}).get(\\\"emb_dim\\\", model.tok_emb.embedding_dim) ** 0.5)\\n        handles.append(model.tok_emb.register_forward_hook(hook(\\\"embedding\\\", scale=emb_scale)))\\n        blocks = getattr(model, \\\"blocks\\\", None)\\n        if blocks is None:\\n            blocks = getattr(model, \\\"trf_blocks\\\", None)\\n        if blocks is None:\\n            raise AttributeError(\\\"Could not locate Gemma 3 blocks on the local model.\\\")\\n        for idx, block in enumerate(blocks):\\n            handles.append(block.register_forward_hook(hook(f\\\"block_{idx}\\\")))\\n        handles.append(model.final_norm.register_forward_hook(hook(\\\"final_norm\\\")))\\n        handles.append(model.out_head.register_forward_hook(hook(\\\"logits\\\")))\\n\\n    return traces, handles\\n\\n\\ndef _layer_sort_key(name):\\n    if name == \\\"embedding\\\":\\n        return (0, 0)\\n    if name.startswith(\\\"block_\\\"):\\n        idx = int(name.split(\\\"_\\\")[1])\\n        return (1, idx)\\n    if name == \\\"final_norm\\\":\\n        return (2, 0)\\n    if name == \\\"logits\\\":\\n        return (3, 0)\\n    return (4, name)\\n\\n\\ndef layerwise_differences(ours, hf_model, input_ids, rtol=1e-5, atol=1e-5):\\n    ours_traces, ours_handles = _attach_debug_hooks(ours, is_hf=False)\\n    hf_traces, hf_handles = _attach_debug_hooks(hf_model, is_hf=True)\\n\\n    try:\\n        with torch.inference_mode():\\n            ours(input_ids)\\n            hf_model(input_ids)\\n    finally:\\n        for h in ours_handles + hf_handles:\\n            h.remove()\\n\\n    layer_names = sorted(set(ours_traces) | set(hf_traces), key=_layer_sort_key)\\n    results = []\\n    for name in layer_names:\\n        ours_tensor = ours_traces.get(name)\\n        hf_tensor = hf_traces.get(name)\\n\\n        if ours_tensor is None or hf_tensor is None:\\n            results.append(\\n                {\\n                    \\\"name\\\": name,\\n                    \\\"status\\\": \\\"missing\\\",\\n                    \\\"ours_shape\\\": None if ours_tensor is None else tuple(ours_tensor.shape),\\n                    \\\"hf_shape\\\": None if hf_tensor is None else tuple(hf_tensor.shape),\\n                    \\\"max_diff\\\": None,\\n                    \\\"mean_abs_diff\\\": None,\\n                }\\n            )\\n            continue\\n\\n        if ours_tensor.shape != hf_tensor.shape:\\n            results.append(\\n                {\\n                    \\\"name\\\": name,\\n                    \\\"status\\\": \\\"shape_mismatch\\\",\\n                    \\\"ours_shape\\\": tuple(ours_tensor.shape),\\n                    \\\"hf_shape\\\": tuple(hf_tensor.shape),\\n                    \\\"max_diff\\\": None,\\n                    \\\"mean_abs_diff\\\": None,\\n                }\\n            )\\n            continue\\n\\n        diff = (ours_tensor - hf_tensor).abs()\\n        max_diff = float(diff.max().item())\\n        mean_diff = float(diff.mean().item())\\n        allclose = torch.allclose(ours_tensor, hf_tensor, rtol=rtol, atol=atol)\\n        results.append(\\n            {\\n                \\\"name\\\": name,\\n                \\\"status\\\": \\\"ok\\\" if allclose else \\\"mismatch\\\",\\n                \\\"ours_shape\\\": tuple(ours_tensor.shape),\\n                \\\"hf_shape\\\": tuple(hf_tensor.shape),\\n                \\\"max_diff\\\": max_diff,\\n                \\\"mean_abs_diff\\\": mean_diff,\\n            }\\n        )\\n    return results\\n\\n\\ndef format_report(differences):\\n    lines = []\\n    for diff in sorted(differences, key=lambda d: _layer_sort_key(d[\\\"name\\\"])):\\n        if diff[\\\"status\\\"] == \\\"ok\\\":\\n            lines.append(f\\\"[OK] {diff['name']}: max={diff['max_diff']:.2e}, mean={diff['mean_abs_diff']:.2e}\\\")\\n        elif diff[\\\"status\\\"] == \\\"mismatch\\\":\\n            lines.append(f\\\"[DIFF] {diff['name']}: max={diff['max_diff']:.2e}, mean={diff['mean_abs_diff']:.2e}\\\")\\n        elif diff[\\\"status\\\"] == \\\"shape_mismatch\\\":\\n            lines.append(f\\\"[SHAPE] {diff['name']}: ours={diff['ours_shape']}, hf={diff['hf_shape']}\\\")\\n        else:\\n            lines.append(f\\\"[MISSING] {diff['name']}: ours={diff['ours_shape']}, hf={diff['hf_shape']}\\\")\\n    return \\\"\\\\n\\\".join(lines)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    transformers_available = importlib.util.find_spec(\\\"transformers\\\") is not None\\n    if not transformers_available:\\n        raise SystemExit(\\\"transformers is not installed; install it to run the debugger.\\\")\\n\\n    import_notebook_defs = load_notebook_defs()\\n    cfg = tiny_debug_config()\\n\\n    ours_model, hf_model = build_gemma3_pair(import_notebook_defs, cfg)\\n    torch.manual_seed(0)\\n    input_ids = torch.randint(0, cfg[\\\"vocab_size\\\"], (1, cfg[\\\"context_length\\\"]), dtype=torch.long)\\n    diffs = layerwise_differences(ours_model, hf_model, input_ids)\\n    print(format_report(diffs))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/12_gemma3/tests/gemma3_layer_debugger_detailed.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aec1ad3c832ab61468ee3e822902dce250562a6e877b38599fe300e0e77d4dac\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport importlib\\nfrom pathlib import Path\\n\\nimport torch\\n\\nfrom llms_from_scratch.utils import import_definitions_from_notebook\\n\\ntry:\\n    from transformers import Gemma3ForCausalLM, Gemma3TextConfig\\nexcept ImportError:\\n    Gemma3ForCausalLM = None\\n    Gemma3TextConfig = None\\n\\n\\ndef tiny_debug_config():\\n    return {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"head_dim\\\": 8,\\n        \\\"qk_norm\\\": True,\\n        \\\"n_kv_groups\\\": 2,\\n        \\\"rope_base\\\": 1_000_000.0,\\n        \\\"rope_local_base\\\": 10_000.0,\\n        \\\"sliding_window\\\": 4,\\n        \\\"layer_types\\\": [\\\"full_attention\\\", \\\"full_attention\\\"],\\n        \\\"dtype\\\": torch.float32,\\n        \\\"query_pre_attn_scalar\\\": 256,\\n    }\\n\\n\\ndef _hf_config_from_dict(cfg):\\n    if Gemma3TextConfig is None:\\n        raise ImportError(\\\"transformers is required for the Gemma 3 debugger.\\\")\\n\\n    return Gemma3TextConfig(\\n        vocab_size=cfg[\\\"vocab_size\\\"],\\n        max_position_embeddings=cfg[\\\"context_length\\\"],\\n        hidden_size=cfg[\\\"emb_dim\\\"],\\n        num_attention_heads=cfg[\\\"n_heads\\\"],\\n        num_hidden_layers=cfg[\\\"n_layers\\\"],\\n        intermediate_size=cfg[\\\"hidden_dim\\\"],\\n        head_dim=cfg[\\\"head_dim\\\"],\\n        num_key_value_heads=cfg[\\\"n_kv_groups\\\"],\\n        rope_theta=cfg[\\\"rope_base\\\"],\\n        rope_local_base_freq=cfg[\\\"rope_local_base\\\"],\\n        layer_types=cfg[\\\"layer_types\\\"],\\n        sliding_window=cfg[\\\"sliding_window\\\"],\\n        tie_word_embeddings=False,\\n        attn_implementation=\\\"eager\\\",\\n        torch_dtype=cfg.get(\\\"dtype\\\", torch.float32),\\n        query_pre_attn_scalar=cfg[\\\"query_pre_attn_scalar\\\"],\\n        rope_scaling={\\\"rope_type\\\": \\\"default\\\"},\\n        ignore_keys_at_rope_validation={\\\"full_attention\\\", \\\"sliding_attention\\\"},\\n    )\\n\\n\\ndef load_notebook_defs(nb_name=\\\"standalone-gemma3.ipynb\\\"):\\n    nb_dir = Path(__file__).resolve().parents[1]\\n    return import_definitions_from_notebook(nb_dir, nb_name)\\n\\n\\ndef build_gemma3_pair(import_notebook_defs, cfg, hf_checkpoint=None):\\n    if Gemma3ForCausalLM is None:\\n        raise ImportError(\\\"transformers is required for the Gemma 3 debugger.\\\")\\n\\n    torch.manual_seed(123)\\n    ours = import_notebook_defs.Gemma3Model(cfg)\\n\\n    if hf_checkpoint:\\n        hf_model = Gemma3ForCausalLM.from_pretrained(\\n            hf_checkpoint,\\n            torch_dtype=cfg.get(\\\"dtype\\\", torch.float32),\\n            attn_implementation=\\\"eager\\\",\\n        )\\n    else:\\n        hf_cfg = _hf_config_from_dict(cfg)\\n        hf_model = Gemma3ForCausalLM(hf_cfg)\\n\\n    param_config = {\\\"n_layers\\\": cfg[\\\"n_layers\\\"], \\\"hidden_dim\\\": cfg[\\\"hidden_dim\\\"]}\\n    import_notebook_defs.load_weights_into_gemma(ours, param_config, hf_model.state_dict())\\n\\n    ours.eval()\\n    hf_model.eval()\\n    return ours, hf_model\\n\\n\\ndef _register_trace_hook(handles, traces, name, module, scale=None):\\n    if module is None:\\n        return\\n\\n    def _record(_, __, output):\\n        if isinstance(output, tuple):\\n            output = output[0]\\n        if scale is not None:\\n            output = output * scale\\n        traces[name] = output.detach().to(torch.float32).cpu()\\n\\n    handles.append(module.register_forward_hook(_record))\\n\\n\\ndef _attach_debug_hooks(model, is_hf, include_block_details=True):\\n    traces = {}\\n    handles = []\\n\\n    if is_hf:\\n        core = model.model\\n        _register_trace_hook(handles, traces, \\\"embedding\\\", core.embed_tokens)\\n        for idx, layer in enumerate(core.layers):\\n            block_name = f\\\"block_{idx}\\\"\\n            _register_trace_hook(handles, traces, block_name, layer)\\n\\n            if include_block_details:\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.input_layernorm\\\", layer.input_layernorm)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.q_proj\\\", layer.self_attn.q_proj)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.k_proj\\\", layer.self_attn.k_proj)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.v_proj\\\", layer.self_attn.v_proj)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.q_norm\\\", layer.self_attn.q_norm)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.k_norm\\\", layer.self_attn.k_norm)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.o_proj\\\", layer.self_attn.o_proj)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att\\\", layer.self_attn)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.post_attention_layernorm\\\", layer.post_attention_layernorm)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.pre_feedforward_layernorm\\\", layer.pre_feedforward_layernorm)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.ff.gate_proj\\\", layer.mlp.gate_proj)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.ff.up_proj\\\", layer.mlp.up_proj)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.ff.down_proj\\\", layer.mlp.down_proj)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.ff\\\", layer.mlp)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.post_feedforward_layernorm\\\", layer.post_feedforward_layernorm)\\n\\n        _register_trace_hook(handles, traces, \\\"final_norm\\\", core.norm)\\n        _register_trace_hook(handles, traces, \\\"logits\\\", model.lm_head)\\n    else:\\n        emb_scale = float(getattr(model, \\\"cfg\\\", {}).get(\\\"emb_dim\\\", model.tok_emb.embedding_dim) ** 0.5)\\n        _register_trace_hook(handles, traces, \\\"embedding\\\", model.tok_emb, scale=emb_scale)\\n        blocks = getattr(model, \\\"blocks\\\", None)\\n        if blocks is None:\\n            blocks = getattr(model, \\\"trf_blocks\\\", None)\\n        if blocks is None:\\n            raise AttributeError(\\\"Could not locate Gemma 3 blocks on the local model.\\\")\\n        for idx, block in enumerate(blocks):\\n            block_name = f\\\"block_{idx}\\\"\\n            _register_trace_hook(handles, traces, block_name, block)\\n\\n            if include_block_details:\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.input_layernorm\\\", block.input_layernorm)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.q_proj\\\", block.att.W_query)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.k_proj\\\", block.att.W_key)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.v_proj\\\", block.att.W_value)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.q_norm\\\", block.att.q_norm)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.k_norm\\\", block.att.k_norm)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att.o_proj\\\", block.att.out_proj)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.att\\\", block.att)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.post_attention_layernorm\\\", block.post_attention_layernorm)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.pre_feedforward_layernorm\\\", block.pre_feedforward_layernorm)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.ff.gate_proj\\\", block.ff.fc1)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.ff.up_proj\\\", block.ff.fc2)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.ff.down_proj\\\", block.ff.fc3)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.ff\\\", block.ff)\\n                _register_trace_hook(handles, traces, f\\\"{block_name}.post_feedforward_layernorm\\\", block.post_feedforward_layernorm)\\n\\n        _register_trace_hook(handles, traces, \\\"final_norm\\\", model.final_norm)\\n        _register_trace_hook(handles, traces, \\\"logits\\\", model.out_head)\\n\\n    return traces, handles\\n\\n\\ndef _layer_sort_key(name):\\n    block_detail_order = {\\n        \\\"input_layernorm\\\": 0,\\n        \\\"att.q_proj\\\": 1,\\n        \\\"att.k_proj\\\": 2,\\n        \\\"att.v_proj\\\": 3,\\n        \\\"att.q_norm\\\": 4,\\n        \\\"att.k_norm\\\": 5,\\n        \\\"att.o_proj\\\": 6,\\n        \\\"att\\\": 7,\\n        \\\"post_attention_layernorm\\\": 8,\\n        \\\"pre_feedforward_layernorm\\\": 9,\\n        \\\"ff.gate_proj\\\": 10,\\n        \\\"ff.up_proj\\\": 11,\\n        \\\"ff.down_proj\\\": 12,\\n        \\\"ff\\\": 13,\\n        \\\"post_feedforward_layernorm\\\": 14,\\n    }\\n\\n    if name == \\\"embedding\\\":\\n        return (0, 0)\\n    if name.startswith(\\\"block_\\\"):\\n        block_name, _, detail = name.partition(\\\".\\\")\\n        idx = int(block_name.split(\\\"_\\\")[1])\\n        if not detail:\\n            return (1, idx, -1)\\n        return (2, idx, block_detail_order.get(detail, 100), detail)\\n    if name == \\\"final_norm\\\":\\n        return (3, 0)\\n    if name == \\\"logits\\\":\\n        return (4, 0)\\n    return (5, name)\\n\\n\\ndef layerwise_differences(ours, hf_model, input_ids, rtol=1e-5, atol=1e-5, include_block_details=True):\\n    ours_traces, ours_handles = _attach_debug_hooks(ours, is_hf=False, include_block_details=include_block_details)\\n    hf_traces, hf_handles = _attach_debug_hooks(hf_model, is_hf=True, include_block_details=include_block_details)\\n\\n    try:\\n        with torch.inference_mode():\\n            ours(input_ids)\\n            hf_model(input_ids)\\n    finally:\\n        for h in ours_handles + hf_handles:\\n            h.remove()\\n\\n    layer_names = sorted(set(ours_traces) | set(hf_traces), key=_layer_sort_key)\\n    results = []\\n    for name in layer_names:\\n        ours_tensor = ours_traces.get(name)\\n        hf_tensor = hf_traces.get(name)\\n\\n        if ours_tensor is None or hf_tensor is None:\\n            results.append(\\n                {\\n                    \\\"name\\\": name,\\n                    \\\"status\\\": \\\"missing\\\",\\n                    \\\"ours_shape\\\": None if ours_tensor is None else tuple(ours_tensor.shape),\\n                    \\\"hf_shape\\\": None if hf_tensor is None else tuple(hf_tensor.shape),\\n                    \\\"max_diff\\\": None,\\n                    \\\"mean_abs_diff\\\": None,\\n                }\\n            )\\n            continue\\n\\n        if ours_tensor.shape != hf_tensor.shape:\\n            results.append(\\n                {\\n                    \\\"name\\\": name,\\n                    \\\"status\\\": \\\"shape_mismatch\\\",\\n                    \\\"ours_shape\\\": tuple(ours_tensor.shape),\\n                    \\\"hf_shape\\\": tuple(hf_tensor.shape),\\n                    \\\"max_diff\\\": None,\\n                    \\\"mean_abs_diff\\\": None,\\n                }\\n            )\\n            continue\\n\\n        diff = (ours_tensor - hf_tensor).abs()\\n        max_diff = float(diff.max().item())\\n        mean_diff = float(diff.mean().item())\\n        allclose = torch.allclose(ours_tensor, hf_tensor, rtol=rtol, atol=atol)\\n        results.append(\\n            {\\n                \\\"name\\\": name,\\n                \\\"status\\\": \\\"ok\\\" if allclose else \\\"mismatch\\\",\\n                \\\"ours_shape\\\": tuple(ours_tensor.shape),\\n                \\\"hf_shape\\\": tuple(hf_tensor.shape),\\n                \\\"max_diff\\\": max_diff,\\n                \\\"mean_abs_diff\\\": mean_diff,\\n            }\\n        )\\n    return results\\n\\n\\ndef _format_diff_line(diff, indent=\\\"\\\"):\\n    if diff[\\\"status\\\"] == \\\"ok\\\":\\n        return f\\\"{indent}[OK] {diff['name']}: max={diff['max_diff']:.2e}, mean={diff['mean_abs_diff']:.2e}\\\"\\n    if diff[\\\"status\\\"] == \\\"mismatch\\\":\\n        return f\\\"{indent}[DIFF] {diff['name']}: max={diff['max_diff']:.2e}, mean={diff['mean_abs_diff']:.2e}\\\"\\n    if diff[\\\"status\\\"] == \\\"shape_mismatch\\\":\\n        return f\\\"{indent}[SHAPE] {diff['name']}: ours={diff['ours_shape']}, hf={diff['hf_shape']}\\\"\\n    return f\\\"{indent}[MISSING] {diff['name']}: ours={diff['ours_shape']}, hf={diff['hf_shape']}\\\"\\n\\n\\ndef format_report(differences, show_block_details=True, details_for_all_blocks=False):\\n    lines = []\\n    top_level_diffs = [diff for diff in differences if \\\".\\\" not in diff[\\\"name\\\"]]\\n\\n    for diff in sorted(top_level_diffs, key=lambda d: _layer_sort_key(d[\\\"name\\\"])):\\n        lines.append(_format_diff_line(diff))\\n\\n        if not show_block_details or not diff[\\\"name\\\"].startswith(\\\"block_\\\"):\\n            continue\\n\\n        detail_prefix = f\\\"{diff['name']}.\\\"\\n        detail_diffs = [\\n            other for other in differences\\n            if other[\\\"name\\\"].startswith(detail_prefix)\\n        ]\\n        if not detail_diffs:\\n            continue\\n\\n        has_detail_mismatch = any(other[\\\"status\\\"] != \\\"ok\\\" for other in detail_diffs)\\n        if not details_for_all_blocks and diff[\\\"status\\\"] == \\\"ok\\\" and not has_detail_mismatch:\\n            continue\\n        if not details_for_all_blocks and diff[\\\"status\\\"] == \\\"ok\\\":\\n            continue\\n\\n        for other in sorted(detail_diffs, key=lambda d: _layer_sort_key(d[\\\"name\\\"])):\\n            lines.append(_format_diff_line(other, indent=\\\"  \\\"))\\n\\n    return \\\"\\\\n\\\".join(lines)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    transformers_available = importlib.util.find_spec(\\\"transformers\\\") is not None\\n    if not transformers_available:\\n        raise SystemExit(\\\"transformers is not installed; install it to run the debugger.\\\")\\n\\n    import_notebook_defs = load_notebook_defs()\\n    cfg = tiny_debug_config()\\n\\n    ours_model, hf_model = build_gemma3_pair(import_notebook_defs, cfg)\\n    torch.manual_seed(0)\\n    input_ids = torch.randint(0, cfg[\\\"vocab_size\\\"], (1, cfg[\\\"context_length\\\"]), dtype=torch.long)\\n    diffs = layerwise_differences(ours_model, hf_model, input_ids)\\n    print(format_report(diffs))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/12_gemma3/tests/test_gemma3_kv_nb.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8da877befb68d2f774a7d61bacca34a470c2ca99ce02a9dc360bbc0e49181435\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport importlib\\nfrom pathlib import Path\\n\\nimport pytest\\nimport torch\\n\\nfrom llms_from_scratch.utils import import_definitions_from_notebook\\n\\n\\ntransformers_installed = importlib.util.find_spec(\\\"transformers\\\") is not None\\n\\n\\n@pytest.fixture\\ndef import_notebook_defs():\\n    nb_dir = Path(__file__).resolve().parents[1]\\n    mod = import_definitions_from_notebook(nb_dir, \\\"standalone-gemma3-plus-kvcache.ipynb\\\")\\n    return mod\\n\\n\\n@pytest.fixture\\ndef dummy_input():\\n    torch.manual_seed(123)\\n    return torch.randint(0, 100, (1, 8))  # batch size 1, seq length 8\\n\\n\\n@pytest.fixture\\ndef dummy_cfg_base():\\n    return {\\n        \\\"vocab_size\\\": 100,\\n        \\\"emb_dim\\\": 32,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"n_layers\\\": 2,\\n        \\\"n_heads\\\": 4,\\n        \\\"head_dim\\\": 8,\\n        \\\"n_kv_groups\\\": 1,\\n        \\\"qk_norm\\\": True,                # Gemma3 uses q/k RMSNorm\\n        \\\"dtype\\\": torch.float32,\\n        \\\"rope_base\\\": 1_000_000.0,       # global RoPE base\\n        \\\"rope_local_base\\\": 10_000.0,    # local RoPE base (unused in these tests)\\n        \\\"context_length\\\": 64,\\n        \\\"sliding_window\\\": 16,\\n        \\\"layer_types\\\": [\\\"full_attention\\\", \\\"full_attention\\\"],\\n        \\\"query_pre_attn_scalar\\\": 256,\\n    }\\n\\n\\n@torch.inference_mode()\\ndef test_dummy_gemma3_forward(dummy_cfg_base, dummy_input, import_notebook_defs):\\n    torch.manual_seed(123)\\n    model = import_notebook_defs.Gemma3Model(dummy_cfg_base)\\n    out = model(dummy_input)\\n    assert out.shape == (1, dummy_input.size(1), dummy_cfg_base[\\\"vocab_size\\\"])\\n\\n\\n@torch.inference_mode()\\n@pytest.mark.skipif(not transformers_installed, reason=\\\"transformers not installed\\\")\\ndef test_gemma3_base_equivalence_with_transformers(import_notebook_defs):\\n    from transformers import Gemma3TextConfig, Gemma3ForCausalLM\\n\\n    # Tiny config so the test is fast\\n    cfg = {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"head_dim\\\": 8,\\n        \\\"qk_norm\\\": True,\\n        \\\"n_kv_groups\\\": 2,\\n        \\\"rope_base\\\": 1_000_000.0,\\n        \\\"rope_local_base\\\": 10_000.0,\\n        \\\"sliding_window\\\": 4,\\n        \\\"layer_types\\\": [\\\"full_attention\\\", \\\"full_attention\\\"],\\n        \\\"dtype\\\": torch.float32,\\n        \\\"query_pre_attn_scalar\\\": 256,\\n    }\\n    model = import_notebook_defs.Gemma3Model(cfg)\\n\\n    hf_cfg = Gemma3TextConfig(\\n        vocab_size=cfg[\\\"vocab_size\\\"],\\n        max_position_embeddings=cfg[\\\"context_length\\\"],\\n        hidden_size=cfg[\\\"emb_dim\\\"],\\n        num_attention_heads=cfg[\\\"n_heads\\\"],\\n        num_hidden_layers=cfg[\\\"n_layers\\\"],\\n        intermediate_size=cfg[\\\"hidden_dim\\\"],\\n        head_dim=cfg[\\\"head_dim\\\"],\\n        num_key_value_heads=cfg[\\\"n_kv_groups\\\"],\\n        rope_theta=cfg[\\\"rope_base\\\"],\\n        rope_local_base_freq=cfg[\\\"rope_local_base\\\"],\\n        layer_types=cfg[\\\"layer_types\\\"],\\n        sliding_window=cfg[\\\"sliding_window\\\"],\\n        tie_word_embeddings=False,\\n        attn_implementation=\\\"eager\\\",\\n        torch_dtype=torch.float32,\\n        query_pre_attn_scalar=cfg[\\\"query_pre_attn_scalar\\\"],\\n        rope_scaling={\\\"rope_type\\\": \\\"default\\\"},\\n        ignore_keys_at_rope_validation={\\\"full_attention\\\", \\\"sliding_attention\\\"},\\n    )\\n    hf_model = Gemma3ForCausalLM(hf_cfg)\\n\\n    hf_state = hf_model.state_dict()\\n    param_config = {\\\"n_layers\\\": cfg[\\\"n_layers\\\"], \\\"hidden_dim\\\": cfg[\\\"hidden_dim\\\"]}\\n    import_notebook_defs.load_weights_into_gemma(model, param_config, hf_state)\\n\\n    x = torch.randint(0, cfg[\\\"vocab_size\\\"], (2, cfg[\\\"context_length\\\"]), dtype=torch.long)\\n    ours_logits = model(x)\\n    theirs_logits = hf_model(x).logits\\n    torch.testing.assert_close(ours_logits, theirs_logits, rtol=1e-5, atol=1e-5)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/12_gemma3/tests/test_gemma3_nb.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"011c32ba81ef49f3ce712037f7a19c97b3d9aa4f61de56329b45b1f6877c4383\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport importlib\\nfrom pathlib import Path\\n\\nimport pytest\\nimport torch\\n\\nfrom llms_from_scratch.utils import import_definitions_from_notebook\\n\\n\\ntransformers_installed = importlib.util.find_spec(\\\"transformers\\\") is not None\\n\\n\\n@pytest.fixture\\ndef import_notebook_defs():\\n    nb_dir = Path(__file__).resolve().parents[1]\\n    mod = import_definitions_from_notebook(nb_dir, \\\"standalone-gemma3.ipynb\\\")\\n    return mod\\n\\n\\n@pytest.fixture\\ndef dummy_input():\\n    torch.manual_seed(123)\\n    return torch.randint(0, 100, (1, 8))  # batch size 1, seq length 8\\n\\n\\n@pytest.fixture\\ndef dummy_cfg_base():\\n    return {\\n        \\\"vocab_size\\\": 100,\\n        \\\"emb_dim\\\": 32,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"n_layers\\\": 2,\\n        \\\"n_heads\\\": 4,\\n        \\\"head_dim\\\": 8,\\n        \\\"n_kv_groups\\\": 1,\\n        \\\"qk_norm\\\": True,                # Gemma3 uses q/k RMSNorm\\n        \\\"dtype\\\": torch.float32,\\n        \\\"rope_base\\\": 1_000_000.0,       # global RoPE base\\n        \\\"rope_local_base\\\": 10_000.0,    # local RoPE base (unused in these tests)\\n        \\\"context_length\\\": 64,\\n        \\\"sliding_window\\\": 16,\\n        \\\"layer_types\\\": [\\\"full_attention\\\", \\\"full_attention\\\"],\\n        \\\"query_pre_attn_scalar\\\": 256,\\n    }\\n\\n\\n@torch.inference_mode()\\ndef test_dummy_gemma3_forward(dummy_cfg_base, dummy_input, import_notebook_defs):\\n    torch.manual_seed(123)\\n    model = import_notebook_defs.Gemma3Model(dummy_cfg_base)\\n    out = model(dummy_input)\\n    assert out.shape == (1, dummy_input.size(1), dummy_cfg_base[\\\"vocab_size\\\"])\\n\\n\\n@torch.inference_mode()\\n@pytest.mark.skipif(not transformers_installed, reason=\\\"transformers not installed\\\")\\ndef test_gemma3_base_equivalence_with_transformers(import_notebook_defs):\\n    from transformers import Gemma3TextConfig, Gemma3ForCausalLM\\n\\n    # Tiny config so the test is fast\\n    cfg = {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"head_dim\\\": 8,\\n        \\\"qk_norm\\\": True,\\n        \\\"n_kv_groups\\\": 2,\\n        \\\"rope_base\\\": 1_000_000.0,\\n        \\\"rope_local_base\\\": 10_000.0,\\n        \\\"sliding_window\\\": 4,\\n        \\\"layer_types\\\": [\\\"full_attention\\\", \\\"full_attention\\\"],\\n        \\\"dtype\\\": torch.float32,\\n        \\\"query_pre_attn_scalar\\\": 256,\\n    }\\n    model = import_notebook_defs.Gemma3Model(cfg)\\n\\n    hf_cfg = Gemma3TextConfig(\\n        vocab_size=cfg[\\\"vocab_size\\\"],\\n        max_position_embeddings=cfg[\\\"context_length\\\"],\\n        hidden_size=cfg[\\\"emb_dim\\\"],\\n        num_attention_heads=cfg[\\\"n_heads\\\"],\\n        num_hidden_layers=cfg[\\\"n_layers\\\"],\\n        intermediate_size=cfg[\\\"hidden_dim\\\"],\\n        head_dim=cfg[\\\"head_dim\\\"],\\n        num_key_value_heads=cfg[\\\"n_kv_groups\\\"],\\n        rope_theta=cfg[\\\"rope_base\\\"],\\n        rope_local_base_freq=cfg[\\\"rope_local_base\\\"],\\n        layer_types=cfg[\\\"layer_types\\\"],\\n        sliding_window=cfg[\\\"sliding_window\\\"],\\n        tie_word_embeddings=False,\\n        attn_implementation=\\\"eager\\\",\\n        torch_dtype=torch.float32,\\n        query_pre_attn_scalar=cfg[\\\"query_pre_attn_scalar\\\"],\\n        rope_scaling={\\\"rope_type\\\": \\\"default\\\"},\\n        ignore_keys_at_rope_validation={\\\"full_attention\\\", \\\"sliding_attention\\\"},\\n    )\\n    hf_model = Gemma3ForCausalLM(hf_cfg)\\n\\n    hf_state = hf_model.state_dict()\\n    param_config = {\\\"n_layers\\\": cfg[\\\"n_layers\\\"], \\\"hidden_dim\\\": cfg[\\\"hidden_dim\\\"]}\\n    import_notebook_defs.load_weights_into_gemma(model, param_config, hf_state)\\n\\n    x = torch.randint(0, cfg[\\\"vocab_size\\\"], (2, cfg[\\\"context_length\\\"]), dtype=torch.long)\\n    ours_logits = model(x)\\n    theirs_logits = hf_model(x).logits\\n    torch.testing.assert_close(ours_logits, theirs_logits, rtol=1e-5, atol=1e-5)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/13_olmo3/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d7e2762a926498e0a315eb0e345aad271cabfb511ac4f287d48197782afcca73\",\"content\":\"# Olmo 3 7B and 32B From Scratch\\n\\nThis [standalone-olmo3.ipynb](standalone-olmo3.ipynb) Jupyter notebook in this folder contains a from-scratch implementation of Olmo 3 7B and 32B and requires about 13 GB of RAM to run. \\n\\nThe alternative [standalone-olmo3-plus-kvcache.ipynb](standalone-olmo3-plus-kv-cache.ipynb) notebook adds a KV cache for better runtime performance (but adds more code complexity). To learn more about KV caching, see my [Understanding and Coding the KV Cache in LLMs from Scratch](https://magazine.sebastianraschka.com/p/coding-the-kv-cache-in-llms) article.\\n\\nBelow is a side-by-side comparison with Qwen3 as a reference model; if you are interested in the Qwen3 0.6B standalone notebook, you can find it [here](../11_qwen3).\\n\\n<br>\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/olmo3/olmo3-7B.webp?1\\\">\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/olmo3/olmo3-32B.webp?1\\\">\\n\\nOlmo 3 also comes in different flavors, as shown below (the architecture is the same, only the training pipeline differs):\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/olmo3/olmo3-pipeline.webp?1\\\">\\n\\n\\n&nbsp;\\n## How does Olmo 3 compare to Qwen3\\n\\nFocusing on the architecture, not the training details, this section provides a brief comparison to Qwen3.\\n\\n\\nThe 7B model:\\n\\n1. As we can see in the figures above, the Olmo 3 architecture is relatively similar to Qwen3. However, it's worth noting that this is essentially likely inspired by the Olmo 2 predecessor, not Qwen3. \\n\\n2) Similar to Olmo 2, Olmo 3 still uses a post-norm flavor instead of pre-norm, as they found in the Olmo 2 paper that it stabilizes the training.\\n\\n3) Interestingly, the 7B model still uses multi-head attention similar to Olmo 2. \\nHowever, to make things more efficient and reduce the KV cache size, they now use sliding-window attention (e.g., similar to Gemma 3).\\n\\nNext, the 32B model:\\n\\n4) Overall, it's the same architecture but just scaled up. Also, the proportions (e.g., going from the input to the intermediate size in the feed-forward layer, and so on) roughly match the ones in Qwen3. \\n\\n5) My guess is the architecture was initially somewhat smaller than Qwen3 due to the smaller vocabulary, and they then scaled up the intermediate size expansion from 5x in Qwen3 to 5.4 in Olmo 3 to have a 32B model for a direct comparison. \\n\\n6) Also, note that the 32B model (finally!) uses grouped query attention.\\n\\n\\n\\n\\n\\n<br>\\n\\nTo learn more about the architecture differences and read about comparisons with other architectures, see my [The Big LLM Architecture Comparison: From DeepSeek-V3 to Kimi K2: A Look At Modern LLM Architecture Design](https://magazine.sebastianraschka.com/p/the-big-llm-architecture-comparison) article.\\n\\n\\n\\n\\n\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch05/13_olmo3/tests/olmo3_layer_debugger.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6f7f8b3d4f8fa164e04c7a688fd077f5cf764ed6ce8c65b63b2294071a9ef4b8\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport importlib\\nfrom pathlib import Path\\n\\nimport torch\\n\\nfrom llms_from_scratch.utils import import_definitions_from_notebook\\n\\ntry:\\n    from transformers import Olmo3Config, Olmo3ForCausalLM\\nexcept ImportError:\\n    Olmo3Config = None\\n    Olmo3ForCausalLM = None\\n\\n\\ndef tiny_debug_config():\\n    return {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"head_dim\\\": 8,\\n        \\\"qk_norm\\\": True,\\n        \\\"n_kv_heads\\\": 2,\\n        \\\"sliding_window\\\": 4,\\n        \\\"layer_types\\\": [\\\"full_attention\\\", \\\"full_attention\\\"],\\n        \\\"dtype\\\": torch.float32,\\n        \\\"query_pre_attn_scalar\\\": 256,\\n        \\\"attention_bias\\\": False,\\n        \\\"rms_norm_eps\\\": 1e-6,\\n        \\\"rope_base\\\": 1_000_000.0,\\n        \\\"rope_attention_factor\\\": 1.0,\\n        \\\"rope_type\\\": \\\"default\\\",\\n        \\\"rope_factor\\\": 1.0,\\n        \\\"rope_orig_max\\\": 8,\\n        \\\"rope_local_base\\\": 10_000.0,\\n    }\\n\\n\\ndef yarn_debug_config():\\n    return {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"hidden_dim\\\": 64,\\n        \\\"head_dim\\\": 8,\\n        \\\"qk_norm\\\": True,\\n        \\\"n_kv_heads\\\": 2,\\n        \\\"sliding_window\\\": 4,\\n        \\\"layer_types\\\": [\\\"full_attention\\\", \\\"full_attention\\\"],\\n        \\\"dtype\\\": torch.float32,\\n        \\\"query_pre_attn_scalar\\\": 256,\\n        \\\"attention_bias\\\": False,\\n        \\\"rms_norm_eps\\\": 1e-6,\\n        \\\"rope_base\\\": 500_000.0,\\n        \\\"rope_attention_factor\\\": 1.2079441541679836,\\n        \\\"rope_type\\\": \\\"yarn\\\",\\n        \\\"rope_factor\\\": 8.0,\\n        \\\"rope_orig_max\\\": 8192,\\n        \\\"beta_fast\\\": 32.0,\\n        \\\"beta_slow\\\": 1.0,\\n        \\\"rope_local_base\\\": 10_000.0,\\n    }\\n\\n\\ndef _hf_config_from_dict(cfg):\\n    if Olmo3Config is None:\\n        raise ImportError(\\\"transformers is required for the Olmo-3 debugger.\\\")\\n\\n    rope_type = cfg.get(\\\"rope_type\\\", \\\"default\\\")\\n    rope_scaling = {\\\"rope_type\\\": rope_type}\\n    if rope_type == \\\"yarn\\\":\\n        rope_scaling.update(\\n            {\\n                \\\"attention_factor\\\": cfg.get(\\\"rope_attention_factor\\\", 1.0),\\n                \\\"beta_fast\\\": cfg.get(\\\"beta_fast\\\", 32.0),\\n                \\\"beta_slow\\\": cfg.get(\\\"beta_slow\\\", 1.0),\\n                \\\"factor\\\": cfg.get(\\\"rope_factor\\\", 1.0),\\n                \\\"original_max_position_embeddings\\\": cfg.get(\\\"rope_orig_max\\\", 8192),\\n            }\\n        )\\n\\n    return Olmo3Config(\\n        vocab_size=cfg[\\\"vocab_size\\\"],\\n        max_position_embeddings=cfg[\\\"context_length\\\"],\\n        hidden_size=cfg[\\\"emb_dim\\\"],\\n        num_attention_heads=cfg[\\\"n_heads\\\"],\\n        num_hidden_layers=cfg[\\\"n_layers\\\"],\\n        intermediate_size=cfg[\\\"hidden_dim\\\"],\\n        head_dim=cfg[\\\"head_dim\\\"],\\n        num_key_value_heads=cfg[\\\"n_kv_heads\\\"],\\n        rope_theta=cfg[\\\"rope_base\\\"],\\n        rope_local_base_freq=cfg.get(\\\"rope_local_base\\\", 10_000.0),\\n        layer_types=cfg[\\\"layer_types\\\"],\\n        sliding_window=cfg[\\\"sliding_window\\\"],\\n        tie_word_embeddings=False,\\n        attn_implementation=\\\"eager\\\",\\n        torch_dtype=cfg.get(\\\"dtype\\\", torch.float32),\\n        query_pre_attn_scalar=cfg.get(\\\"query_pre_attn_scalar\\\", 256),\\n        rope_scaling=rope_scaling,\\n        qk_norm=cfg.get(\\\"qk_norm\\\", False),\\n        rms_norm_eps=cfg.get(\\\"rms_norm_eps\\\", 1e-5),\\n    )\\n\\n\\ndef load_notebook_defs(nb_name=\\\"standalone-olmo3.ipynb\\\"):\\n    nb_dir = Path(__file__).resolve().parents[1]\\n    return import_definitions_from_notebook(nb_dir, nb_name)\\n\\n\\ndef build_olmo3_pair(import_notebook_defs, cfg, hf_checkpoint=None):\\n    if Olmo3ForCausalLM is None:\\n        raise ImportError(\\\"transformers is required for the Olmo-3 debugger.\\\")\\n\\n    ours = import_notebook_defs.Olmo3Model(cfg)\\n    hf_cfg = _hf_config_from_dict(cfg)\\n\\n    if hf_checkpoint:\\n        hf_model = Olmo3ForCausalLM.from_pretrained(\\n            hf_checkpoint,\\n            torch_dtype=cfg.get(\\\"dtype\\\", torch.float32),\\n            attn_implementation=\\\"eager\\\",\\n        )\\n    else:\\n        hf_model = Olmo3ForCausalLM(hf_cfg)\\n\\n    param_config = {\\\"n_layers\\\": cfg[\\\"n_layers\\\"], \\\"hidden_dim\\\": cfg[\\\"hidden_dim\\\"]}\\n    import_notebook_defs.load_weights_into_olmo(ours, param_config, hf_model.state_dict())\\n\\n    ours.eval()\\n    hf_model.eval()\\n    return ours, hf_model\\n\\n\\ndef _attach_debug_hooks(model, is_hf):\\n    traces = {}\\n    handles = []\\n\\n    def hook(name):\\n        def _record(_, __, output):\\n            traces[name] = output.detach().to(torch.float32).cpu()\\n        return _record\\n\\n    if is_hf:\\n        core = model.model\\n        handles.append(core.embed_tokens.register_forward_hook(hook(\\\"embedding\\\")))\\n        for idx, layer in enumerate(core.layers):\\n            handles.append(layer.register_forward_hook(hook(f\\\"block_{idx}\\\")))\\n        handles.append(core.norm.register_forward_hook(hook(\\\"final_norm\\\")))\\n        handles.append(model.lm_head.register_forward_hook(hook(\\\"logits";
